function ensureAppMountElement(html) {
  let outputHtml = String(html || "");
  if (/\sid=(["'])app\1/i.test(outputHtml)) {
    return outputHtml.replace(
      /<div\b([^>]*\sid=(["'])app\2[^>]*)>/i,
      (match, attrs) => /data-st-hypnoos-app-root\s*=/.test(match)
        ? match
        : `<div${attrs} data-st-hypnoos-app-root="true">`
    );
  }
  if (/<body\b[^>]*>/i.test(outputHtml)) {
    return outputHtml.replace(/<body([^>]*)>/i, `<body$1><div id="app" data-st-hypnoos-app-root="true"></div>`);
  }
  return `${outputHtml}<div id="app" data-st-hypnoos-app-root="true"></div>`;
}

function moveHeadScriptsAfterApp(html) {
  let outputHtml = String(html || "");
  const headMatch = outputHtml.match(/<head\b[^>]*>([\s\S]*?)<\/head>/i);
  if (!headMatch) return outputHtml;
  const scripts = [];
  const nextHeadInner = headMatch[1].replace(/<script\b[\s\S]*?<\/script>/gi, (script) => {
    scripts.push(script);
    return "";
  });
  if (!scripts.length) return outputHtml;
  outputHtml = outputHtml.replace(headMatch[0], headMatch[0].replace(headMatch[1], nextHeadInner));
  outputHtml = ensureAppMountElement(outputHtml);
  const appPattern = /(<body\b[^>]*>\s*<div\s+id=(["'])app\2(?:\s+data-st-hypnoos-app-root=(["'])true\3)?><\/div>)/i;
  if (appPattern.test(outputHtml)) {
    return outputHtml.replace(appPattern, (match) => `${match}${scripts.join("")}`);
  }
  return outputHtml.replace(/<body([^>]*)>/i, (_match, attrs) => `<body${attrs}><div id="app" data-st-hypnoos-app-root="true"></div>${scripts.join("")}`);
}

