function extractBalancedObjectLiteral(text, marker) {
  const markerIndex = text.indexOf(marker);
  if (markerIndex < 0) return "";
  const objectStart = text.indexOf("{", markerIndex);
  if (objectStart < 0) return "";
  let depth = 0;
  let quote = "";
  let escaped = false;
  for (let i = objectStart; i < text.length; i += 1) {
    const ch = text[i];
    if (quote) {
      if (escaped) {
        escaped = false;
        continue;
      }
      if (ch === "\\") {
        escaped = true;
        continue;
      }
      if (ch === quote) quote = "";
      continue;
    }
    if (ch === "\"" || ch === "'" || ch === "`") {
      quote = ch;
      continue;
    }
    if (ch === "{") depth += 1;
    if (ch === "}") {
      depth -= 1;
      if (depth === 0) return text.slice(objectStart, i + 1);
    }
  }
  return "";
}

function cleanMchanSeedText(value, fallback = "") {
  const text = String(value || "").trim();
  return (text || fallback).replaceAll("MC点", "MC能量");
}

function jsonForInlineScript(value) {
  return JSON.stringify(value)
    .replace(/<\//g, "<\\/")
    .replace(/\u2028/g, "\\u2028")
    .replace(/\u2029/g, "\\u2029");
}

function encounterPackageRelativeAssetPath(source, value) {
  const text = String(value || "").trim();
  if (!text || /^(?:https?:|data:|blob:)/i.test(text)) return text;
  const normalized = text.replace(/\\/g, "/").replace(/^\/+/, "");
  if (normalized.startsWith("encounter/")) return normalized;
  const assetRoot = "public/frontends/hypnosis-app/assets/";
  const sourceDir = path.dirname(source).replace(/\\/g, "/");
  if (!sourceDir.startsWith(assetRoot)) return normalized;
  const packageDir = sourceDir.slice(assetRoot.length).replace(/^\/+|\/+$/g, "");
  return packageDir ? (packageDir + "/" + normalized).replace(/\/+/g, "/") : normalized;
}

function encounterStablePackageIdFromSource(source) {
  const dir = path.basename(path.dirname(String(source || ""))).trim();
  return dir ? dir.toLowerCase().replace(/[^a-z0-9\u4e00-\u9fa5]+/g, "-").replace(/^-+|-+$/g, "") + "-role-pack" : "";
}

function normalizeEncounterBuiltinPackageAssetPaths(pkg, source) {
  if (!pkg || typeof pkg !== "object" || Array.isArray(pkg)) return pkg;
  const next = { ...pkg };
  [
    "encounterPrompt",
    "roleEncounterPrompt",
    "appearancePrompt",
    "storyPrompt",
    "prompt",
    "出场提示词",
    "角色出场提示词",
    "AI出场提示词",
    "邂逅提示词",
    "AI邂逅提示词"
  ].forEach((key) => delete next[key]);
  if (!next.id && !next.packageId) next.id = encounterStablePackageIdFromSource(source);
  if (next.cover) next.cover = encounterPackageRelativeAssetPath(source, next.cover);
  if (next.coverDataUrl) next.coverDataUrl = encounterPackageRelativeAssetPath(source, next.coverDataUrl);
  if (Array.isArray(next.roles)) {
    next.roles = next.roles.map((role) => {
      if (!role || typeof role !== "object" || Array.isArray(role)) return role;
      const roleNext = { ...role };
      if (roleNext.image) roleNext.image = encounterPackageRelativeAssetPath(source, roleNext.image);
      if (roleNext.imageDataUrl) roleNext.imageDataUrl = encounterPackageRelativeAssetPath(source, roleNext.imageDataUrl);
      if (Array.isArray(roleNext.images)) {
        roleNext.images = roleNext.images.map((image) => image ? encounterPackageRelativeAssetPath(source, image) : "");
      }
      if (Array.isArray(roleNext.imageDataUrls)) {
        roleNext.imageDataUrls = roleNext.imageDataUrls.map((image) => image ? encounterPackageRelativeAssetPath(source, image) : "");
      }
      return roleNext;
    });
  }
  return next;
}

async function loadEncounterBuiltinPackages() {
  const preserveAuthoredAgeText = (value) => {
    if (typeof value === "string") return value
      .replaceAll("var readOnlyKeys = ['_年龄', '_事件记录', '至关重要记忆'];", "var readOnlyKeys = ['_事件记录', '至关重要记忆'];")
      .replaceAll("readOnlyKeys.indexOf(key) >= 0 || String(key).charAt(0) === '_'", "readOnlyKeys.indexOf(key) >= 0 || (String(key).charAt(0) === '_' && key !== '_年龄')")
      .replaceAll("信息（_年龄为" + "2024" + "基准年龄）", "信息（年龄字段按原值展示）");
    if (Array.isArray(value)) return value.map(preserveAuthoredAgeText);
    if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, preserveAuthoredAgeText(item)]));
    return value;
  };
  const packages = [];
  for (const source of ENCOUNTER_BUILTIN_PACKAGE_SOURCES) {
    try {
      const parsed = preserveAuthoredAgeText(normalizeEncounterBuiltinPackageAssetPaths(JSON.parse(await readFile(source, "utf8")), source));
      packages.push(parsed);
    } catch (error) {
      console.warn(`Skipped encounter builtin package ${source}: ${error?.message || error}`);
    }
  }
  return packages;
}

