            来源: "催眠APP",
            操作: "资源兑换",
            项目: "提升MC能量上限",
            暂存摘要: "提升MC能量上限｜MC能量上限 +" + qty + "点｜资金 ¥" + cost.toLocaleString(),
            购买数量: qty,
            数量: qty + "点",
            兑换规则: "100円 = 1点MC能量上限",
            消耗零花钱: cost,
            消耗资源: "资金 ¥" + cost.toLocaleString(),
