  function timetableStorageKey() {
    try {
      return ST_TIMETABLE_STORAGE_PREFIX + ":" + graphCommonScopeKey();
    } catch {
      return ST_TIMETABLE_STORAGE_PREFIX + ":global";
    }
  }

  function timetableDescriptionStorageKey() {
    try {
      return ST_TIMETABLE_DESC_STORAGE_PREFIX + ":" + graphCommonScopeKey();
    } catch {
      return ST_TIMETABLE_DESC_STORAGE_PREFIX + ":global";
    }
  }

  function normalizeWeeklyTimetable(source = ST_WEEKLY_TIMETABLE) {
    const table = {};
    for (let day = 1; day <= 5; day += 1) {
      const sourceRow = Array.isArray(source?.[day]) ? source[day] : Array.isArray(source?.[String(day)]) ? source[String(day)] : [];
      const defaultRow = ST_WEEKLY_TIMETABLE[day] || [];
      table[day] = ST_CLASS_PERIODS.map((period, index) => {
        const value = String(sourceRow[index] ?? defaultRow[index] ?? "自习").trim();
        return value || "自习";
      });
    }
    return table;
  }

  function readWeeklyTimetable() {
    try {
      const parsed = JSON.parse(localStorage.getItem(timetableStorageKey()) || "null");
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return normalizeWeeklyTimetable(parsed);
    } catch {}
    return normalizeWeeklyTimetable(ST_WEEKLY_TIMETABLE);
  }

  function normalizeWeeklyTimetableDescriptions(source = {}) {
    const descriptions = {};
    for (let day = 1; day <= 5; day += 1) {
      const sourceRow = Array.isArray(source?.[day]) ? source[day] : Array.isArray(source?.[String(day)]) ? source[String(day)] : [];
      descriptions[day] = ST_CLASS_PERIODS.map((period, index) => String(sourceRow[index] ?? "").trim());
    }
    return descriptions;
  }

  function readWeeklyTimetableDescriptions() {
    try {
      const parsed = JSON.parse(localStorage.getItem(timetableDescriptionStorageKey()) || "null");
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return normalizeWeeklyTimetableDescriptions(parsed);
    } catch {}
    return normalizeWeeklyTimetableDescriptions({});
  }

  function writeWeeklyTimetableDescriptions(descriptions) {
    try {
      localStorage.setItem(timetableDescriptionStorageKey(), JSON.stringify(normalizeWeeklyTimetableDescriptions(descriptions)));
      globalThis.__ST_HYPNOOS_DAILY_SCHEDULE_SYNC_SIGNATURE__ = "";
      scheduleReadonlyScheduleSyncForCurrentClock();
      return true;
    } catch {
      return false;
    }
  }

	  function writeWeeklyTimetable(table) {
	    try {
	      localStorage.setItem(timetableStorageKey(), JSON.stringify(normalizeWeeklyTimetable(table)));
	      globalThis.__ST_HYPNOOS_DAILY_SCHEDULE_SYNC_SIGNATURE__ = "";
	      scheduleReadonlyScheduleSyncForCurrentClock();
	      return true;
	    } catch {
	      return false;
	    }
	  }

	  function timetableStorageSnapshot() {
	    try {
	      return {
	        table: localStorage.getItem(timetableStorageKey()),
	        descriptions: localStorage.getItem(timetableDescriptionStorageKey())
	      };
	    } catch {
	      return null;
	    }
	  }

	  function restoreTimetableStorageSnapshot(snapshot) {
	    if (!snapshot) return false;
	    try {
	      if (snapshot.table === null) localStorage.removeItem(timetableStorageKey());
	      else localStorage.setItem(timetableStorageKey(), snapshot.table);
	      if (snapshot.descriptions === null) localStorage.removeItem(timetableDescriptionStorageKey());
	      else localStorage.setItem(timetableDescriptionStorageKey(), snapshot.descriptions);
	      globalThis.__ST_HYPNOOS_DAILY_SCHEDULE_SYNC_SIGNATURE__ = "";
	      return true;
	    } catch {
	      return false;
	    }
	  }

	  function writeWeeklyTimetableState(table, descriptions, { scheduleSync = true } = {}) {
	    const before = timetableStorageSnapshot();
	    if (!before) return { ok: false, reason: "课程表本地存储不可用。" };
	    const normalizedTable = normalizeWeeklyTimetable(table);
	    const normalizedDescriptions = normalizeWeeklyTimetableDescriptions(descriptions);
	    try {
	      const tableText = JSON.stringify(normalizedTable);
	      const descriptionText = JSON.stringify(normalizedDescriptions);
	      localStorage.setItem(timetableStorageKey(), tableText);
	      localStorage.setItem(timetableDescriptionStorageKey(), descriptionText);
	      if (localStorage.getItem(timetableStorageKey()) !== tableText || localStorage.getItem(timetableDescriptionStorageKey()) !== descriptionText) {
	        throw new Error("课程表本地读回不一致");
	      }
	      globalThis.__ST_HYPNOOS_DAILY_SCHEDULE_SYNC_SIGNATURE__ = "";
	      if (scheduleSync) scheduleReadonlyScheduleSyncForCurrentClock();
	      return { ok: true, before, table: normalizedTable, descriptions: normalizedDescriptions };
	    } catch {
	      restoreTimetableStorageSnapshot(before);
	      return { ok: false, reason: "课程表本地保存失败，未消耗魔改券。" };
	    }
	  }

	  function resetWeeklyTimetable() {
	    try {
	      localStorage.removeItem(timetableStorageKey());
	      localStorage.removeItem(timetableDescriptionStorageKey());
	      globalThis.__ST_HYPNOOS_DAILY_SCHEDULE_SYNC_SIGNATURE__ = "";
	      scheduleReadonlyScheduleSyncForCurrentClock();
	    } catch {}
	  }

	  let readonlyScheduleSyncTimer = 0;
	  function scheduleReadonlyScheduleSyncForCurrentClock(delay = 220) {
	    try {
	      if (readonlyScheduleSyncTimer) window.clearTimeout(readonlyScheduleSyncTimer);
	      readonlyScheduleSyncTimer = window.setTimeout(() => {
	        readonlyScheduleSyncTimer = 0;
	        syncReadonlyScheduleVariablesForCurrentClock().catch((err) => {
	          console.warn("[HypnoOS] 同步只读课程表变量失败", err);
	        });
	      }, Math.max(0, Number(delay) || 0));
	    } catch {}
	  }

	  async function syncReadonlyScheduleVariablesForCurrentClock() {
	    if (typeof rewardApplySystemMutation !== "function") return false;
	    const result = await rewardApplySystemMutation((system) => {
	      const dateText = systemStoryDateText(system);
	      const timeText = storyTimeOnly(system["当前时间"], "12:00");
	      const before = JSON.stringify([
	        system["_当前周几"],
	        system["_当前日程"],
	        system["_当前特殊日期"],
		        system["_课程表"]
	      ]);
	      applyReadonlySchedule(system, dateText, timeText);
	      const after = JSON.stringify([
	        system["_当前周几"],
	        system["_当前日程"],
	        system["_当前特殊日期"],
		        system["_课程表"]
	      ]);
	      return before === after
	        ? { ok: false, message: "只读课程表变量无需同步。" }
	        : { ok: true, message: "已同步只读课程表变量。" };
		    });
		    return Boolean(result?.ok);
		  }
		  window.setTimeout(() => scheduleReadonlyScheduleSyncForCurrentClock(0), 0);

	  function weeklyTimetableSubject(weekdayIndex, periodIndex, table = readWeeklyTimetable()) {
    const day = Number(weekdayIndex);
    const period = Math.max(1, Math.floor(Number(periodIndex) || 1));
    return String(table?.[day]?.[period - 1] || ST_WEEKLY_TIMETABLE[day]?.[period - 1] || "自习").trim() || "自习";
  }

  function weeklyTimetableOriginalSubject(weekdayIndex, periodIndex) {
    const day = Number(weekdayIndex);
    const period = Math.max(1, Math.floor(Number(periodIndex) || 1));
    return String(ST_WEEKLY_TIMETABLE[day]?.[period - 1] || "自习").trim() || "自习";
  }

  function defaultCourseDescription(subject) {
    const text = String(subject || "自习").trim() || "自习";
    if (ST_COURSE_DESCRIPTIONS[text]) return ST_COURSE_DESCRIPTIONS[text];
    if (/数学|算数|代数|几何|微积分|统计/.test(text)) return text + "课会围绕公式推导、例题演算和板书订正推进，教师通常要求写清步骤，并让学生说明每一步为什么成立。";
    if (/英语|英文|外语|法语|德语|中文|国语|日语|韩语/.test(text)) return text + "课会结合阅读、听力、写作和口语练习，课堂重点是词句理解、表达准确度和情境对话。";
    if (/历史|史|地理|公民|政治|伦理|社会/.test(text)) return text + "课会围绕事件脉络、人物关系、地图或制度变化展开，要求学生整理关键词、因果关系和自己的简短看法。";
    if (/物理|化学|生物|科学|理科|实验/.test(text)) return text + "课会结合概念讲解、图表整理和实验或演示，强调现象、条件、结论之间的对应关系。";
    if (/体育|球|游泳|田径|剑道|柔道|舞蹈/.test(text)) return text + "课以热身、分组练习和动作修正为主，重点是安全、体能消耗、姿势节奏和同伴配合。";
    if (/音乐|美术|书道|艺术|绘画|设计/.test(text)) return text + "课会安排鉴赏、基础技法和个人创作练习，教师更看重完成过程、表达意图和作品细节。";
    if (/家庭|料理|家政|手工|技术|信息|电脑|编程/.test(text)) return text + "课偏实践应用，会让学生完成小型任务、记录步骤并提交成果，课堂气氛比主科轻松但要求细心。";
    if (/班会|探究|综合|社团|自习/.test(text)) return text + "时间主要用于通知、讨论、资料整理或自主推进任务，内容会随班级事务和当天剧情自然变化。";
    return text + "课会按该科目的课堂目标展开：教师先说明当天主题，再安排练习、讨论或小测，让学生在当节课内留下可被剧情使用的具体行动。";
  }

  function weeklyTimetableOriginalDescription(weekdayIndex, periodIndex) {
    return defaultCourseDescription(weeklyTimetableOriginalSubject(weekdayIndex, periodIndex));
  }

  function weeklyTimetableDescription(weekdayIndex, periodIndex, table = readWeeklyTimetable(), descriptions = readWeeklyTimetableDescriptions()) {
    const day = Number(weekdayIndex);
    const period = Math.max(1, Math.floor(Number(periodIndex) || 1));
    const currentSubject = weeklyTimetableSubject(day, period, table);
    if (weeklyTimetableIsModified(day, period, table, descriptions)) {
      const stored = String(descriptions?.[day]?.[period - 1] ?? descriptions?.[String(day)]?.[period - 1] ?? "").trim();
      if (stored) return stored;
    }
    return defaultCourseDescription(currentSubject);
  }

	  function persistWeeklyTimetableFromReadonlyVariables(system = getSystemState()) {
	    try {
      const fallbackWeekday = normalizeWeekdayText(system?.["_当前周几"] || system?.["当前周几"]);
      const fallbackDay = ST_WEEKDAY_INDEX[fallbackWeekday] ?? 0;
	      const rows = normalizeReadonlyTimetableRows(system?.["_课程表"]);
      if (!rows.length) return false;
      const table = readWeeklyTimetable();
      const descriptions = readWeeklyTimetableDescriptions();
      let changed = false;
      rows.forEach((row, index) => {
        if (!row || typeof row !== "object" || Array.isArray(row)) return;
        const day = fallbackDay;
        if (day < 1 || day > 5) return;
        table[day] = Array.isArray(table[day]) ? table[day].slice() : normalizeWeeklyTimetable()[day].slice();
        descriptions[day] = Array.isArray(descriptions[day]) ? descriptions[day].slice() : normalizeWeeklyTimetableDescriptions()[day].slice();
        const label = String(row["课节"] ?? row.period ?? "").trim();
        const match = label.match(/(\\d+)/);
        const period = match ? Number(match[1]) : (index + 1);
        if (period < 1 || period > ST_CLASS_PERIODS.length) return;
        const isModified = Boolean(row["是否魔改"] !== undefined ? row["是否魔改"] : row.modified);
        const modifiedSubject = String(row["魔改课程"] ?? row.modifiedSubject ?? "").trim();
        const modifiedDescription = String(row["魔改课程描述"] ?? row.modifiedDescription ?? "").trim();
        const originalDescription = String(row["原课程描述"] ?? weeklyTimetableOriginalDescription(day, period)).trim()
          || weeklyTimetableOriginalDescription(day, period);
        if (!isModified || !modifiedSubject) return;
        if (table[day][period - 1] !== modifiedSubject) {
          table[day][period - 1] = modifiedSubject;
          changed = true;
        }
        if (modifiedDescription && modifiedDescription !== originalDescription && descriptions[day][period - 1] !== modifiedDescription) {
          descriptions[day][period - 1] = modifiedDescription;
          changed = true;
        }
      });
      if (!changed) return false;
      localStorage.setItem(timetableStorageKey(), JSON.stringify(normalizeWeeklyTimetable(table)));
      localStorage.setItem(timetableDescriptionStorageKey(), JSON.stringify(normalizeWeeklyTimetableDescriptions(descriptions)));
      globalThis.__ST_HYPNOOS_DAILY_SCHEDULE_SYNC_SIGNATURE__ = "";
      scheduleReadonlyScheduleSyncForCurrentClock();
      return true;
    } catch {
      return false;
    }
  }

	  function weeklyTimetableIsModified(weekdayIndex, periodIndex, table = readWeeklyTimetable(), descriptions = readWeeklyTimetableDescriptions()) {
	    const day = Number(weekdayIndex);
	    const period = Math.max(1, Math.floor(Number(periodIndex) || 1));
	    if (weeklyTimetableSubject(day, period, table) !== weeklyTimetableOriginalSubject(day, period)) return true;
	    const stored = String(descriptions?.[day]?.[period - 1] ?? descriptions?.[String(day)]?.[period - 1] ?? "").trim();
	    return Boolean(stored && stored !== weeklyTimetableOriginalDescription(day, period));
	  }

	  function weeklyTimetableChangeCount(table = readWeeklyTimetable(), descriptions = readWeeklyTimetableDescriptions()) {
	    let count = 0;
	    for (let day = 1; day <= 5; day += 1) {
	      for (const period of ST_CLASS_PERIODS) {
	        if (weeklyTimetableIsModified(day, period.index, table, descriptions)) count += 1;
	      }
	    }
    return count;
  }

  function timetableCurrentContext() {
    const system = getSystemState();
    const dateText = systemStoryDateText(system);
    const timeText = storyTimeOnly(system["当前时间"], "12:00");
    const parsedDate = parseStoryDate(dateText);
    const weekday = weekdayForStoryDate(dateText)
      || normalizeWeekdayText(system["_当前周几"] || system["当前周几"])
      || "";
    const activeDay = ST_WEEKDAY_INDEX[weekday] ?? 0;
    const minutes = minutesFromTimeText(timeText);
    const special = specialDayForDate(parsedDate);
    const blocksClass = specialDayBlocksClasses(special);
    const canModifyToday = Boolean(activeDay >= 1 && activeDay <= 5 && !blocksClass);
    const remainingPeriods = new Set(canModifyToday
      ? ST_CLASS_PERIODS.filter((period) => Number.isFinite(minutes) && period.end > minutes).map((period) => period.index)
      : []);
    return { system, dateText, timeText, parsedDate, weekday, activeDay, minutes, special, blocksClass, canModifyToday, remainingPeriods };
  }

  function timetableCanUseCouponForCell(day, period, context = timetableCurrentContext()) {
    return Boolean(context.canModifyToday && Number(day) === context.activeDay && context.remainingPeriods.has(Number(period)));
  }

  function timetableEditableModifiedCellCount(table = readWeeklyTimetable(), context = timetableCurrentContext()) {
    let count = 0;
    for (let day = 1; day <= 5; day += 1) {
      for (const period of ST_CLASS_PERIODS) {
        if (weeklyTimetableIsModified(day, period.index, table) && timetableCanUseCouponForCell(day, period.index, context)) count += 1;
      }
    }
    return count;
  }

  function timetableWeekdayShortName(day) {
    return ({ 1: "周一", 2: "周二", 3: "周三", 4: "周四", 5: "周五" })[Number(day)] || ("周" + day);
  }

  function timetableSelectedState(page) {
    const day = Number(page?.dataset?.timetableSelectedDay || 0);
    const period = Number(page?.dataset?.timetableSelectedPeriod || 0);
    if (!day || !period) return null;
    const periodInfo = ST_CLASS_PERIODS.find((item) => item.index === period);
    const label = timetableWeekdayShortName(day) + " " + (periodInfo?.label || (period + "限"));
    const originalSubject = weeklyTimetableOriginalSubject(day, period);
    const currentSubject = weeklyTimetableSubject(day, period);
    const isModified = weeklyTimetableIsModified(day, period);
    const currentDescription = weeklyTimetableDescription(day, period);
    const originalDescription = weeklyTimetableOriginalDescription(day, period);
    const consumeCoupon = page?.dataset?.timetableSelectedConsumeCoupon === "true";
    return { day, period, label, originalSubject, currentSubject, originalDescription, currentDescription, isModified, consumeCoupon };
  }

  function clearTimetableSelectedCell(page) {
    delete page.dataset.timetableSelectedDay;
    delete page.dataset.timetableSelectedPeriod;
    delete page.dataset.timetableSelectedConsumeCoupon;
  }

  function timetableModificationCouponCount(stat = getLatestStatDataSync()) {
    try {
      return encounterInventoryItemCount(TIMETABLE_MOD_COUPON_ITEM, stat);
    } catch {
      return 0;
    }
  }

	  function timetableOperationPayload(details = {}, beforeCount = 0) {
	    const rowIndex = Math.max(0, Math.floor(Number(details.period) || 1) - 1);
	    const rowPath = "/系统/_课程表/" + rowIndex;
	    const rowPaths = ST_TIMETABLE_ROW_KEYS.map((key) => rowPath + "/" + key);
	    const consumeCoupon = Boolean(details.consumeCoupon);
	    const frontendPaths = consumeCoupon
	      ? ["/系统/持有物品/" + TIMETABLE_MOD_COUPON_ITEM].concat(rowPaths)
	      : rowPaths;
	    return {
	      来源: "课程表",
	      操作: consumeCoupon ? "使用课程表魔改券" : "重命名已魔改课程",
	      暂存摘要: (details.label || "当前课节") + "｜" + (details.nextSubject || "魔改课程"),
	      变量处理: "前端已结算",
	      前端已写路径: frontendPaths,
	      AI不可写路径: frontendPaths,
	      AI可写路径: [],
	      不可删除: true,
	      日期: details.dateText || "",
	      星期: details.weekday || "",
	      当前时间: details.timeText || "",
	      消耗物品: consumeCoupon ? TIMETABLE_MOD_COUPON_ITEM + " x1" : "无",
	      前端写入后剩余魔改券: consumeCoupon ? Math.max(0, beforeCount - 1) : beforeCount,
	      修改范围: "永久修改本聊天周课表中的一个星期＋课节单格；选择入口仅限今天尚未结束的课节",
	      修改课节: details.label || "",
	      原课程名: details.originalSubject || "",
	      重命名前课程名: details.currentSubject || "",
	      魔改课程名: details.nextSubject || "",
	      原课程描述: details.originalDescription || "",
	      重命名前课程描述: details.currentDescription || "",
	      魔改课程描述: details.nextDescription || "",
	      魔改备注: details.nextDescription || "",
	      前端处理: "前端已在同一事务内保存课程表单格、写回/系统/_课程表并完成读回校验" + (consumeCoupon ? "，同时扣除1张课程表魔改券。" : "；本次重命名不消耗课程表魔改券。"),
	      AI执行规范: "课程表单格与课程描述均已由前端最终写入，AI不得再次扣券、扣星光点或改写任何/系统/_课程表叶。课程表魔改不是地点规则、催眠常识或角色效果，禁止写入/规则、临时催眠效果或永久催眠效果；它没有到期时间，永久作用于本聊天周课表中这个星期＋课节单格，直到用户再次修改该格。正文只承认修改后的课程安排，并按对应课节时间推进。"
	    };
	  }

	  async function restoreTimetableMvuSnapshot(candidate, snapshot) {
	    if (!candidate?.replace || !snapshot) return false;
	    try {
	      const result = candidate.replace(snapshot, candidate.option);
	      const settled = result && typeof result.then === "function" ? await result : result;
	      return settled !== false;
	    } catch {
	      return false;
	    }
	  }

	  async function commitTimetableModification(details = {}) {
	    if (!requireWritablePhoneFloor()) return { ok: false, reason: "历史楼层只读；切回当前最新楼后才能修改课程表。" };
	    const option = getCurrentVariableOption();
	    if (!option) return { ok: false, reason: "未能锁定当前楼层，课程表没有修改。" };
	    const candidate = await settingsReadMvuCandidateForOption(option, { requireReplace: true });
	    if (!candidate?.stat || !candidate?.replace) return { ok: false, reason: "MVU变量接口未就绪，课程表没有修改。" };

	    const beforeMvu = settingsClone(candidate.mvu);
	    const beforeCount = timetableModificationCouponCount(candidate.stat);
	    if (details.consumeCoupon && beforeCount < 1) return { ok: false, reason: "需要课程表魔改券，VIP6可在邂逅商店用100星光点购买。" };

	    const table = readWeeklyTimetable();
	    const descriptions = readWeeklyTimetableDescriptions();
	    const day = Math.max(1, Math.min(5, Math.floor(Number(details.day) || 1)));
	    const period = Math.max(1, Math.min(ST_CLASS_PERIODS.length, Math.floor(Number(details.period) || 1)));
	    table[day] = Array.isArray(table[day]) ? table[day].slice() : normalizeWeeklyTimetable()[day].slice();
	    descriptions[day] = Array.isArray(descriptions[day]) ? descriptions[day].slice() : normalizeWeeklyTimetableDescriptions()[day].slice();
	    table[day][period - 1] = String(details.nextSubject || "自习").trim() || "自习";
	    const nextDescription = String(details.nextDescription || "").trim() || defaultCourseDescription(table[day][period - 1]);
	    descriptions[day][period - 1] = nextDescription;

	    const localWrite = writeWeeklyTimetableState(table, descriptions, { scheduleSync: false });
	    if (!localWrite.ok) return localWrite;

	    candidate.stat["系统"] = candidate.stat["系统"] && typeof candidate.stat["系统"] === "object" && !Array.isArray(candidate.stat["系统"]) ? candidate.stat["系统"] : {};
	    if (details.consumeCoupon && !encounterConsumeInventoryItem(candidate.stat, TIMETABLE_MOD_COUPON_ITEM, 1)) {
	      restoreTimetableStorageSnapshot(localWrite.before);
	      return { ok: false, reason: "课程表魔改券扣除失败，课程表没有修改。" };
	    }
	    applyReadonlySchedule(candidate.stat["系统"], details.dateText, details.timeText);
	    const expectedRows = normalizeReadonlyTimetableRows(candidate.stat["系统"]["_课程表"]);
	    const expectedRow = expectedRows[period - 1];
	    const expectedCount = details.consumeCoupon ? Math.max(0, beforeCount - 1) : beforeCount;

	    try {
	      const result = candidate.replace(candidate.mvu, candidate.option);
	      const settled = result && typeof result.then === "function" ? await result : result;
	      if (settled === false) throw new Error("变量接口拒绝写入");
	      const readBack = await settingsReadMvuCandidateForOption(option, { requireReplace: true });
	      const actualRows = normalizeReadonlyTimetableRows(readBack?.stat?.["系统"]?.["_课程表"]);
	      const actualRow = actualRows[period - 1];
	      const rowMatches = Boolean(expectedRow && actualRow && JSON.stringify(actualRow) === JSON.stringify(expectedRow));
	      const countMatches = Boolean(readBack?.stat) && timetableModificationCouponCount(readBack.stat) === expectedCount;
	      if (!rowMatches || !countMatches) throw new Error("同楼读回不一致");
	    } catch {
	      await restoreTimetableMvuSnapshot(candidate, beforeMvu);
	      restoreTimetableStorageSnapshot(localWrite.before);
	      return { ok: false, reason: "课程表变量写回校验失败，已撤销本次修改。" };
	    }

	    const appended = await appendAppOperation(timetableOperationPayload(details, beforeCount));
	    if (!appended) {
	      await restoreTimetableMvuSnapshot(candidate, beforeMvu);
	      restoreTimetableStorageSnapshot(localWrite.before);
	      return { ok: false, reason: "日程格写入失败，已撤销课程表和魔改券变化。" };
	    }
	    globalThis.__ST_HYPNOOS_DAILY_SCHEDULE_SYNC_SIGNATURE__ = "";
	    return { ok: true, remaining: expectedCount };
	  }

	  async function consumeTimetableModificationCoupon(details = {}) {
	    return commitTimetableModification({ ...details, consumeCoupon: true });
	  }

	  async function appendTimetableRenameOperation(details = {}) {
	    return commitTimetableModification({ ...details, consumeCoupon: false });
	  }

  function timetableExternalSnapshot() {
    const context = timetableCurrentContext();
    const table = readWeeklyTimetable();
    const descriptions = readWeeklyTimetableDescriptions();
    const original = normalizeWeeklyTimetable(ST_WEEKLY_TIMETABLE);
    const days = [1, 2, 3, 4, 5].map((day) => ({
      day,
      label: ({ 1: "月曜日", 2: "火曜日", 3: "水曜日", 4: "木曜日", 5: "金曜日" })[day],
      active: day === context.activeDay,
      cells: ST_CLASS_PERIODS.map((period) => ({
        day,
        period: period.index,
        id: "wd" + day + "-p" + period.index,
        label: period.label,
        time: String(Math.floor(period.start / 60)).padStart(2, "0") + ":" + String(period.start % 60).padStart(2, "0"),
        subject: weeklyTimetableSubject(day, period.index, table),
        originalSubject: weeklyTimetableSubject(day, period.index, original),
        description: weeklyTimetableDescription(day, period.index, table, descriptions),
        originalDescription: weeklyTimetableOriginalDescription(day, period.index),
        modified: weeklyTimetableIsModified(day, period.index, table, descriptions),
        editable: timetableCanUseCouponForCell(day, period.index, context)
      }))
    }));
    const schedule = readDailyActionState(context.dateText);
    return {
      version: 1,
      writable: isLatestPhoneVariableView(),
      date: context.dateText,
      time: context.timeText,
      weekday: ({ 0: "日曜日", 1: "月曜日", 2: "火曜日", 3: "水曜日", 4: "木曜日", 5: "金曜日", 6: "土曜日" })[context.activeDay] || String(context.weekday || ""),
      activeDay: context.activeDay,
      special: context.special ? { title: context.special.title, detail: context.special.detail, description: context.special.description, blocksClass: context.blocksClass } : null,
      couponCount: timetableModificationCouponCount(),
      changeCount: weeklyTimetableChangeCount(table, descriptions),
      rhythm: [
        { id: "morning", label: "朝礼", start: "08:30", end: "08:40" },
        { id: "p1", label: "1限", start: "08:40", end: "09:30" },
        { id: "p2", label: "2限", start: "09:40", end: "10:30" },
        { id: "p3", label: "3限", start: "10:40", end: "11:30" },
        { id: "p4", label: "4限", start: "11:40", end: "12:30" },
        { id: "lunch", label: "昼休み", start: "12:30", end: "13:20" },
        { id: "p5", label: "5限", start: "13:20", end: "14:10" },
        { id: "p6", label: "6限", start: "14:20", end: "15:10" },
        { id: "closing", label: "終礼", start: "15:10", end: "15:25" },
        { id: "cleaning", label: "清掃", start: "15:25", end: "15:40" },
        { id: "after", label: "放課後", start: "15:45", end: "" }
      ],
      days,
      actionSchedule: {
        slots: schedule.slots.map((slot) => ({
          id: slot.id,
          label: slot.label,
          time: slot.time,
          locked: dailyActionSlotLocked(slot, schedule),
          sent: Boolean(slot.sent),
          cards: dailyActionSlotCards(schedule, slot.id).map((item) => ({ id: item.id, kind: item.kind, title: String(item.payload?.["暂存摘要"] || item.payload?.["操作"] || "行动"), source: String(item.payload?.["来源"] || "APP"), note: item.note || "" }))
        })),
        pending: schedule.cards.filter((item) => !item.slotId).map((item) => ({ id: item.id, kind: item.kind, title: String(item.payload?.["暂存摘要"] || item.payload?.["操作"] || "待安排操作"), source: String(item.payload?.["来源"] || "APP"), note: item.note || "", busy: String(item.payload?.["结算状态"] || "") === "进行中" })),
        used: dailyActionBaseCards(schedule).length,
        remaining: Math.max(0, 6 - dailyActionBaseCards(schedule).length),
        lastError: String(window.__ST_HYPNOOS_DAILY_SCHEDULE_LAST_ERROR__ || "")
      }
    };
  }

  async function timetableExternalCommit(intent = {}) {
    const day = Math.max(1, Math.min(5, Math.trunc(Number(intent.day) || 0)));
    const period = Math.max(1, Math.min(6, Math.trunc(Number(intent.period) || 0)));
    const context = timetableCurrentContext();
    if (!timetableCanUseCouponForCell(day, period, context)) return { ok: false, reason: "只能修改今天尚未结束的课节。" };
    const isModified = weeklyTimetableIsModified(day, period);
    const details = {
      day,
      period,
      dateText: context.dateText,
      weekday: context.weekday,
      timeText: context.timeText,
      label: timetableWeekdayShortName(day) + " " + period + "限",
      originalSubject: weeklyTimetableOriginalSubject(day, period),
      currentSubject: weeklyTimetableSubject(day, period),
      nextSubject: String(intent.subject || "").trim() || "自习",
      originalDescription: weeklyTimetableOriginalDescription(day, period),
      currentDescription: weeklyTimetableDescription(day, period),
      nextDescription: String(intent.description || "").trim() || defaultCourseDescription(intent.subject)
    };
    return isModified ? appendTimetableRenameOperation(details) : consumeTimetableModificationCoupon(details);
  }

  try {
    globalThis.__ST_HYPNOOS_GET_TIMETABLE__ = () => readWeeklyTimetable();
    globalThis.__ST_HYPNOOS_GET_TIMETABLE_DESCRIPTIONS__ = () => readWeeklyTimetableDescriptions();
    globalThis.__ST_HYPNOOS_DEFAULT_COURSE_DESCRIPTION__ = (subject) => defaultCourseDescription(subject);
    globalThis.__ST_HYPNOOS_RESET_TIMETABLE__ = () => resetWeeklyTimetable();
    globalThis.__ST_HYPNOOS_TIMETABLE_SNAPSHOT__ = () => timetableExternalSnapshot();
    globalThis.__ST_HYPNOOS_TIMETABLE_COMMIT__ = (intent) => timetableExternalCommit(intent);
    globalThis.__ST_HYPNOOS_TIMETABLE_MOVE_CARD__ = (entryId, slotId) => moveDailyCardToSlot(entryId, slotId);
    globalThis.__ST_HYPNOOS_TIMETABLE_ADD_NOTE__ = (text, targetId) => addDailyNoteCard(text, targetId);
    globalThis.__ST_HYPNOOS_TIMETABLE_ADVANCE__ = () => executeDailyActionAdvance();
    globalThis.__ST_HYPNOOS_TIMETABLE_NEXT_DAY__ = () => executeDailyActionNextDay();
  } catch {}
  function getSystemState() {
    const variables = activeStatDataReadScope !== undefined ? activeStatDataReadScope : getLatestStatDataSync();
    const system = variables?.["系统"];
    return system && typeof system === "object" && !Array.isArray(system) ? system : {};
  }

  function storyTimeOnly(value, fallback = "12:00") {
    const match = String(value ?? "").match(/(?:^|[^\\d])(\\d{1,2})\\s*[:：]\\s*(\\d{1,2})(?!\\d)/);
    if (!match) return fallback;
    const hour = Math.max(0, Math.min(23, Number(match[1]) || 0));
    const minute = Math.max(0, Math.min(59, Number(match[2]) || 0));
    return String(hour).padStart(2, "0") + ":" + String(minute).padStart(2, "0");
  }

  function liteIslandMeaningfulText(value) {
    const text = String(value ?? "").trim();
    if (!text || /^(无|没有|空|none|null|undefined)$/i.test(text)) return "";
    return text;
  }

  function liteIslandHypnosisInfo() {
    const roles = getStatsRoles();
    for (const [roleName, roleData] of Object.entries(roles)) {
      if (!isPlainObject(roleData)) continue;
      const effects = roleEffectValue(roleData, "临时催眠效果");
      if (!effects) continue;
      const entries = isPlainObject(effects)
        ? Object.entries(effects)
        : Array.isArray(effects)
          ? effects.map((value, index) => [String(index + 1), value])
          : [["催眠中", effects]];
      for (const [key, value] of entries) {
        let label = "";
        if (isPlainObject(value)) {
          label = liteIslandMeaningfulText(value["效果"] ?? value["名称"] ?? value["内容"] ?? value["描述"] ?? key);
        } else {
          label = liteIslandMeaningfulText(value);
        }
        if (label) return { roleName, title: label };
      }
    }
    return null;
  }

  function liteIslandProgressHtml(label, value, max) {
    const safeMax = Math.max(1, Number(max) || 1);
    const safeValue = Math.max(0, Math.min(safeMax, Number(value) || 0));
    const pct = Math.round(safeValue / safeMax * 100);
    return '<div class="st-app-island-stack"><strong>' + escapeHtml(label + " " + safeValue + " / " + safeMax) + '</strong><span class="st-app-island-progress" style="--pct:' + pct + '%"><i></i></span></div>';
  }

  function recordingIslandHtml() {
    return '<span class="st-app-island-recording"><span class="st-app-island-dot is-camera"></span><strong>录制中</strong></span>';
  }

  function taskIslandHtml() {
    return '<span class="st-task-island"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4h14v16H5zM8 8h8M8 12h6M8 16h4"/></svg><strong>TASK</strong></span>';
  }

  function inventoryIslandHtml() {
    return '<span class="st-inventory-island"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 8h16v11H4zM8 8V5h8v3M9 12h6"/></svg><strong>ITEM</strong></span>';
  }

  function sharedIslandModeIcon(kind) {
    const body = kind === "status"
      ? '<path d="M12 3l7 4v5c0 4.5-3 7.5-7 9-4-1.5-7-4.5-7-9V7l7-4Z" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M9 12l2 2 4-5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>'
      : '<path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><circle cx="12" cy="12" r="3" fill="currentColor"/>';
    return '<svg viewBox="0 0 24 24" aria-hidden="true">' + body + '</svg>';
  }

  function sharedIslandModeHtml(kind, fixedText, label) {
    return '<div class="st-home-hypnosis-fixed">' +
      sharedIslandModeIcon(kind) +
      '<strong>' + escapeHtml(fixedText) + '</strong>' +
    '</div>' +
    '<div class="st-home-hypnosis-scroll" data-shared-island-scroll>' +
      '<span>' + escapeHtml(label || fixedText) + '</span>' +
    '</div>';
  }

  function bindSharedIslandModeDrag(root) {
    root?.querySelectorAll?.("[data-shared-island-scroll]").forEach((scroller) => {
      enableHorizontalDragScroll(scroller);
    });
  }

  function hypnosisSubscriptionText(system) {
    const raw = system?.["催眠APP订阅等级"] ?? system?.["_催眠APP订阅等级"] ?? system?.["VIP等级"] ?? system?.["订阅等级"] ?? system?.["订阅"] ?? system?.["催眠APP订阅"] ?? system?.["MC订阅"] ?? system?.["买断"] ?? "";
    const text = String(raw || "").trim();
    const match = text.toUpperCase().replace(/\\s+/g, "").match(/VIP([1-6])/);
    if (match) return "VIP" + match[1];
    return text || "未买断";
  }

  function hypnosisIslandHtml(system) {
    const energy = Number(system?.["MC能量"] ?? 0) || 0;
    const maxEnergy = Number(system?.["MC能量上限"] ?? (energy || 1)) || 1;
    const safeMax = Math.max(1, maxEnergy);
    const safeEnergy = Math.max(0, Math.min(safeMax, energy));
    const pct = Math.round(safeEnergy / safeMax * 100);
    return '<div class="st-hypnosis-island-center">' +
      '<div class="st-hypnosis-island-row"><strong>MC能量 ' + escapeHtml(String(safeEnergy) + " / " + String(safeMax)) + '</strong><small>' + escapeHtml(hypnosisSubscriptionText(system)) + '</small></div>' +
      '<span class="st-app-island-progress" style="--pct:' + pct + '%"><i></i></span>' +
    '</div>';
  }

  function liteIslandModes(options = {}) {
    if (options.blankIsland === true) return [{ id: "app", className: "is-blank", html: "" }];
    const appHtml = options.html || '<strong>' + escapeHtml(options.title || "APP") + '</strong>';
    const modes = [{ id: "app", className: options.appClassName || "", html: appHtml }];
    const hypnosis = liteIslandHypnosisInfo();
    if (hypnosis) {
      modes.push({
        id: "hypnosis",
        className: "is-hypnosis",
        html: sharedIslandModeHtml("hypnosis", "催眠中", (hypnosis.roleName ? hypnosis.roleName + " · " : "") + hypnosis.title)
      });
    }
    return modes;
  }

  function renderLiteHeader(page, options = {}) {
    const modes = liteIslandModes(options);
    const requested = String(page?.dataset?.liteIslandMode || "app");
    const current = modes.find((mode) => mode.id === requested) || modes[0];
    if (page?.dataset && current.id !== requested) page.dataset.liteIslandMode = current.id;
    const headerClass = options.headerClass || "st-lite-header";
    const backClass = options.backClass || "st-lite-back";
    const backAttr = options.backAttr || 'data-lite-action="back"';
    const switchable = modes.length > 1;
    return '<header class="' + escapeAttr(headerClass) + '">' +
      '<button class="' + escapeAttr(backClass) + '" ' + backAttr + ' title="返回桌面">‹</button>' +
      '<div class="st-app-island ' + escapeAttr(current.className || "") + (switchable ? ' is-switchable' : '') + '" data-lite-island data-lite-island-switchable="' + (switchable ? "true" : "false") + '" role="' + (switchable ? "button" : "status") + '" tabindex="' + (switchable ? "0" : "-1") + '">' +
        current.html +
      '</div>' +
      '<template data-lite-island-app-template data-lite-island-app-title="' + escapeAttr(options.title || "APP") + '" data-lite-island-app-class="' + escapeAttr(options.appClassName || "") + '">' + appHtmlForLiteIslandTemplate(options) + '</template>' +
    '</header>';
  }

  function appHtmlForLiteIslandTemplate(options = {}) {
    return options.html || '<strong>' + escapeHtml(options.title || "APP") + '</strong>';
  }

  function rerenderLitePagePreservingBodyScroll(page, rerender) {
    const body = page?.querySelector?.(".st-lite-body");
    const scrollTop = body ? body.scrollTop : 0;
    const profileItemsScrollTop = Number(page?.querySelector?.(".st-profile-items")?.scrollTop || 0);
    const profileRemodelDetailScrollLeft = Number(page?.querySelector?.(".st-profile-remodel-detail-strip")?.scrollLeft || 0);
    const pageScrollTop = page && typeof page.scrollTop === "number" ? page.scrollTop : 0;
    const docScroll = document.scrollingElement ? { left: document.scrollingElement.scrollLeft, top: document.scrollingElement.scrollTop } : null;
    try { document.activeElement?.blur?.(); } catch {}
    rerender?.();
    const restore = () => {
      const nextBody = page?.querySelector?.(".st-lite-body");
      if (nextBody) nextBody.scrollTop = scrollTop;
      const nextProfileItems = page?.querySelector?.(".st-profile-items");
      if (nextProfileItems) nextProfileItems.scrollTop = profileItemsScrollTop;
      const nextRemodelDetailStrip = page?.querySelector?.(".st-profile-remodel-detail-strip");
      if (nextRemodelDetailStrip) nextRemodelDetailStrip.scrollLeft = profileRemodelDetailScrollLeft;
      if (page && typeof page.scrollTop === "number") page.scrollTop = pageScrollTop;
      if (docScroll && document.scrollingElement) document.scrollingElement.scrollTo(docScroll.left, docScroll.top);
    };
    restore();
    window.requestAnimationFrame(restore);
  }

  function rerenderPoliceHeadquartersPreservingScroll(page) {
    const body = page?.querySelector?.(".st-police-hq-v5-body");
    const roster = page?.querySelector?.(".st-police-hq-v5-roster-list");
    const traits = page?.querySelector?.(".st-police-hq-v5-trait-grid");
    const editor = page?.querySelector?.(".st-police-hq-v5-editor");
    const scrollState = {
      body: body ? body.scrollTop : 0,
      roster: roster ? roster.scrollTop : 0,
      traits: traits ? traits.scrollTop : 0,
      editor: editor ? editor.scrollTop : 0
    };
    try { document.activeElement?.blur?.(); } catch {}
    renderPoliceHeadquartersPage(page);
    window.requestAnimationFrame(() => {
      const nextBody = page?.querySelector?.(".st-police-hq-v5-body");
      const nextRoster = page?.querySelector?.(".st-police-hq-v5-roster-list");
      const nextTraits = page?.querySelector?.(".st-police-hq-v5-trait-grid");
      const nextEditor = page?.querySelector?.(".st-police-hq-v5-editor");
      if (nextBody) nextBody.scrollTop = scrollState.body;
      if (nextRoster) nextRoster.scrollTop = scrollState.roster;
      if (nextTraits) nextTraits.scrollTop = scrollState.traits;
      if (nextEditor) nextEditor.scrollTop = scrollState.editor;
    });
  }

  function rerenderHospitalRemodelPreservingScroll(page) {
    const body = page?.querySelector?.(".st-hospital-remodel-body");
    const roster = page?.querySelector?.(".st-hospital-remodel-roster > div");
    const parts = page?.querySelector?.(".st-hospital-remodel-parts > div");
    const details = page?.querySelector?.(".st-hospital-remodel-detail-list");
    const current = page?.querySelector?.(".st-hospital-remodel-current div");
    const editor = page?.querySelector?.(".st-hospital-remodel-editor");
    const pageScrollTop = page && typeof page.scrollTop === "number" ? page.scrollTop : 0;
    const docScroll = document.scrollingElement ? { left: document.scrollingElement.scrollLeft, top: document.scrollingElement.scrollTop } : null;
    const scrollState = {
      body: body ? body.scrollTop : 0,
      roster: roster ? roster.scrollTop : 0,
      parts: parts ? parts.scrollTop : 0,
      detailsLeft: details ? details.scrollLeft : 0,
      detailsTop: details ? details.scrollTop : 0,
      current: current ? current.scrollTop : 0,
      editor: editor ? editor.scrollTop : 0
    };
    try { document.activeElement?.blur?.(); } catch {}
    renderHospitalRemodelRoom(page);
    const restore = () => {
      const nextBody = page?.querySelector?.(".st-hospital-remodel-body");
      const nextRoster = page?.querySelector?.(".st-hospital-remodel-roster > div");
      const nextParts = page?.querySelector?.(".st-hospital-remodel-parts > div");
      const nextDetails = page?.querySelector?.(".st-hospital-remodel-detail-list");
      const nextCurrent = page?.querySelector?.(".st-hospital-remodel-current div");
      const nextEditor = page?.querySelector?.(".st-hospital-remodel-editor");
      if (nextBody) nextBody.scrollTop = scrollState.body;
      if (nextRoster) nextRoster.scrollTop = scrollState.roster;
      if (nextParts) nextParts.scrollTop = scrollState.parts;
      if (nextDetails) {
        nextDetails.scrollLeft = scrollState.detailsLeft;
        nextDetails.scrollTop = scrollState.detailsTop;
      }
      if (nextCurrent) nextCurrent.scrollTop = scrollState.current;
      if (nextEditor) nextEditor.scrollTop = scrollState.editor;
      if (page && typeof page.scrollTop === "number") page.scrollTop = pageScrollTop;
      if (docScroll && document.scrollingElement) document.scrollingElement.scrollTo(docScroll.left, docScroll.top);
    };
    restore();
    window.requestAnimationFrame(restore);
  }

  function updateLiteIslandInPlace(page) {
    const island = page.querySelector("[data-lite-island]");
    const appTemplate = page.querySelector("[data-lite-island-app-template]");
    if (!island || !appTemplate) return;
    const options = {
      title: appTemplate.dataset.liteIslandAppTitle || page.getAttribute("aria-label") || "APP",
      appClassName: appTemplate.dataset.liteIslandAppClass || "",
      html: appTemplate.innerHTML
    };
    const modes = liteIslandModes(options);
    const requested = String(page.dataset.liteIslandMode || "app");
    const current = modes.find((mode) => mode.id === requested) || modes[0];
    const switchable = modes.length > 1;
    page.dataset.liteIslandMode = current.id;
    island.className = "st-app-island " + (current.className || "") + (switchable ? " is-switchable" : "");
    island.dataset.liteIslandSwitchable = switchable ? "true" : "false";
    island.setAttribute("role", switchable ? "button" : "status");
    island.setAttribute("tabindex", switchable ? "0" : "-1");
    island.innerHTML = current.html;
    bindSharedIslandModeDrag(island);
    bindLiteIslandControls(page);
  }

  function bindLiteIslandControls(page, rerender) {
    page.querySelectorAll("[data-calendar-month-shift]").forEach((button) => {
      if (button.dataset.liteIslandControlBound === "true") return;
      button.dataset.liteIslandControlBound = "true";
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const shift = Number(button.getAttribute("data-calendar-month-shift")) || 0;
        const current = Number(page.dataset.calendarMonthOffset || 0) || 0;
        page.dataset.calendarMonthOffset = String(current + shift);
        rerenderLitePagePreservingBodyScroll(page, rerender);
      });
    });
  }

  function bindLiteHeader(page, rerender) {
    const island = page.querySelector("[data-lite-island]");
    bindSharedIslandModeDrag(page);
    if (island?.dataset.liteIslandSwitchable === "true") {
      const switchMode = (event) => {
        if (event?.target?.closest?.("[data-lite-island-control]")) return;
        event?.preventDefault?.();
        const appTemplate = page.querySelector("[data-lite-island-app-template]");
        const modes = liteIslandModes({
          title: appTemplate?.dataset?.liteIslandAppTitle || page.getAttribute("aria-label") || "APP",
          appClassName: appTemplate?.dataset?.liteIslandAppClass || "",
          html: appTemplate?.innerHTML || ""
        });
        const ids = modes.map((mode) => mode.id);
        const currentIndex = Math.max(0, ids.indexOf(page.dataset.liteIslandMode || "app"));
        page.dataset.liteIslandMode = ids[(currentIndex + 1) % ids.length] || "app";
        updateLiteIslandInPlace(page);
      };
      island.addEventListener("click", switchMode);
      island.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") switchMode(event);
      });
    }
    bindLiteIslandControls(page, rerender);
  }

  function parseStoryDate(text) {
    const raw = String(text || "");
    const match = raw.match(/(\\d{4})\\s*年\\s*(\\d{1,2})\\s*月\\s*(\\d{1,2})\\s*日/);
    if (!match) return null;
    const year = Number(match[1]);
    const month = Number(match[2]);
    const day = Number(match[3]);
    if (!Number.isInteger(year) || year < 1 || month < 1 || month > 12 || day < 1 || day > daysInStoryMonth(year, month)) return null;
    return { year, month, day };
  }

  function systemStoryDateText(system = getSystemState()) {
    const year = Math.max(1, Math.floor(Number(system?.["当前年份"]) || 2024));
    const date = String(system?.["当前日期"] || "").trim() || "4月9日";
    return year + "年" + date;
  }

  function setSystemStoryDate(system, fullDateText) {
    const parsed = parseStoryDate(fullDateText);
    if (!system || !parsed) return false;
    system["当前年份"] = parsed.year;
    system["当前日期"] = parsed.month + "月" + parsed.day + "日";
    return true;
  }

  function storyDateSerialDay(date) {
    if (!date) return NaN;
    return Math.floor(Date.UTC(Number(date.year), Number(date.month) - 1, Number(date.day)) / 86400000);
  }

  function storyDateTextFromParts(year, month, day) {
    return Number(year) + "年" + Number(month) + "月" + Number(day) + "日";
  }

  function schoolYearDay(month, day) {
    let total = 0;
    for (const item of ST_SCHOOL_MONTH_ORDER) {
      if (item === month) return total + day;
      total += daysInStoryMonth(2024, item) || 30;
    }
    return day;
  }

  function storyCalendarKey(month, day) {
    return String(Number(month) || 0) + "-" + String(Number(day) || 0);
  }

  function storyCalendarSpecialLabel(item) {
    const from = item.from ?? item.d;
    const to = item.to ?? from;
    return from === to ? item.m + "月" + from + "日" : item.m + "月" + from + "-" + to + "日";
  }

  function storyCalendarDay(month, day, year = null) {
    const entry = {
      year: Number(year) || null,
      month: Number(month),
      day: Number(day),
      dateText: year ? storyDateTextFromParts(year, month, day) : month + "月" + day + "日",
      weekday: year ? ST_WEEKDAY_NAMES[new Date(Date.UTC(Number(year), Number(month) - 1, Number(day))).getUTCDay()] : "",
      specialDay: null,
      specialText: ""
    };
    const specialRanges = ST_SPECIAL_DAYS
      .map((item) => {
        const from = item.from ?? item.d;
        const to = item.to ?? from;
        return { item, from, to, span: to - from, start: schoolYearDay(item.m, from) };
      })
      .sort((a, b) => a.span - b.span || a.start - b.start);
    for (const range of specialRanges) {
      for (let day = range.from; day <= range.to; day += 1) {
        if (Number(range.item.m) !== Number(month) || Number(day) !== Number(entry.day) || entry.specialDay) continue;
        entry.specialDay = { ...range.item };
        entry.specialText = storyCalendarSpecialLabel(range.item) + " " + range.item.title + "：" + (range.item.detail || "特别日程");
      }
    }
    return entry;
  }

  function weekdayForStoryDate(dateText) {
    const parsed = parseStoryDate(dateText);
    if (!parsed) return "";
    return ST_WEEKDAY_NAMES[new Date(Date.UTC(parsed.year, parsed.month - 1, parsed.day)).getUTCDay()] || "";
  }

  function minutesFromTimeText(text) {
    const match = String(text || "").match(/(\\d{1,2})\\s*[:：]\\s*(\\d{1,2})/);
    if (!match) return 8 * 60;
    return Number(match[1]) * 60 + Number(match[2]);
  }

  function nextStoryDateLabel(dateText) {
    const parsed = parseStoryDate(dateText);
    if (!parsed) return "明天";
    const next = new Date(Date.UTC(parsed.year, parsed.month - 1, parsed.day + 1));
    return storyDateTextFromParts(next.getUTCFullYear(), next.getUTCMonth() + 1, next.getUTCDate());
  }

  function specialDayForDate(parsedDate) {
    if (!parsedDate) return null;
    return storyCalendarDay(parsedDate.month, parsedDate.day, parsedDate.year)?.specialDay || null;
  }

  function specialDayBlocksClasses(special) {
    if (!special) return false;
    if (special.holiday || special.exam) return true;
    const detail = String(special.detail || "");
    return !/普通/.test(detail);
  }

  function normalSchoolSlot(minutes, weekdayText) {
    const weekdayIndex = ST_WEEKDAY_INDEX[weekdayText];
    if (weekdayIndex === 0 || weekdayIndex === 6) {
      return { title: "周末自由", detail: "无固定课程" };
    }
    if (minutes >= 450 && minutes < 500) return { title: "早训", detail: "社团自愿" };
    if (minutes >= 500 && minutes < 510) return { title: "入校", detail: "校门关闭前" };
    if (minutes >= 510 && minutes < 520) return { title: "朝礼", detail: "08:30-08:40" };
    for (const period of ST_CLASS_PERIODS) {
      if (minutes >= period.start && minutes < period.end) {
        const subject = weeklyTimetableSubject(weekdayIndex, period.index);
        return {
          title: period.label + " · " + subject,
          detail: formatPeriodTime(period.start) + "-" + formatPeriodTime(period.end),
          period: period.label,
          subject
        };
      }
    }
    if (minutes >= 570 && minutes < 580) return { title: "课间", detail: "1限后" };
    if (minutes >= 630 && minutes < 640) return { title: "课间", detail: "2限后" };
    if (minutes >= 690 && minutes < 700) return { title: "课间", detail: "3限后" };
    if (minutes >= 750 && minutes < 800) return { title: "午休", detail: "12:30-13:20" };
    if (minutes >= 850 && minutes < 860) return { title: "课间", detail: "5限前后" };
    if (minutes >= 910 && minutes < 925) return { title: "终礼", detail: "15:10-15:25" };
    if (minutes >= 925 && minutes < 940) return { title: "清扫时间", detail: "15:25-15:40" };
    if (minutes >= 945) return { title: "放学后", detail: "社团/自由行动" };
    if (minutes < 450) return { title: "上学前", detail: "自由行动" };
    return { title: "课间", detail: "移动/准备" };
  }

  function formatPeriodTime(minutes) {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return String(h).padStart(2, "0") + ":" + String(m).padStart(2, "0");
  }

  function routineSlot(minutes, weekdayText, parsedDate) {
    const special = specialDayForDate(parsedDate);
    const normal = normalSchoolSlot(minutes, weekdayText);
    if (specialDayBlocksClasses(special)) {
      return { title: special.title, detail: special.detail || "特别日程" };
    }
    if (special && /普通/.test(special.detail || "")) {
      return { title: normal.title, detail: normal.detail + " / " + special.title };
    }
    return normal;
  }

  function specialDateLabel(item) {
    const from = item.from ?? item.d;
    const to = item.to ?? item.d;
    if (from !== to) return item.m + "/" + from + "-" + to;
    return item.m + "/" + from;
  }

  function upcomingSpecialDays(parsedDate, limit = 8) {
    if (!parsedDate) return [];
    const base = parsedDate;
    const today = schoolYearDay(base.month, base.day);
    return ST_SPECIAL_DAYS
      .map((item) => {
        const from = item.from ?? item.d;
        const to = item.to ?? item.d;
        const start = schoolYearDay(item.m, from);
        const end = schoolYearDay(item.m, to);
        const distance = today > end ? -1 : Math.max(0, start - today);
        return { ...item, distance };
      })
      .filter((item) => item.distance >= 0)
      .sort((a, b) => a.distance - b.distance)
      .slice(0, limit);
  }

  function calendarDisplayDate(page, parsedDate) {
    if (!parsedDate) return null;
    const offset = Number(page?.dataset?.calendarMonthOffset || 0) || 0;
    const date = new Date(Date.UTC(parsedDate.year, parsedDate.month - 1 + offset, 1));
    return {
      year: date.getUTCFullYear(),
      month: date.getUTCMonth() + 1,
      day: offset === 0 ? parsedDate.day : 1
    };
  }

  function calendarSelectedDate(page, displayDate, actualDate) {
    if (!displayDate) return null;
    const year = displayDate.year;
    const month = displayDate.month;
    const selectedYear = Number(page?.dataset?.calendarSelectedYear || 0);
    const selectedMonth = Number(page?.dataset?.calendarSelectedMonth || 0);
    const selectedDay = Number(page?.dataset?.calendarSelectedDay || 0);
    const selectedDaysInMonth = daysInStoryMonth(selectedYear, selectedMonth);
    const fallbackDay = actualDate?.year === year && actualDate?.month === month ? actualDate.day : 1;
    if (selectedYear === year && selectedMonth === month && selectedDay >= 1 && selectedDay <= selectedDaysInMonth) {
      return { year: selectedYear, month: selectedMonth, day: selectedDay };
    }
    const daysInMonth = daysInStoryMonth(year, month);
    return { year, month, day: Math.max(1, Math.min(daysInMonth, fallbackDay)) };
  }

  function renderCalendarDayDetail(selectedDate, actualDate) {
    if (!selectedDate) return '<section class="st-lite-card st-cal-detail"><p>当前日期缺少年份或格式无效，无法计算星期。</p></section>';
    const dateLabel = storyDateTextFromParts(selectedDate.year, selectedDate.month, selectedDate.day);
    const weekday = weekdayForStoryDate(dateLabel) || "";
    const weekdayIndex = ST_WEEKDAY_INDEX[weekday];
    const special = specialDayForDate(selectedDate);
    const isToday = actualDate?.year === selectedDate?.year && actualDate?.month === selectedDate?.month && actualDate?.day === selectedDate?.day;
    const courses = weekdayIndex >= 1 && weekdayIndex <= 5 && !special?.holiday
      ? ST_CLASS_PERIODS.map((period) => {
          const subject = weeklyTimetableSubject(weekdayIndex, period.index);
          return '<span title="' + escapeAttr(period.label + " " + subject) + '">' + escapeHtml(period.label + " " + subject) + '</span>';
        }).join("")
      : "";
    return '<section class="st-lite-card st-cal-detail">' +
      '<div class="st-cal-detail-head"><strong>' + escapeHtml(dateLabel) + '</strong><span>' + escapeHtml((weekday || "未记录") + (isToday ? " · 今天" : "")) + '</span></div>' +
      '<p>' + escapeHtml(special ? (special.title + "：" + (special.description || special.detail || "特别日程")) : (weekdayIndex === 0 || weekdayIndex === 6 ? "周末没有固定课程，可按个人安排活动。" : "普通授课日，课程按当天课表依次进行。")) + '</p>' +
      (courses ? '<div class="st-cal-detail-courses">' + courses + '</div>' : '<p>没有固定课程，按自由行动或特殊日程推进。</p>') +
    '</section>';
  }

  function calendarIslandHtml(displayDate) {
    if (!displayDate) return '<div class="st-app-island-calendar"><strong>日期异常</strong></div>';
    return '<div class="st-app-island-calendar">' +
      '<button type="button" data-lite-island-control data-calendar-month-shift="-1" title="上个月">‹</button>' +
      '<strong>' + escapeHtml(String(displayDate.year) + "年" + String(displayDate.month) + "月") + '</strong>' +
      '<button type="button" data-lite-island-control data-calendar-month-shift="1" title="下个月">›</button>' +
    '</div>';
  }

  function renderCalendarMonthGrid(parsedDate, actualDate = parsedDate, selectedDate = parsedDate) {
    if (!parsedDate) return '<div class="st-cal-month-head"><strong>日期格式异常</strong><span>请使用完整年份</span></div>';
    const year = parsedDate.year;
    const month = parsedDate.month;
    const todayDay = actualDate?.year === year && actualDate?.month === month ? (actualDate?.day || 0) : 0;
    const selectedDay = selectedDate?.year === year && selectedDate?.month === month ? (selectedDate?.day || 0) : 0;
    const daysInMonth = daysInStoryMonth(year, month);
    const firstWeekday = new Date(Date.UTC(year, month - 1, 1)).getUTCDay();
    const weekdayLabels = ["日", "一", "二", "三", "四", "五", "六"];
    const cells = weekdayLabels.map((label) => '<div class="st-cal-weekday">' + label + '</div>');
    for (let i = 0; i < firstWeekday; i += 1) {
      cells.push('<div class="st-cal-day is-empty"></div>');
    }
    for (let day = 1; day <= daysInMonth; day += 1) {
      const weekdayIndex = (firstWeekday + day - 1) % 7;
      const special = specialDayForDate({ year, month, day });
      const className = [
        "st-cal-day",
        day === todayDay ? "is-today" : "",
        day === selectedDay ? "is-selected" : "",
        special ? "is-special" : "",
        weekdayIndex === 0 || weekdayIndex === 6 ? "is-weekend" : ""
      ].filter(Boolean).join(" ");
      cells.push(
        '<button type="button" class="' + className + '" data-calendar-day="' + day + '" data-calendar-month="' + month + '" data-calendar-year="' + year + '">' +
          '<b>' + day + '</b>' +
          (special ? '<i>' + escapeHtml(special.title) + '</i>' : '') +
        '</button>'
      );
    }
    return (
      '<div class="st-cal-month-head"><strong>' + year + '年' + month + '月</strong><span>' + escapeHtml(weekdayForStoryDate(storyDateTextFromParts(year, month, todayDay || 1)) || "") + '</span></div>' +
      '<div class="st-cal-month-grid">' + cells.join("") + '</div>'
    );
  }

  function renderLiteCalendarPage(page) {
    const system = getSystemState();
    const dateText = systemStoryDateText(system);
    const timeText = storyTimeOnly(system["当前时间"], "12:00");
    const parsedDate = parseStoryDate(dateText);
    const displayDate = calendarDisplayDate(page, parsedDate);
    const selectedDate = calendarSelectedDate(page, displayDate, parsedDate);
    const weekday = weekdayForStoryDate(dateText) || String(system["_当前周几"] || system["当前周几"] || "").trim() || "日期未记录";
    const slot = routineSlot(minutesFromTimeText(timeText), weekday, parsedDate);
    const special = specialDayForDate(parsedDate);
    const events = upcomingSpecialDays(parsedDate);
    const eventsHtml = events.map((event) => (
      '<article class="st-cal-event">' +
        '<time>' + escapeHtml(specialDateLabel(event)) + '</time>' +
        '<div><strong>' + escapeHtml(event.title) + '</strong><span>' + escapeHtml(event.description || event.detail || "特别日程") + '</span></div>' +
      '</article>'
    )).join("");
    page.innerHTML =
      renderLiteHeader(page, { title: "日历", html: calendarIslandHtml(displayDate) }) +
      '<main class="st-lite-body">' +
        '<section class="st-lite-card st-cal-hero">' +
          '<div class="st-cal-date"><strong>' + escapeHtml(dateText) + '</strong><span>' + escapeHtml(timeText) + '</span></div>' +
          '<div class="st-cal-now">' +
            '<article><small>当前</small><strong>' + escapeHtml(slot.title) + '</strong></article>' +
            '<article><small>状态</small><strong>' + escapeHtml(special ? special.title : weekday) + '</strong></article>' +
          '</div>' +
        '</section>' +
        '<section class="st-lite-card st-cal-controls">' +
          '<label><span>查看年份</span><input type="number" inputmode="numeric" min="2024" max="9999" step="1" data-calendar-year-input value="' + escapeAttr(String(displayDate?.year || "")) + '"></label>' +
          '<small>仅查看日期，不改变剧情；推进日期或时间请使用“时钟”。</small>' +
        '</section>' +
        '<section class="st-lite-card st-cal-month">' + renderCalendarMonthGrid(displayDate, parsedDate, selectedDate) + '</section>' +
        '<div class="st-cal-section-title">日期详情</div>' +
        renderCalendarDayDetail(selectedDate, parsedDate) +
        '<div class="st-cal-section-title">近期特殊日期</div>' +
        '<section class="st-cal-events">' + (eventsHtml || '<article class="st-cal-event"><time>--</time><div><strong>暂无特殊日期</strong><span>按普通日程推进</span></div></article>') + '</section>' +
      '</main>';
    bindLiteHeader(page, () => renderLiteCalendarPage(page));
    page.querySelector('[data-lite-action="back"]')?.addEventListener("click", () => {
      setPhoneActiveApp(page.parentElement, "");
      page.remove();
    });
    page.querySelectorAll("[data-calendar-day]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        page.dataset.calendarSelectedYear = button.getAttribute("data-calendar-year") || "";
        page.dataset.calendarSelectedMonth = button.getAttribute("data-calendar-month") || "";
        page.dataset.calendarSelectedDay = button.getAttribute("data-calendar-day") || "";
        rerenderLitePagePreservingBodyScroll(page, () => renderLiteCalendarPage(page));
      });
    });
    page.querySelector("[data-calendar-year-input]")?.addEventListener("change", (event) => {
      const requestedYear = Math.max(2024, Math.min(9999, Math.trunc(Number(event.currentTarget?.value) || 0)));
      if (!parsedDate || !requestedYear) return;
      const currentDisplay = calendarDisplayDate(page, parsedDate) || parsedDate;
      page.dataset.calendarMonthOffset = String((requestedYear - parsedDate.year) * 12 + (currentDisplay.month - parsedDate.month));
      page.dataset.calendarSelectedYear = "";
      page.dataset.calendarSelectedMonth = "";
      page.dataset.calendarSelectedDay = "";
      rerenderLitePagePreservingBodyScroll(page, () => renderLiteCalendarPage(page));
    });
  }

  function splitSubject(subject) {
    const match = String(subject || "").match(/^(.+?)（(.+?)）$/);
    return match ? { main: match[1], sub: match[2] } : { main: String(subject || "自习"), sub: "" };
  }

  function rerenderTimetablePagePreservingScroll(page) {
    rerenderLitePagePreservingBodyScroll(page, () => renderTimetablePage(page));
  }

  function renderTimetablePage(page) {
    const days = [
      { index: 1, short: "周一", full: "星期一" },
      { index: 2, short: "周二", full: "星期二" },
      { index: 3, short: "周三", full: "星期三" },
      { index: 4, short: "周四", full: "星期四" },
      { index: 5, short: "周五", full: "星期五" }
    ];
    const context = timetableCurrentContext();
    const { dateText, timeText, parsedDate, weekday, activeDay, minutes, special, blocksClass } = context;
    const activePeriod = ST_CLASS_PERIODS.find((period) => minutes >= period.start && minutes < period.end)?.index || 0;
    const slot = routineSlot(minutes, weekday, parsedDate);
    const mode = page.dataset.timetableMode === "original" ? "original" : "modified";
    if (mode !== "modified") page.dataset.timetableEdit = "";
    const selecting = mode === "modified" && page.dataset.timetableEdit === "select";
    const timetable = readWeeklyTimetable();
    const displayTable = mode === "original" ? normalizeWeeklyTimetable(ST_WEEKLY_TIMETABLE) : timetable;
    const changeCount = weeklyTimetableChangeCount(timetable);
    const couponCount = timetableModificationCouponCount();
    const notice = String(page.dataset.timetableNotice || "").trim();
    const selectedState = timetableSelectedState(page);
    const selectedCanEditByTime = selectedState ? timetableCanUseCouponForCell(selectedState.day, selectedState.period, context) : false;
    const detailEditing = page.dataset.timetableDetailEditing === "true";
    const selectedCanRenameDirectly = Boolean(mode === "modified" && selectedState?.isModified && selectedCanEditByTime);
    const selectedCanUseCouponBySelection = Boolean(mode === "modified" && selecting && selectedState && !selectedState.isModified && selectedCanEditByTime);
    const selectedCanEdit = Boolean(selectedCanUseCouponBySelection || (selectedCanRenameDirectly && detailEditing));
    const selectedAction = selectedState?.isModified ? "rename" : "coupon";
    const selectedNote = !selectedState
      ? "点击任意课节查看原课程与魔改课程。"
      : mode !== "modified"
        ? "原课程表只用于查看；切换到魔改课程表后可以修改。"
        : !selectedCanEditByTime
            ? "只能修改今天还没结束的课节。"
            : selectedState.isModified
              ? "该星期＋课节单格已永久魔改，可直接重命名且不再消耗魔改券。"
              : selecting
                ? "保存后消耗1张课程表魔改券，永久修改这个星期＋课节单格。"
                : "选择入口仅限今天剩余课程；保存后会永久作用于每周同一课表格。";
    const selectedDetailHtml = selectedState
      ? '<section class="st-tt-detail" data-timetable-detail>' +
          '<div class="st-tt-detail-head"><strong>' + escapeHtml(selectedState.label) + '</strong><div class="st-tt-detail-tools">' +
            (selectedCanRenameDirectly && !detailEditing ? '<button type="button" data-timetable-detail-edit>重命名</button>' : '') +
            '<span>' + escapeHtml(selectedState.isModified ? "已魔改" : "未魔改") + '</span></div></div>' +
          '<div class="st-tt-detail-grid">' +
            '<article><small>原课程名</small><b title="' + escapeAttr(selectedState.originalSubject) + '">' + escapeHtml(selectedState.originalSubject) + '</b></article>' +
            '<article><small>魔改课程名</small><b title="' + escapeAttr(selectedState.isModified ? selectedState.currentSubject : "未魔改") + '">' + escapeHtml(selectedState.isModified ? selectedState.currentSubject : "未魔改") + '</b></article>' +
          '</div>' +
          '<article class="st-tt-description"><small>' + escapeHtml(selectedState.isModified ? "当前课程描述" : "原课程描述") + '</small><p>' + escapeHtml(selectedState.currentDescription) + '</p></article>' +
          (selectedCanEdit
            ? '<div class="st-tt-editor">' +
                '<label><span>课程名</span><input class="st-tt-subject-input" data-timetable-detail-input maxlength="24" value="' + escapeAttr(selectedState.currentSubject) + '" aria-label="课程名"></label>' +
                '<label class="st-tt-editor-description"><span>课程描述 / 魔改备注</span><textarea data-timetable-detail-description maxlength="260" aria-label="课程描述" placeholder="写下魔改后的课堂内容；AI会按这里理解课程性质。">' + escapeHtml(selectedState.currentDescription) + '</textarea></label>' +
                '<button type="button" data-timetable-detail-save="' + selectedAction + '">' + escapeHtml(selectedAction === "coupon" ? "保存并扣券" : "保存重命名") + '</button>' +
              '</div>'
            : '') +
          '<p class="st-tt-detail-note">' + escapeHtml(selectedNote) + '</p>' +
        '</section>'
      : '<section class="st-tt-detail" data-timetable-detail><p class="st-tt-detail-note">' + escapeHtml(selectedNote) + '</p></section>';
    const weekHtml = days.map((day) => {
      const periods = ST_CLASS_PERIODS.map((period) => {
        const subject = weeklyTimetableSubject(day.index, period.index, displayTable);
        const originalSubject = weeklyTimetableOriginalSubject(day.index, period.index);
        const modifiedSubject = weeklyTimetableSubject(day.index, period.index, timetable);
	        const modified = originalSubject !== modifiedSubject;
	        const parts = splitSubject(subject);
	        const current = !blocksClass && day.index === activeDay && period.index === activePeriod;
	        const canEditByTime = timetableCanUseCouponForCell(day.index, period.index, context);
	        const canRenameCell = mode === "modified" && modified && canEditByTime;
	        const canUseCouponCell = mode === "modified" && selecting && !modified && canEditByTime;
	        const selected = selectedState && selectedState.day === day.index && selectedState.period === period.index;
	        const cellBody = '<small>' + escapeHtml(period.label) + '</small>' +
	          '<strong>' + escapeHtml(parts.main) + '</strong>' +
	          (parts.sub ? '<em>' + escapeHtml(parts.sub) + '</em>' : '');
	        return '<div class="st-tt-period ' + (current ? "is-current " : "") + (modified ? "is-modified " : "") + (selected ? "is-selected " : "") + (canUseCouponCell ? "is-selectable " : "") + (canRenameCell ? "is-renamable " : "") + (selecting && !canUseCouponCell && !canRenameCell ? "is-disabled" : "") + '">' +
	          '<button type="button" data-timetable-cell data-timetable-day="' + day.index + '" data-timetable-period="' + period.index + '" aria-label="' + escapeAttr("查看 " + day.short + " " + period.label) + '">' + cellBody + '</button>' +
	        '</div>';
      }).join("");
      return '<section class="st-tt-day ' + (day.index === activeDay ? "is-active" : "") + '">' +
        '<h3>' + escapeHtml(day.short) + '<small>' + escapeHtml(day.full) + '</small></h3>' +
        periods +
      '</section>';
    }).join("");
    page.innerHTML =
      renderLiteHeader(page, { title: "课程表" }) +
      '<main class="st-lite-body">' +
        '<section class="st-lite-card st-tt-current">' +
          '<div><span>' + escapeHtml(dateText + " · " + timeText) + '</span><strong>' + escapeHtml(slot.title) + '</strong></div>' +
          '<div class="st-tt-badge">' + escapeHtml(slot.detail || (special?.detail || "普通授课")) + '</div>' +
        '</section>' +
        '<section class="st-tt-segments">' +
          '<button type="button" class="' + (mode === "original" ? "active" : "") + '" data-timetable-mode="original">原课程表</button>' +
          '<button type="button" class="' + (mode === "modified" ? "active" : "") + '" data-timetable-mode="modified">魔改课程表</button>' +
        '</section>' +
        '<section class="st-tt-actions">' +
          (mode === "modified" ? '<button type="button" class="primary" data-timetable-edit-toggle>' + (selecting ? "取消选择" : "修改课程表") + '</button>' : '') +
          '<span>' + escapeHtml((selecting ? "选择今天剩余一节 / " : "") + "已改 " + changeCount + " 格 / " + TIMETABLE_MOD_COUPON_ITEM + " " + couponCount + " 张") + '</span>' +
        '</section>' +
        (notice ? '<p class="st-tt-status">' + escapeHtml(notice) + '</p>' : '') +
        '<section class="st-tt-week">' + weekHtml + '</section>' +
        selectedDetailHtml +
        '<section class="st-tt-rhythm">' +
          '<div class="st-tt-rhythm-item"><b>08:30</b><span>朝礼</span><i>08:40</i></div>' +
          '<div class="st-tt-rhythm-item"><b>12:30</b><span>午休</span><i>13:20</i></div>' +
          '<div class="st-tt-rhythm-item"><b>15:10</b><span>终礼</span><i>15:25</i></div>' +
          '<div class="st-tt-rhythm-item"><b>15:25</b><span>清扫</span><i>15:40</i></div>' +
          '<div class="st-tt-rhythm-item"><b>15:45</b><span>放学</span><i>16:00</i></div>' +
        '</section>' +
      '</main>';
    bindLiteHeader(page, () => renderTimetablePage(page));
    page.querySelector('[data-lite-action="back"]')?.addEventListener("click", () => {
      setPhoneActiveApp(page.parentElement, "");
      page.remove();
    });
    page.querySelectorAll("[data-timetable-mode]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        page.dataset.timetableMode = button.getAttribute("data-timetable-mode") || "modified";
        page.dataset.timetableEdit = "";
        delete page.dataset.timetableDetailEditing;
        page.dataset.timetableNotice = "";
        rerenderTimetablePagePreservingScroll(page);
      });
    });
    page.querySelector("[data-timetable-edit-toggle]")?.addEventListener("click", async (event) => {
      event.preventDefault();
      if (page.dataset.timetableEdit === "select") {
        page.dataset.timetableEdit = "";
        delete page.dataset.timetableDetailEditing;
        page.dataset.timetableNotice = "已取消本次课程表修改。";
        rerenderTimetablePagePreservingScroll(page);
        return;
      }
      const requirement = timetableModificationCouponCount();
      const editableModifiedCells = timetableEditableModifiedCellCount(timetable, context);
      if (requirement < 1 && editableModifiedCells < 1) {
        page.dataset.timetableNotice = "需要" + TIMETABLE_MOD_COUPON_ITEM + "（VIP6 / " + TIMETABLE_MOD_COUPON_PRICE + "星光点购买）。";
        rerenderTimetablePagePreservingScroll(page);
        return;
      }
      if (!context.canModifyToday || !context.remainingPeriods.size) {
        page.dataset.timetableNotice = "当前没有可修改的当天剩余课程。课程表魔改券和已魔改格子都只能用于今天还没结束的一节课。";
        rerenderTimetablePagePreservingScroll(page);
        return;
      }
      page.dataset.timetableMode = "modified";
      page.dataset.timetableEdit = "select";
      delete page.dataset.timetableDetailEditing;
      page.dataset.timetableNotice = requirement < 1
        ? "请选择今天剩余课程中已经魔改过的一节重命名，不会消耗课程表魔改券。"
        : "请选择今天剩余课程中的一节。新魔改保存后消耗1张" + TIMETABLE_MOD_COUPON_ITEM + "；已魔改格子重命名不再扣券。";
      rerenderTimetablePagePreservingScroll(page);
    });
    page.querySelectorAll("[data-timetable-cell]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const day = Math.max(1, Math.min(5, Number(button.getAttribute("data-timetable-day")) || 1));
        const period = Math.max(1, Math.min(6, Number(button.getAttribute("data-timetable-period")) || 1));
        const selectedTable = readWeeklyTimetable();
        const isModified = weeklyTimetableIsModified(day, period, selectedTable);
        page.dataset.timetableSelectedDay = String(day);
        page.dataset.timetableSelectedPeriod = String(period);
        page.dataset.timetableSelectedConsumeCoupon = isModified ? "" : "true";
        delete page.dataset.timetableDetailEditing;
        page.dataset.timetableNotice = "";
        rerenderTimetablePagePreservingScroll(page);
      });
    });
    page.querySelector("[data-timetable-detail-edit]")?.addEventListener("click", (event) => {
      event.preventDefault();
      page.dataset.timetableMode = "modified";
      page.dataset.timetableEdit = "";
      page.dataset.timetableDetailEditing = "true";
      page.dataset.timetableNotice = "";
      rerenderTimetablePagePreservingScroll(page);
    });
    const detailInput = page.querySelector("[data-timetable-detail-input]");
    if (detailInput) {
      try { detailInput.focus(); detailInput.select(); } catch {}
    }
    page.querySelector("[data-timetable-detail-save]")?.addEventListener("click", async (event) => {
      event.preventDefault();
	  if (page.dataset.timetableSaving === "true") return;
      const state = timetableSelectedState(page);
      if (!state) return;
      const nextSubject = String(page.querySelector("[data-timetable-detail-input]")?.value || "").trim() || "自习";
      const rawNextDescription = String(page.querySelector("[data-timetable-detail-description]")?.value || "").trim();
      const nextDescription = rawNextDescription || defaultCourseDescription(nextSubject);
      if (nextSubject === state.currentSubject && nextDescription === state.currentDescription) {
        page.dataset.timetableNotice = state.consumeCoupon ? "未修改课程名，未消耗课程表魔改券。" : "课程名未变化。";
        rerenderTimetablePagePreservingScroll(page);
        return;
      }
      const saveContext = timetableCurrentContext();
      if (!timetableCanUseCouponForCell(state.day, state.period, saveContext)) {
        page.dataset.timetableNotice = state.consumeCoupon ? "只能修改今天剩余课程中的一节。" : "已魔改格子也只能修改今天还没结束的课节。";
        rerenderTimetablePagePreservingScroll(page);
        return;
      }
	  page.dataset.timetableSaving = "true";
	  const commitDetails = {
	    day: state.day,
	    period: state.period,
	    dateText: saveContext.dateText,
	    weekday: saveContext.weekday,
	    timeText: saveContext.timeText,
	    label: state.label,
	    originalSubject: state.originalSubject,
	    currentSubject: state.currentSubject,
	    nextSubject,
	    originalDescription: state.originalDescription,
	    currentDescription: state.currentDescription,
	    nextDescription
	  };
	  let result;
	  try {
	    result = state.consumeCoupon
	      ? await consumeTimetableModificationCoupon(commitDetails)
	      : await appendTimetableRenameOperation(commitDetails);
	  } catch {
	    result = { ok: false, reason: "课程表修改发生异常，未确认保存。" };
	  } finally {
	    delete page.dataset.timetableSaving;
	  }
	  if (!result?.ok) {
	    page.dataset.timetableNotice = result?.reason || "课程表修改失败，未保存任何变化。";
	    rerenderTimetablePagePreservingScroll(page);
	    return;
	  }
      page.dataset.timetableEdit = "";
      delete page.dataset.timetableDetailEditing;
      page.dataset.timetableSelectedConsumeCoupon = "";
      page.dataset.timetableNotice = state.consumeCoupon
        ? "已消耗1张" + TIMETABLE_MOD_COUPON_ITEM + "，修改了" + state.label + "。"
        : "已重命名" + state.label + "。";
      rerenderTimetablePagePreservingScroll(page);
    });
  }

  const PERSON_PROFILE_INFO_FIELDS = [
    { key: "姓名", label: "姓　名" },
    { key: "性别", label: "性　别" },
    { key: "年龄", label: "年　龄" },
    { key: "社团/职业", label: "社　团" },
    { key: "身高", label: "身　高" },
    { key: "体重", label: "体　重" },
    { key: "三围", label: "三　围" }
  ];
  const PERSON_PROFILE_CLOTHING_FIELDS = [
    { key: "头发", label: "头　发", long: true },
    { key: "面部", label: "面　部", long: true },
    { key: "上衣", label: "上　衣", long: true },
    { key: "下衣", label: "下　衣", long: true }
  ];
  const PERSON_PROFILE_TABS = [
    { id: "clothing", label: "衣着" },
    { id: "info", label: "信息" },
    { id: "state", label: "状态" },
    { id: "sensitivity", label: "敏感" },
    { id: "effects", label: "效果" }
  ];
  const PERSON_PROFILE_PRIMARY_TABS = ["clothing", "info", "state", "events", "items"];
  const PERSON_PROFILE_CONFIDENTIAL_TABS = ["sensitivity", "effects", "bad-records", "remodel", "children"];
  const ST_PROFILE_UI_STATE_STORAGE_PREFIX = "hypnoos:profile-ui:v2";
  const ST_PROFILE_NAV_NORMAL_ART = stAssetUrl("profile-ui/profile-nav-normal-v1.png");
  const ST_PROFILE_NAV_CONFIDENTIAL_ART = stAssetUrl("profile-ui/profile-nav-confidential-v1.png");
  const PERSON_PROFILE_DESK_PAGE_SIZE = 6;
  const PERSON_PROFILE_EFFECT_PAGE_SIZE = 3;
  const PROFILE_PHOTO_STORAGE_PREFIX = "hypnoos:profile-photo:v1";
  const PROFILE_PHOTO_IDB_NAME = "hypnoos-profile-photo-storage-v1";
  const PROFILE_PHOTO_IDB_STORE = "photos";
  const profilePhotoMemoryStorage = new Map();
  const profilePhotoDeletedStorageKeys = new Set();
  let profilePhotoIdbPromise = null;

  function normalizeRememberedProfileTab(navSet, value) {
    const set = navSet === "confidential" ? "confidential" : "primary";
    const allowed = set === "confidential" ? PERSON_PROFILE_CONFIDENTIAL_TABS : PERSON_PROFILE_PRIMARY_TABS;
    const fallback = set === "confidential" ? "sensitivity" : "clothing";
    const tab = String(value || "");
    return allowed.includes(tab) ? tab : fallback;
  }

  function profileUiStateStorageKey() {
    return ST_PROFILE_UI_STATE_STORAGE_PREFIX + ":" + profileStableStorageScope();
  }

  function readProfileUiState() {
    const fallback = {
      navSet: "primary",
      primaryTab: "clothing",
      confidentialTab: "sensitivity",
      roleName: ""
    };
    try {
      const parsed = JSON.parse(localStorage.getItem(profileUiStateStorageKey()) || "null");
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return fallback;
      const navSet = parsed.navSet === "confidential" ? "confidential" : "primary";
      return {
        navSet,
        primaryTab: normalizeRememberedProfileTab("primary", parsed.primaryTab),
        confidentialTab: normalizeRememberedProfileTab("confidential", parsed.confidentialTab),
        roleName: String(parsed.roleName || "").trim()
      };
    } catch {
      return fallback;
    }
  }

  function writeProfileUiState(page) {
    if (!page?.dataset) return;
    const roleNames = profileRoleNamesForPage(page, getStatsRoles());
    const roleName = isIsaacProfilePage(page) ? "" : (roleNames[normalizeProfileIndex(page, roleNames.length)] || "");
    const navSet = activeProfileNavSet(page);
    const activeTab = profileEventsMode(page) ? "events" : activePersonProfileTab(page);
    if (navSet === "confidential") {
      page.dataset.profileConfidentialTab = normalizeRememberedProfileTab("confidential", activeTab);
    } else {
      page.dataset.profilePrimaryTab = normalizeRememberedProfileTab("primary", activeTab);
    }
    const state = {
      navSet,
      primaryTab: normalizeRememberedProfileTab("primary", page.dataset.profilePrimaryTab),
      confidentialTab: normalizeRememberedProfileTab("confidential", page.dataset.profileConfidentialTab),
      roleName
    };
    try {
      localStorage.setItem(profileUiStateStorageKey(), JSON.stringify(state));
    } catch {}
  }

  function profileRememberPhotoStorage(key, value) {
    if (!key) return;
    const storageKey = String(key);
    profilePhotoDeletedStorageKeys.delete(storageKey);
    profilePhotoMemoryStorage.set(storageKey, String(value || ""));
  }

  function profileOpenPhotoIdb() {
    if (typeof indexedDB === "undefined") return Promise.resolve(null);
    if (profilePhotoIdbPromise) return profilePhotoIdbPromise;
    profilePhotoIdbPromise = new Promise((resolve) => {
      const request = indexedDB.open(PROFILE_PHOTO_IDB_NAME, 1);
      request.onupgradeneeded = () => {
        try {
          const db = request.result;
          if (!db.objectStoreNames.contains(PROFILE_PHOTO_IDB_STORE)) db.createObjectStore(PROFILE_PHOTO_IDB_STORE);
        } catch {}
      };
      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => {
        console.warn("[人物档案] 照片 IndexedDB 打开失败", request.error);
        resolve(null);
      };
      request.onblocked = () => resolve(null);
    });
    return profilePhotoIdbPromise;
  }

  async function profileSetPhotoStorageIdb(key, value) {
    const db = await profileOpenPhotoIdb();
    if (!db) return false;
    return new Promise((resolve) => {
      try {
        const tx = db.transaction(PROFILE_PHOTO_IDB_STORE, "readwrite");
        tx.objectStore(PROFILE_PHOTO_IDB_STORE).put(String(value || ""), String(key || ""));
        tx.oncomplete = () => resolve(true);
        tx.onerror = () => {
          console.warn("[人物档案] 照片 IndexedDB 写入失败", key, tx.error);
          resolve(false);
        };
      } catch (error) {
        console.warn("[人物档案] 照片 IndexedDB 写入失败", key, error);
        resolve(false);
      }
    });
  }

  async function profileGetPhotoStorageIdb(key) {
    const db = await profileOpenPhotoIdb();
    if (!db) return null;
    return new Promise((resolve) => {
      try {
        const tx = db.transaction(PROFILE_PHOTO_IDB_STORE, "readonly");
        const request = tx.objectStore(PROFILE_PHOTO_IDB_STORE).get(String(key || ""));
        request.onsuccess = () => resolve(request.result === undefined ? null : String(request.result || ""));
        request.onerror = () => resolve(null);
      } catch {
        resolve(null);
      }
    });
  }

  async function profileRemovePhotoStorageIdb(key) {
    const db = await profileOpenPhotoIdb();
    if (!db) return false;
    return new Promise((resolve) => {
      try {
        const tx = db.transaction(PROFILE_PHOTO_IDB_STORE, "readwrite");
        tx.objectStore(PROFILE_PHOTO_IDB_STORE).delete(String(key || ""));
        tx.oncomplete = () => resolve(true);
        tx.onerror = () => resolve(false);
      } catch {
        resolve(false);
      }
    });
  }

  function profileReadPhotoStorageString(key) {
    const storageKey = String(key || "");
    if (!storageKey) return "";
    if (profilePhotoMemoryStorage.has(storageKey)) return String(profilePhotoMemoryStorage.get(storageKey) || "");
    try {
      const legacy = localStorage.getItem(storageKey);
      if (legacy) {
        profileRememberPhotoStorage(storageKey, legacy);
        profileSetPhotoStorageIdb(storageKey, legacy).then((ok) => {
          if (ok) {
            try { localStorage.removeItem(storageKey); } catch {}
          }
        });
        return legacy;
      }
    } catch {}
    return "";
  }

  function profileSetPhotoStorage(key, value) {
    const storageKey = String(key || "");
    if (!storageKey) return false;
    profilePhotoDeletedStorageKeys.delete(storageKey);
    profileRememberPhotoStorage(storageKey, value);
    try { localStorage.removeItem(storageKey); } catch {}
    profileSetPhotoStorageIdb(storageKey, String(value || ""));
    return true;
  }

  function profileRemovePhotoStorage(key) {
    const storageKey = String(key || "");
    if (!storageKey) return false;
    profilePhotoDeletedStorageKeys.add(storageKey);
    profilePhotoMemoryStorage.delete(storageKey);
    try { localStorage.removeItem(storageKey); } catch {}
    profileRemovePhotoStorageIdb(storageKey).then(() => {
      profilePhotoDeletedStorageKeys.delete(storageKey);
    });
    return true;
  }

  async function profileHydratePhotoStorageKey(key) {
    const storageKey = String(key || "");
    if (!storageKey || profilePhotoMemoryStorage.has(storageKey)) return false;
    if (profilePhotoDeletedStorageKeys.has(storageKey)) return false;
    const stored = await profileGetPhotoStorageIdb(storageKey);
    if (profilePhotoDeletedStorageKeys.has(storageKey)) return false;
    if (stored !== null) {
      profileRememberPhotoStorage(storageKey, stored);
      try { localStorage.removeItem(storageKey); } catch {}
      return true;
    }
    try {
      const legacy = localStorage.getItem(storageKey);
      if (!legacy) return false;
      profileRememberPhotoStorage(storageKey, legacy);
      profileSetPhotoStorageIdb(storageKey, legacy).then((ok) => {
        if (ok) {
          try { localStorage.removeItem(storageKey); } catch {}
        }
      });
      return true;
    } catch {}
    return false;
  }

  function normalizeProfileGenderFilter(value) {
    const normalized = String(value || "").trim().toLowerCase();
    return normalized === "male" || normalized === "female" ? normalized : "";
  }

  function profileGenderFilterForPage(page) {
    return normalizeProfileGenderFilter(page?.dataset?.profileGender);
  }

  function profileAppTitle(page) {
    return profileGenderFilterForPage(page) === "male" ? "男性档案" : "女性档案";
  }

  function orderedProfileRoleNames(roles, genderFilter = "") {
    const defaults = DEFAULT_ROLE_NAMES.filter((name) => Object.prototype.hasOwnProperty.call(roles, name));
    const rest = Object.keys(roles).filter((name) => name && !DEFAULT_ROLE_NAMES.includes(name)).sort((a, b) => a.localeCompare(b, "zh-CN"));
    const ordered = orderRoleNamesByFavorites(defaults.concat(rest));
    const normalizedFilter = normalizeProfileGenderFilter(genderFilter);
    if (normalizedFilter === "female") return ordered.filter((name) => isFemaleRole(name, roles[name]));
    if (normalizedFilter === "male") return ordered.filter((name) => isMaleRole(name, roles[name]));
    return ordered;
  }

  function profileRoleNamesForPage(page, roles) {
    return orderedProfileRoleNames(roles, profileGenderFilterForPage(page));
  }

  function isIsaacProfilePage(page) {
    return false;
  }

  function profilePossessionAvailable(roleName, roleData = null) {
    const name = String(roleName || "").trim();
    if (!ghostPossessionUiUnlocked() || !name || name === ST_GHOST_ROLE_NAME) return false;
    const role = roleData && typeof roleData === "object" ? roleData : getStatsRoles()?.[name];
    return Boolean(role) && !isMaleRole(name, role);
  }

  function profileFavoriteStampHtml() {
    return '<span class="st-profile-favorite-stamp" aria-hidden="true"><svg viewBox="0 0 32 32" focusable="false"><path class="st-profile-favorite-stamp__seal" d="M4 7h24l2 6-3 14H5L2 13z"/><path class="st-profile-favorite-stamp__glyph" d="M16 24.5 8.8 17.8a4.2 4.2 0 0 1 5.9-6l1.3 1.3 1.3-1.3a4.2 4.2 0 0 1 5.9 6Z"/></svg></span>';
  }

  function profilePickerHtml(roleNames, selectedValue, searchValue = "", pickerOpen = false, roles = {}) {
    const query = String(searchValue || "").trim().toLocaleLowerCase("zh-CN");
    const visibleNames = query
      ? roleNames.filter((name) => {
          const roleData = isPlainObject(roles?.[name]) ? roles[name] : {};
          return (name + " " + roleNickname(name, roleData)).toLocaleLowerCase("zh-CN").includes(query);
        })
      : roleNames;
	    const favorite = Boolean(selectedValue) && isFavoriteRoleName(selectedValue);
	    const selectedRoleData = isPlainObject(roles?.[selectedValue]) ? roles[selectedValue] : {};
	    const selectedNickname = selectedValue ? roleNickname(selectedValue, selectedRoleData) : "";
	    const selectedNicknameClass = selectedNickname ? roleNicknameClass(selectedRoleData) : "";
	    const selectedLabelHtml = selectedValue
	      ? '<span class="' + (selectedNickname ? "st-person-select-oldname" : "") + '">' + escapeHtml(selectedValue) + '</span>'
	      : (roleNames.length ? escapeHtml(roleNames[0]) : "没有角色档案");
    const favoriteStampHtml = profileFavoriteStampHtml();
    const favoriteOptionIcon = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m12 20-7-6.5a4 4 0 0 1 5.7-5.6L12 9.2l1.3-1.3a4 4 0 0 1 5.7 5.6Z"/></svg>';
    const groupHtml = (gender, label) => {
      const names = visibleNames.filter((name) => roleGender(name, roles?.[name]) === gender);
      if (!names.length) return "";
      return '<div class="st-person-option-group" data-profile-gender="' + gender + '"><div class="st-person-option-group-title">' + label + '</div>' + names.map((name) => {
          const isSelected = selectedValue === name;
          const isFavorite = isFavoriteRoleName(name);
          return '<div class="st-person-option-row ' + (isSelected ? "active" : "") + '">' +
            '<button type="button" class="st-person-option ' + (isSelected ? "active" : "") + '" data-profile-option="' + escapeAttr(name) + '">' +
              '<strong>' + escapeHtml(name) + '</strong>' + (isFavorite ? '<small class="st-profile-option-stamp" aria-label="已收藏">' + favoriteOptionIcon + '</small>' : '') +
            '</button></div>';
        }).join("") + '</div>';
    };
    const menuHtml = visibleNames.length
      ? groupHtml("女", "女性档案") + groupHtml("男", "男性档案")
      : '<div class="st-person-option-empty">没有匹配角色</div>';
    return '<div class="st-person-picker-wrap">' +
      '<div class="st-person-picker-nickname ' + escapeAttr(selectedNicknameClass) + '" aria-hidden="true">' + (selectedNickname ? escapeHtml(selectedNickname) : "&nbsp;") + '</div>' +
      '<div class="st-person-picker ' + (pickerOpen ? "is-open" : "") + '">' +
	        '<button type="button" class="st-person-select" data-profile-picker-toggle aria-label="选择角色档案" aria-expanded="' + (pickerOpen ? "true" : "false") + '"><span>' + selectedLabelHtml + '</span></button>' +
	        '<button type="button" class="st-person-favorite ' + (favorite ? "active" : "") + '" data-profile-favorite aria-label="' + (favorite ? "取消收藏" : "收藏角色") + '" aria-pressed="' + (favorite ? "true" : "false") + '"' + (!selectedValue ? " disabled" : "") + '>' + favoriteStampHtml + '</button>' +
	        '<input class="st-person-search" type="text" data-profile-search value="' + escapeAttr(searchValue || "") + '" placeholder="搜索" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="搜索角色档案">' +
	        '<div class="st-person-menu" role="listbox">' + menuHtml + '</div>' +
	      '</div>' +
	    '</div>';
	  }

	  function profileStorageScope() {
	    try {
	      const slotScope = window.__ST_HYPNOOS_FRONTEND_SLOT_SCOPE__?.();
	      if (slotScope) return String(slotScope);
	    } catch {}
	    try {
	      const id = window?.SillyTavern?.getCurrentChatId?.();
	      if (id !== undefined && id !== null && String(id)) return String(id);
    } catch {}
    try {
      const id = getCurrentMessageIdSafe();
      if (id !== null && id !== undefined) return "message-" + String(id);
    } catch {}
    return "global";
  }

  function profileStableStorageScope() {
    try {
      const id = window?.SillyTavern?.getCurrentChatId?.();
      if (id !== undefined && id !== null && String(id)) return "chat:" + String(id);
    } catch {}
    try {
      const context = window.SillyTavern?.getContext?.() || (typeof getContext === "function" ? getContext() : null);
      for (const value of [context?.chatId, context?.chat_id, context?.chatFile, context?.chat_file, context?.characterId, context?.groupId]) {
        const text = String(value ?? "").trim();
        if (text) return "ctx:" + text;
      }
    } catch {}
    return "global";
  }

  function profilePhotoStorageKey(roleName) {
    return PROFILE_PHOTO_STORAGE_PREFIX + ":" + profileStorageScope() + ":" + roleName;
  }

  function profilePhotoStorageKeyForScope(scope, roleName) {
    return PROFILE_PHOTO_STORAGE_PREFIX + ":" + String(scope || profileStorageScope()) + ":" + roleName;
  }

  function profileStablePhotoStorageKey(roleName) {
    return PROFILE_PHOTO_STORAGE_PREFIX + ":stable:" + profileStableStorageScope() + ":" + roleName;
  }

  function profilePhotoSlotsStorageKey(roleName) {
    return PROFILE_PHOTO_STORAGE_PREFIX + ":slots:" + profileStorageScope() + ":" + roleName;
  }

  function profilePhotoSlotsStorageKeyForScope(scope, roleName) {
    return PROFILE_PHOTO_STORAGE_PREFIX + ":slots:" + String(scope || profileStorageScope()) + ":" + roleName;
  }

  function profileStablePhotoSlotsStorageKey(roleName) {
    return PROFILE_PHOTO_STORAGE_PREFIX + ":slots:stable:" + profileStableStorageScope() + ":" + roleName;
  }

  function profilePhotoReadKeys(roleName) {
    const keys = [];
    const addKey = (key) => {
      const text = String(key || "").trim();
      if (text && !keys.includes(text)) keys.push(text);
    };
    addKey(profilePhotoStorageKey(roleName));
    try {
      const previous = window.__ST_HYPNOOS_PREVIOUS_FRONTEND_MESSAGE_SCOPE__?.();
      if (previous) addKey(profilePhotoStorageKeyForScope(previous, roleName));
    } catch {}
    addKey(profileStablePhotoStorageKey(roleName));
    return keys;
  }

  function profilePhotoSlotsReadKeys(roleName) {
    const keys = [];
    const addKey = (key) => {
      const text = String(key || "").trim();
      if (text && !keys.includes(text)) keys.push(text);
    };
    addKey(profilePhotoSlotsStorageKey(roleName));
    try {
      const previous = window.__ST_HYPNOOS_PREVIOUS_FRONTEND_MESSAGE_SCOPE__?.();
      if (previous) addKey(profilePhotoSlotsStorageKeyForScope(previous, roleName));
    } catch {}
    addKey(profileStablePhotoSlotsStorageKey(roleName));
    return keys;
  }

  function profilePhotoAllReadKeys(roleName) {
    const keys = [];
    const addKey = (key) => {
      const text = String(key || "").trim();
      if (text && !keys.includes(text)) keys.push(text);
    };
    profilePhotoSlotsReadKeys(roleName).forEach(addKey);
    profilePhotoReadKeys(roleName).forEach(addKey);
    return keys;
  }

  function profileHydratePhotoStorageForRoles(page, roleNames) {
    const names = (Array.isArray(roleNames) ? roleNames : []).map((name) => String(name || "").trim()).filter(Boolean);
    if (!page || !names.length) return;
    const keys = [];
    names.forEach((name) => profilePhotoAllReadKeys(name).forEach((key) => {
      if (key && !keys.includes(key)) keys.push(key);
    }));
    const pending = keys.filter((key) => !profilePhotoMemoryStorage.has(String(key || "")));
    if (!pending.length) return;
    const signature = pending.join("\\n");
    if (page.__stProfilePhotoHydratingSignature === signature) return;
    page.__stProfilePhotoHydratingSignature = signature;
    Promise.all(pending.map(profileHydratePhotoStorageKey)).then((results) => {
      if (!page.isConnected) return;
      page.__stProfilePhotoHydratingSignature = "";
      if (results.some(Boolean)) renderPersonProfilePage(page);
    }).catch(() => {
      if (page) page.__stProfilePhotoHydratingSignature = "";
    });
  }

  const SCENE_SILHOUETTE_STORAGE_PREFIX = "hypnoos:scene-silhouette:v1";

  function sceneSilhouetteStorageScene(scene) {
    const value = String(scene || "").trim();
    return value === "hospital-remodel" ? "hospital-remodel" : "police-trait";
  }

  function sceneSilhouetteStorageKey(scene, roleName) {
    return SCENE_SILHOUETTE_STORAGE_PREFIX + ":" + sceneSilhouetteStorageScene(scene) + ":" + profileStorageScope() + ":" + String(roleName || "");
  }

  function sceneStableSilhouetteStorageKey(scene, roleName) {
    return SCENE_SILHOUETTE_STORAGE_PREFIX + ":" + sceneSilhouetteStorageScene(scene) + ":stable:" + profileStableStorageScope() + ":" + String(roleName || "");
  }

  function sceneSilhouetteReadKeys(scene, roleName) {
    const keys = [];
    const addKey = (key) => {
      const text = String(key || "").trim();
      if (text && !keys.includes(text)) keys.push(text);
    };
    addKey(sceneSilhouetteStorageKey(scene, roleName));
    try {
      const previous = window.__ST_HYPNOOS_PREVIOUS_FRONTEND_MESSAGE_SCOPE__?.();
      if (previous) addKey(SCENE_SILHOUETTE_STORAGE_PREFIX + ":" + sceneSilhouetteStorageScene(scene) + ":" + previous + ":" + String(roleName || ""));
    } catch {}
    addKey(sceneStableSilhouetteStorageKey(scene, roleName));
    return keys;
  }

  function sceneReadLocalSilhouette(scene, roleName) {
    for (const key of sceneSilhouetteReadKeys(scene, roleName)) {
      const value = profileReadPhotoStorageString(key);
      if (value) return value;
    }
    return "";
  }

  function sceneSetLocalSilhouette(scene, roleName, image) {
    const name = String(roleName || "").trim();
    if (!name) return false;
    const value = String(image || "").trim();
    return [
      sceneSilhouetteStorageKey(scene, name),
      sceneStableSilhouetteStorageKey(scene, name)
    ].some((key) => profileSetPhotoStorage(key, value));
  }

  function sceneClearLocalSilhouette(scene, roleName) {
    const name = String(roleName || "").trim();
    if (!name) return false;
    const keys = new Set(sceneSilhouetteReadKeys(scene, name));
    keys.add(sceneSilhouetteStorageKey(scene, name));
    keys.add(sceneStableSilhouetteStorageKey(scene, name));
    keys.forEach((key) => profileRemovePhotoStorage(key));
    return true;
  }

  function sceneHydrateSilhouetteForRole(page, scene, roleName, rerender) {
    const name = String(roleName || "").trim();
    if (!page || !name) return;
    const keys = sceneSilhouetteReadKeys(scene, name);
    const pending = keys.filter((key) => !profilePhotoMemoryStorage.has(String(key || "")));
    if (!pending.length) return;
    const signature = sceneSilhouetteStorageScene(scene) + "\\n" + name + "\\n" + pending.join("\\n");
    if (page.__stSceneSilhouetteHydratingSignature === signature) return;
    page.__stSceneSilhouetteHydratingSignature = signature;
    Promise.all(pending.map(profileHydratePhotoStorageKey)).then((results) => {
      if (!page.isConnected) return;
      page.__stSceneSilhouetteHydratingSignature = "";
      if (results.some(Boolean) && typeof rerender === "function") rerender();
    }).catch(() => {
      if (page) page.__stSceneSilhouetteHydratingSignature = "";
    });
  }

  function sceneBaseSilhouetteForRole(roleName, scene, fallback = "") {
    return encounterRoleSilhouetteByName(roleName, sceneSilhouetteStorageScene(scene), fallback);
  }

  function sceneSilhouetteForRole(roleName, scene, fallback = "") {
    return sceneReadLocalSilhouette(scene, roleName) || sceneBaseSilhouetteForRole(roleName, scene, fallback);
  }

  function renderSceneSilhouetteDialog(scene, roleName, fallback = "") {
    const sceneId = sceneSilhouetteStorageScene(scene);
    const local = sceneReadLocalSilhouette(sceneId, roleName);
    const base = sceneBaseSilhouetteForRole(roleName, sceneId, fallback);
    const cells = [
      { id: "default", label: "默认剪影", source: base, active: !local },
      { id: "local", label: "本地剪影", source: local, active: Boolean(local) }
    ].map((slot) => (
      '<article class="st-profile-photo-slot ' + (slot.active ? "is-selected" : "") + '">' +
        '<div class="st-profile-photo-preview st-scene-silhouette-preview">' + (slot.source ? '<img alt="' + escapeAttr(roleName + " " + slot.label) + '" src="' + escapeAttr(slot.source) + '">' : '<span>' + escapeHtml(slot.label) + '</span>') + '</div>' +
        '<div class="st-profile-photo-actions">' +
          (slot.id === "local"
            ? '<button type="button" data-scene-silhouette-action="change">更换</button><button type="button" class="danger" data-scene-silhouette-action="delete"' + (!local ? " disabled" : "") + '>删除</button><button type="button" class="primary" data-scene-silhouette-action="select-local"' + (!local || slot.active ? " disabled" : "") + '>' + (slot.active ? "已选" : "选中") + '</button>'
            : '<button type="button" data-scene-silhouette-action="select-default"' + (!local ? " disabled" : "") + '>恢复默认</button>') +
        '</div>' +
      '</article>'
    )).join("");
    return '<div class="st-profile-photo-dialog st-scene-silhouette-dialog" data-scene-silhouette-dialog role="dialog" aria-modal="true" aria-label="管理剪影">' +
      '<section class="st-profile-photo-card">' +
        '<h3>' + escapeHtml(roleName || "角色") + ' · ' + (sceneId === "hospital-remodel" ? "医院剪影" : "警视厅剪影") + '</h3>' +
        '<div class="st-profile-photo-grid">' + cells + '</div>' +
        '<input type="file" accept="image/*" data-scene-silhouette-file hidden>' +
        '<div class="st-profile-photo-footer"><button type="button" data-scene-silhouette-action="close">完成</button></div>' +
      '</section>' +
    '</div>';
  }

  function bindSceneSilhouetteControls(page, scene, roleName, fallback, rerender) {
    const sceneId = sceneSilhouetteStorageScene(scene);
    const name = String(roleName || "").trim();
    if (!page || !name || typeof rerender !== "function") return;
    if (page.dataset.sceneSilhouetteDialog !== undefined) {
      page.dataset.sceneSilhouetteActiveDialog = page.dataset.sceneSilhouetteDialog;
      delete page.dataset.sceneSilhouetteDialog;
    }
    page.querySelector("[data-scene-silhouette-open]")?.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      page.dataset.sceneSilhouetteActiveDialog = sceneId;
      rerender();
    });
    const dialog = page.querySelector("[data-scene-silhouette-dialog]");
    if (!dialog) return;
    const close = () => {
      delete page.dataset.sceneSilhouetteActiveDialog;
      rerender();
    };
    dialog.addEventListener("click", (event) => {
      if (event.target === dialog) close();
    });
    dialog.querySelectorAll("[data-scene-silhouette-action]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const action = button.getAttribute("data-scene-silhouette-action") || "";
        if (action === "close") {
          close();
          return;
        }
        if (action === "change") {
          dialog.querySelector("[data-scene-silhouette-file]")?.click();
          return;
        }
        if (action === "delete" || action === "select-default") {
          sceneClearLocalSilhouette(sceneId, name);
          rerender();
          return;
        }
        if (action === "select-local") {
          rerender();
        }
      });
    });
    dialog.querySelector("[data-scene-silhouette-file]")?.addEventListener("change", async (event) => {
      const file = event.target?.files?.[0];
      if (!file) return;
      sceneSetLocalSilhouette(sceneId, name, await encounterFileAsDataUrl(file));
      page.dataset.sceneSilhouetteActiveDialog = sceneId;
      rerender();
    });
  }

  function normalizeProfilePhotoSlots(value) {
    const slots = Array.isArray(value) ? value : [];
    return Array.from({ length: 4 }, (_, index) => {
      const text = String(slots[index] || "").trim();
      return text && !["无", "空", "未记录"].includes(text) ? text : "";
    });
  }

  function profileSaveLocalPhotoSlots(roleName, slots, selectedIndex = 0) {
    if (!roleName) return false;
    const normalizedSlots = normalizeProfilePhotoSlots(slots);
    const availableIndex = normalizedSlots.findIndex(Boolean);
    const normalizedSelected = normalizedSlots[selectedIndex] ? Math.max(0, Math.min(3, Math.trunc(Number(selectedIndex) || 0))) : Math.max(0, availableIndex);
    const state = {
      version: 3,
      selected: normalizedSelected >= 0 ? normalizedSelected : 0,
      slots: normalizedSlots
    };
    let saved = false;
    for (const key of [profilePhotoSlotsStorageKey(roleName), profileStablePhotoSlotsStorageKey(roleName)]) {
      if (profileSetPhotoStorage(key, JSON.stringify(state))) saved = true;
    }
    if (saved) refreshGalgameCardsForRole(roleName);
    return saved;
  }

  function profileReadLocalPhotoSlotsState(roleName) {
    for (const key of profilePhotoSlotsReadKeys(roleName)) {
      try {
        const raw = profileReadPhotoStorageString(key);
        if (!raw) continue;
        const parsed = JSON.parse(raw);
        if (!parsed || !Array.isArray(parsed.slots)) continue;
        let slots = normalizeProfilePhotoSlots(parsed.slots);
        const selected = Math.max(0, Math.min(3, Math.trunc(Number(parsed?.selected) || 0)));
        const configured = ST_DEFAULT_PROFILE_PHOTO_SLOTS[roleName];
        if (Number(parsed?.version || 0) < 3 && Array.isArray(configured) && configured.length) {
          const defaults = normalizeProfilePhotoSlots(configured);
          const merged = slots.slice();
          defaults.forEach((source, index) => {
            if (source && !merged[index]) merged[index] = source;
          });
          slots = merged;
          profileSaveLocalPhotoSlots(roleName, slots, slots[selected] ? selected : 0);
        }
        const firstFilled = slots.findIndex(Boolean);
        return { slots, selected: slots[selected] ? selected : firstFilled >= 0 ? firstFilled : 0 };
      } catch {}
    }
    const configured = ST_DEFAULT_PROFILE_PHOTO_SLOTS[roleName];
    if (Array.isArray(configured) && configured.length) return null;
    const legacy = localProfilePhoto(roleName);
    if (legacy) return { slots: normalizeProfilePhotoSlots([legacy]), selected: 0 };
    return null;
  }

  function profileSaveLocalPhoto(roleName, value) {
    const image = String(value || "");
    if (!roleName || !image) return false;
    let saved = false;
    for (const key of [profilePhotoStorageKey(roleName), profileStablePhotoStorageKey(roleName)]) {
      if (profileSetPhotoStorage(key, image)) saved = true;
    }
    const configured = ST_DEFAULT_PROFILE_PHOTO_SLOTS[roleName];
    if (Array.isArray(configured) && configured.length) {
      const slots = normalizeProfilePhotoSlots(configured);
      const matched = slots.findIndex((source) => source === image);
      if (matched >= 0) {
        profileSaveLocalPhotoSlots(roleName, slots, matched);
      } else {
        slots[0] = image;
        profileSaveLocalPhotoSlots(roleName, slots, 0);
      }
    } else {
      profileSaveLocalPhotoSlots(roleName, [image], 0);
    }
    return saved;
  }

  function profileClearLocalPhotoSlots(roleName) {
    if (!roleName) return false;
    const keys = [];
    const addKey = (key) => {
      const text = String(key || "").trim();
      if (text && !keys.includes(text)) keys.push(text);
    };
    profilePhotoSlotsReadKeys(roleName).forEach(addKey);
    profilePhotoReadKeys(roleName).forEach(addKey);
    addKey(profilePhotoSlotsStorageKey(roleName));
    addKey(profileStablePhotoSlotsStorageKey(roleName));
    addKey(profilePhotoStorageKey(roleName));
    addKey(profileStablePhotoStorageKey(roleName));
    let changed = false;
    keys.forEach((key) => {
      try {
        if (profilePhotoMemoryStorage.has(String(key || "")) || localStorage.getItem(key) !== null) changed = true;
      } catch {}
      profileRemovePhotoStorage(key);
    });
    refreshGalgameCardsForRole(roleName);
    return changed || keys.length > 0;
  }

  function localProfilePhoto(roleName) {
    for (const key of profilePhotoReadKeys(roleName)) {
      try {
        const value = profileReadPhotoStorageString(key);
        if (value) return value;
      } catch {}
    }
    return "";
  }

  function profileEncounterRolePhotoSlots(roleName) {
    const targetKey = encounterRoleNameKey(roleName);
    if (!targetKey) return [];
    const readSlots = (role) => {
      if (encounterRoleNameKey(role?.name) !== targetKey) return [];
      return encounterRoleImageSlots(role).map((source) => source ? encounterImageAssetUrl(source) : "");
    };
    try {
      for (const pkg of encounterReadPackages()) {
        for (const role of (Array.isArray(pkg?.roles) ? pkg.roles : [])) {
          const slots = readSlots(role);
          if (slots.some(Boolean)) return slots;
        }
      }
    } catch {}
    try {
      for (const role of encounterReadStandaloneRoles()) {
        const slots = readSlots(role);
        if (slots.some(Boolean)) return slots;
      }
    } catch {}
    return [];
  }

  function defaultProfilePhotoSlots(roleName, roleData) {
    if (isOtakuFemaleForm(roleName, roleData)) return normalizeProfilePhotoSlots([ST_OTAKU_FEMALE_PROFILE_PHOTO]);
    const configured = ST_DEFAULT_PROFILE_PHOTO_SLOTS[roleName];
    if (Array.isArray(configured) && configured.length) return normalizeProfilePhotoSlots(configured);
    const encounterSlots = profileEncounterRolePhotoSlots(roleName);
    if (encounterSlots.some(Boolean)) return normalizeProfilePhotoSlots(encounterSlots);
    const single = ST_DEFAULT_PROFILE_PHOTOS[roleName] || "";
    return normalizeProfilePhotoSlots(single ? [single] : []);
  }

  function profilePhotoSlotsState(roleName, roleData) {
    const local = profileReadLocalPhotoSlotsState(roleName);
    if (local) return local;
    const profile = roleProfileData(roleName, roleData);
    const source = effectScalar(profile["照片"]).trim();
    if (source && !["无", "空", "未记录"].includes(source)) return { slots: normalizeProfilePhotoSlots([source]), selected: 0 };
    const slots = defaultProfilePhotoSlots(roleName, roleData);
    return { slots, selected: slots.findIndex(Boolean) >= 0 ? Math.max(0, slots.findIndex(Boolean)) : 0 };
  }

  function isOtakuRoleName(roleName) {
    return roleName === "阿宅" || roleName === "阿宅君";
  }

  function isOtakuFemaleForm(roleName, roleData) {
    return isOtakuRoleName(roleName) && isFemaleRole(roleName, roleData);
  }

  function isOtakuMaleForm(roleName, roleData) {
    return isOtakuRoleName(roleName) && isMaleRole(roleName, roleData);
  }

  function canRequestOtakuFemaleTransform(roleName, roleData) {
    if (!isOtakuRoleName(roleName) || isOtakuFemaleForm(roleName, roleData)) return false;
    return statNumber(statValue(roleData, "好感度"), 0) >= 100
      && statNumber(statValue(roleData, "服从度"), 0) >= 100;
  }

  function profilePhotoSource(roleName, roleData) {
    const state = profilePhotoSlotsState(roleName, roleData);
    return state.slots[state.selected] || state.slots.find(Boolean) || "";
  }

  function profileFieldText(profile, roleName, field) {
    const value = effectScalar(profile[field.key]).trim();
    if (value) {
      return value;
    }
    if (field.key === "姓名") return roleName || "未记录";
    return "未记录";
  }

  function personProfileInfoFields(roleName, profile, roleData = null) {
    if (isOtakuRoleName(roleName)) {
      if (isOtakuFemaleForm(roleName, roleData)) return PERSON_PROFILE_INFO_FIELDS;
      return PERSON_PROFILE_INFO_FIELDS.map((field) => field.key === "三围"
        ? { key: "阴茎长度", label: "阴茎长度" }
        : field);
    }
    const hasMaleLengthValue = Boolean(effectScalar(profile?.["阴茎长度"]).trim());
    const hasFemaleMeasurement = Boolean(effectScalar(profile?.["三围"]).trim()) && !hasMaleLengthValue;
    const hasMaleLength = !hasFemaleMeasurement && hasMaleLengthValue;
    if (!hasMaleLength) return PERSON_PROFILE_INFO_FIELDS;
    return PERSON_PROFILE_INFO_FIELDS.map((field) => field.key === "三围"
      ? { key: "阴茎长度", label: "阴茎长度" }
      : field);
  }

