  function openTimetablePage(tile) {
    ensureStyle();
    ensurePhoneDarkThemeStyle();
    const root = findPhoneRoot(tile);
    setPhoneActiveApp(root, "timetable");
    root.style.position = root.style.position || "relative";
    clearPhoneInternalOverlays(root);
    const page = document.createElement("section");
    page.className = "st-lite-app st-timetable-app";
    page.setAttribute("aria-label", "课程表");
    root.appendChild(page);
    renderTimetablePage(page);
  }

  function normalizeClockPart(value, max) {
    const parsed = Number.parseInt(String(value ?? "").replace(/\\D/g, ""), 10);
    if (!Number.isFinite(parsed)) return 0;
    return Math.max(0, Math.min(max, parsed));
  }

  function sanitizeClockInputValue(value, max, pad = false) {
    const digits = String(value ?? "").replace(/\\D/g, "").slice(0, 2);
    if (!digits) return "";
    const safe = String(Math.max(0, Math.min(max, Number.parseInt(digits, 10) || 0)));
    return pad ? safe.padStart(2, "0") : safe;
  }

  function normalizeClockDateOffset(value) {
    const parsed = Math.trunc(Number(value) || 0);
    return Math.max(0, Math.min(2, parsed));
  }

  function clockCurrentDateText() {
    return systemStoryDateText(getSystemState());
  }

  function storyDateLabelAfter(dateText, offset = 0) {
    let label = String(dateText || "").trim() || "2024年4月9日";
    const count = normalizeClockDateOffset(offset);
    for (let index = 0; index < count; index += 1) label = nextStoryDateLabel(label);
    return label;
  }

  function clockDateOptions(currentDateText = clockCurrentDateText()) {
    const labels = ["今天", "明天", "后天"];
    return labels.map((label, offset) => {
      const dateText = storyDateLabelAfter(currentDateText, offset);
      const weekday = weekdayForStoryDate(dateText);
      return { offset, label, dateText, weekday };
    });
  }

  function clockCurrentStamp() {
    const dateText = clockCurrentDateText();
    const parsed = parseStoryDate(dateText) || parseStoryDate("2024年4月9日");
    const minutes = minutesFromTimeText(storyTimeOnly(getSystemState()["当前时间"], "00:00"));
    return storyDateSerialDay(parsed) * 1440 + minutes;
  }

  function clockTargetStamp(dateText, timeText) {
    const parsed = parseStoryDate(dateText);
    if (!parsed) return NaN;
    const minutes = minutesFromTimeText(timeText);
    return storyDateSerialDay(parsed) * 1440 + minutes;
  }

  function clockTargetInfo(hour, minute, offset) {
    const currentDateText = clockCurrentDateText();
    const currentTimeText = storyTimeOnly(getSystemState()["当前时间"], "未知");
    const safeOffset = normalizeClockDateOffset(offset);
    const targetDateText = storyDateLabelAfter(currentDateText, safeOffset);
    const targetTimeText = formatClockInput(hour, minute);
    const currentParsed = parseStoryDate(currentDateText) || parseStoryDate("2024年4月9日");
    const currentMinutes = minutesFromTimeText(storyTimeOnly(getSystemState()["当前时间"], "00:00"));
    const targetMinutes = minutesFromTimeText(targetTimeText);
    const currentStamp = storyDateSerialDay(currentParsed) * 1440 + currentMinutes;
    const targetStamp = storyDateSerialDay(currentParsed) * 1440 + safeOffset * 1440 + targetMinutes;
    const maxStamp = currentStamp + 2 * 1440;
    const tooEarly = Number.isFinite(targetStamp) && targetStamp < currentStamp;
    const tooLate = Number.isFinite(targetStamp) && targetStamp > maxStamp;
    return {
      currentDateText,
      currentTimeText,
      targetDateText,
      targetTimeText,
      currentStamp,
      targetStamp,
      maxStamp,
      tooEarly,
      tooLate,
      valid: Number.isFinite(targetStamp) && !tooEarly && !tooLate
    };
  }

  function pendingRawOperationPayloads() {
    const entries = Array.isArray(window.__ST_OPERATION_INPUT_LOG__) ? window.__ST_OPERATION_INPUT_LOG__ : [];
    return entries.map((entry) => operationEntryPayload(entry));
  }

  function pendingOperationPayloads() {
    const entries = window.__ST_GET_PENDING_OPERATION_INPUT_LOG__?.() || window.__ST_OPERATION_INPUT_LOG__ || [];
    return Array.from(entries).map((entry) => operationEntryPayload(entry));
  }

  function pendingPayloadMatches(payload, sourcePattern, operationPattern) {
    if (!payload || typeof payload !== "object") return false;
    const source = String(payload["来源"] || "").trim();
    const operation = String(payload["操作"] || "").trim();
    const sourceMatched = sourcePattern instanceof RegExp ? sourcePattern.test(source) : source === String(sourcePattern || "").trim();
    const operationMatched = operationPattern instanceof RegExp ? operationPattern.test(operation) : operation === String(operationPattern || "").trim();
    return sourceMatched && operationMatched;
  }

  function hasPendingClockSuggestionOperation() {
    return pendingRawOperationPayloads().some((payload) => pendingPayloadMatches(payload, "时钟", /强制剧情开始时间|强制时间|目标时间|建议剧情开始时间|建议时间|当前时间|推进到该时间/));
  }

  function hasPendingStoryLocationOperation() {
    return pendingOperationPayloads().some((payload) => pendingPayloadMatches(payload, /^(地图|学校地图|主教学楼地图)$/, "建议剧情地点"));
  }

  function getClockSeed() {
    const text = storyTimeOnly(getSystemState()["当前时间"], "12:00");
    const minutes = minutesFromTimeText(text);
    const safeMinutes = Number.isFinite(minutes) ? minutes : 12 * 60;
    return { hour: Math.floor(safeMinutes / 60) % 24, minute: safeMinutes % 60 };
  }

  function formatClockInput(hour, minute) {
    return String(hour).padStart(2, "0") + ":" + String(minute).padStart(2, "0");
  }

  function updateClockFace(page) {
    const hour = normalizeClockPart(page.querySelector("[data-clock-hour]")?.value, 23);
    const minute = normalizeClockPart(page.querySelector("[data-clock-minute]")?.value, 59);
    const hourDeg = ((hour % 12) + minute / 60) * 30;
    const minuteDeg = minute * 6;
    const hourHand = page.querySelector(".st-clock-hand.hour");
    const minuteHand = page.querySelector(".st-clock-hand.minute");
    if (hourHand) hourHand.style.transform = "rotate(" + hourDeg + "deg)";
    if (minuteHand) minuteHand.style.transform = "rotate(" + minuteDeg + "deg)";
    const label = page.querySelector(".st-clock-time");
    if (label) label.textContent = formatClockInput(hour, minute);
  }

	  function updateClockActionState(page) {
	    const pendingClock = hasPendingClockSuggestionOperation();
	    const hour = normalizeClockPart(page.querySelector("[data-clock-hour]")?.value, 23);
    const minute = normalizeClockPart(page.querySelector("[data-clock-minute]")?.value, 59);
    const offset = normalizeClockDateOffset(page.querySelector("[data-clock-date-offset]:checked")?.value ?? page.dataset.clockDateOffset);
    page.dataset.clockDateOffset = String(offset);
    const info = clockTargetInfo(hour, minute, offset);
	    const button = page.querySelector('[data-clock-action="suggest"]');
	    if (button) {
	      button.disabled = Boolean(pendingClock || !info.valid);
	      button.textContent = pendingClock ? "已暂存" : info.tooEarly ? "时间已过" : info.tooLate ? "超过2天" : "锚定此时间";
    }
    const validation = page.querySelector("[data-clock-validation]");
    if (validation) {
      validation.textContent = info.tooEarly
        ? "目标不能早于当前变量时间（" + info.currentDateText + " " + info.currentTimeText + "）。"
        : info.tooLate
          ? "目标不能超过当前变量时间后2天。"
          : "目标：" + info.targetDateText + " " + info.targetTimeText;
    }
    const header = page.querySelector("[data-clock-header-target]");
    if (header) header.textContent = info.targetDateText + " " + info.targetTimeText;
    return info;
  }

  function setClockValue(page, hour, minute) {
    const hourInput = page.querySelector("[data-clock-hour]");
    const minuteInput = page.querySelector("[data-clock-minute]");
    if (hourInput) hourInput.value = String(normalizeClockPart(hour, 23)).padStart(2, "0");
    if (minuteInput) minuteInput.value = String(normalizeClockPart(minute, 59)).padStart(2, "0");
    updateClockFace(page);
  }

		  function renderClockPage(page) {
		    const seed = getClockSeed();
		    const pendingClock = hasPendingClockSuggestionOperation();
		    const selectedOffset = normalizeClockDateOffset(page.dataset.clockDateOffset);
		    page.dataset.clockDateOffset = String(selectedOffset);
		    const targetInfo = clockTargetInfo(seed.hour, seed.minute, selectedOffset);
		    const clockActionLocked = pendingClock || !targetInfo.valid;
	    if (!page.dataset.clockDateGroupName) page.dataset.clockDateGroupName = "st-clock-date-" + Math.random().toString(36).slice(2, 9);
	    const dateGroupName = page.dataset.clockDateGroupName;
	    const dateOptions = clockDateOptions(targetInfo.currentDateText).map((option) => (
	      '<label><input type="radio" name="' + escapeAttr(dateGroupName) + '" data-clock-date-offset value="' + option.offset + '"' + (option.offset === selectedOffset ? " checked" : "") + '><span>' +
	        escapeHtml(option.label) + '<small>' + escapeHtml(option.dateText + (option.weekday ? " · " + option.weekday.replace(/^星期/, "周") : "")) + '</small>' +
	      '</span></label>'
	    )).join("");
    const marks = Array.from({ length: 12 }, (_, index) => {
      const angle = index * 30;
      const radians = angle * Math.PI / 180;
      const x = 50 + Math.sin(radians) * 42;
      const y = 50 - Math.cos(radians) * 42;
      return '<i class="st-clock-mark" style="left:' + x.toFixed(2) + '%;top:' + y.toFixed(2) + '%;transform:translate(-50%,-50%) rotate(' + angle + 'deg)"></i>';
    }).join("");
    page.innerHTML =
      renderLiteHeader(page, { title: "时钟", html: '<strong data-clock-header-target>' + escapeHtml(targetInfo.targetDateText + " " + formatClockInput(seed.hour, seed.minute)) + '</strong>' }) +
      '<main class="st-lite-body">' +
        '<section class="st-lite-card st-clock-card">' +
          '<div class="st-clock-face" aria-hidden="true">' + marks +
            '<i class="st-clock-hand hour"></i><i class="st-clock-hand minute"></i><i class="st-clock-center"></i>' +
          '</div>' +
          '<div class="st-clock-time">' + escapeHtml(formatClockInput(seed.hour, seed.minute)) + '</div>' +
          '<div class="st-clock-date-options">' + dateOptions + '</div>' +
          '<div class="st-clock-inputs">' +
	            '<label><span>时</span><input data-clock-hour inputmode="numeric" autocomplete="off" maxlength="2" min="0" max="23" value="' + escapeAttr(String(seed.hour).padStart(2, "0")) + '"></label>' +
	            '<b class="st-clock-colon">:</b>' +
	            '<label><span>分</span><input data-clock-minute inputmode="numeric" autocomplete="off" maxlength="2" min="0" max="59" value="' + escapeAttr(String(seed.minute).padStart(2, "0")) + '"></label>' +
          '</div>' +
	          '<button type="button" class="st-clock-action" data-clock-action="suggest"' + (clockActionLocked ? " disabled" : "") + '>' + (pendingClock ? "已暂存" : (targetInfo.tooEarly ? "时间已过" : targetInfo.tooLate ? "超过2天" : "锚定此时间")) + '</button>' +
          '<p class="st-clock-note" data-clock-validation>' + escapeHtml(targetInfo.tooEarly ? "目标不能早于当前变量时间（" + targetInfo.currentDateText + " " + targetInfo.currentTimeText + "）。" : targetInfo.tooLate ? "目标不能超过当前变量时间后2天。" : "目标：" + targetInfo.targetDateText + " " + targetInfo.targetTimeText) + '</p>' +
          '<p class="st-clock-note">这会写入本轮强制日期时间锚点；目标范围为当前变量时间到2天后。</p>' +
        '</section>' +
      '</main>';
    bindLiteHeader(page, () => renderClockPage(page));
	    page.querySelector('[data-lite-action="back"]')?.addEventListener("click", () => {
	      const root = page.parentElement;
	      setPhoneActiveApp(root, "");
	      page.__stClockCleanup?.();
	      page.remove();
	    });
    page.querySelectorAll("[data-clock-hour],[data-clock-minute]").forEach((input) => {
      input.addEventListener("input", () => {
        const max = input.hasAttribute("data-clock-hour") ? 23 : 59;
        input.value = sanitizeClockInputValue(input.value, max, false);
        updateClockFace(page);
        updateClockActionState(page);
      });
      input.addEventListener("blur", () => {
        const max = input.hasAttribute("data-clock-hour") ? 23 : 59;
        input.value = sanitizeClockInputValue(input.value, max, true) || "00";
        updateClockFace(page);
        updateClockActionState(page);
      });
    });
    page.querySelectorAll("[data-clock-date-offset]").forEach((input) => {
      input.addEventListener("change", () => {
        page.dataset.clockDateOffset = String(normalizeClockDateOffset(input.value));
        updateClockActionState(page);
      });
    });
		    page.querySelector('[data-clock-action="suggest"]')?.addEventListener("click", () => {
		      if (hasPendingClockSuggestionOperation()) {
		        renderClockPage(page);
		        return;
		      }
	      const hour = normalizeClockPart(page.querySelector("[data-clock-hour]")?.value, 23);
	      const minute = normalizeClockPart(page.querySelector("[data-clock-minute]")?.value, 59);
	      const suggested = formatClockInput(hour, minute);
	      const offset = normalizeClockDateOffset(page.querySelector("[data-clock-date-offset]:checked")?.value ?? page.dataset.clockDateOffset);
	      const info = clockTargetInfo(hour, minute, offset);
	      if (!info.valid) {
	        updateClockActionState(page);
	        return;
	      }
	      Promise.resolve(appendAppOperation({
	        来源: "时钟",
	        操作: "强制剧情开始时间",
	        暂存摘要: "强制到 " + info.targetDateText + " " + suggested,
	        当前日期: info.currentDateText,
	        当前时间: info.currentTimeText,
	        日期选择: offset === 0 ? "今天" : offset === 1 ? "明天" : "后天",
	        建议时间: suggested,
	        目标日期: info.targetDateText,
	        目标时间: suggested,
	        时间解释: "前端已由用户选择目标日期和目标时间，并校验目标不早于当前变量时间、且不超过当前变量时间后2天。",
	        AI执行规范: "这是用户设置的强制剧情时间锚点，不是可忽略建议。AI必须让本轮剧情从目标日期与目标时间开始或推进到该时间点；除非用户最新正文明确取消或改时间，不得绕开、忽略或另选时间。前端已经判断目标日期：直接按/目标日期和/目标时间执行，不要重新判断是否跨天。只更新/系统/当前时间和必要的/系统/当前事件；目标日期不同于当前日期时同步更新/系统/当前日期。/系统/_当前周几、/系统/_当前日程、/系统/_当前特殊日期和/系统/_课程表为前端只读同步字段，AI不要手写这些字段。"
	      })).then(() => renderClockPage(page));
	    });
    updateClockFace(page);
    updateClockActionState(page);
  }

  function openClockPage(tile) {
    ensureStyle();
    ensurePhoneDarkThemeStyle();
    const root = findPhoneRoot(tile);
    setPhoneActiveApp(root, "clock");
    root.style.position = root.style.position || "relative";
    clearPhoneInternalOverlays(root);
    const page = document.createElement("section");
    page.className = "st-lite-app st-clock-app";
    page.setAttribute("aria-label", "时钟");
	    root.appendChild(page);
	    renderClockPage(page);
	    const refreshFromOperationQueue = () => {
	      if (!page.isConnected) {
	        window.removeEventListener("HYPNOOS_OPERATION_QUEUE_CHANGED", refreshFromOperationQueue);
	        return;
	      }
	      renderClockPage(page);
	    };
	    page.__stClockCleanup = () => window.removeEventListener("HYPNOOS_OPERATION_QUEUE_CHANGED", refreshFromOperationQueue);
	    window.addEventListener("HYPNOOS_OPERATION_QUEUE_CHANGED", refreshFromOperationQueue);
	  }

  function scheduleCourseRowsForDate(parsedDate, weekdayText, table = readWeeklyTimetable(), originalTable = normalizeWeeklyTimetable(ST_WEEKLY_TIMETABLE), descriptions = readWeeklyTimetableDescriptions()) {
    const weekdayIndex = ST_WEEKDAY_INDEX[weekdayText];
    const special = parsedDate ? storyCalendarDay(parsedDate.month, parsedDate.day, parsedDate.year)?.specialDay : null;
    if (!parsedDate || weekdayIndex === 0 || weekdayIndex === 6 || specialDayBlocksClasses(special)) return [];
    return ST_CLASS_PERIODS.map((period) => {
      const originalSubject = weeklyTimetableSubject(weekdayIndex, period.index, originalTable);
      const subject = weeklyTimetableSubject(weekdayIndex, period.index, table);
      const isModified = subject !== originalSubject;
      return {
        课节: period.label,
        科目: originalSubject,
        原课程描述: weeklyTimetableOriginalDescription(weekdayIndex, period.index),
        是否魔改: isModified,
        魔改课程: isModified ? subject : "",
        魔改课程描述: isModified ? weeklyTimetableDescription(weekdayIndex, period.index, table, descriptions) : ""
      };
    });
  }

  function scheduleFirstClassForDate(parsedDate) {
    if (!parsedDate) return { 日期: "", 星期: "", 课节: "无", 时间: "", 科目: "日期未记录" };
    const dateText = storyDateTextFromParts(parsedDate.year, parsedDate.month, parsedDate.day);
    const weekdayText = weekdayForStoryDate(dateText);
    const weekdayIndex = ST_WEEKDAY_INDEX[weekdayText];
    const special = storyCalendarDay(parsedDate.month, parsedDate.day, parsedDate.year)?.specialDay;
    if (weekdayIndex === 0 || weekdayIndex === 6 || specialDayBlocksClasses(special)) return { 日期: dateText, 星期: weekdayText || "", 课节: "无", 时间: "", 科目: "无固定课程" };
    const first = ST_CLASS_PERIODS[0];
    return { 日期: dateText, 星期: weekdayText || "", 课节: first.label, 时间: formatPeriodTime(first.start) + "-" + formatPeriodTime(first.end), 科目: weeklyTimetableSubject(weekdayIndex, first.index) };
  }

  function dailyScheduleForDateTime(dateText, timeText) {
    const parsed = parseStoryDate(dateText);
    if (!parsed) return { 日期: String(dateText || ""), 星期: "", 当前课段: { 名称: "日期未记录", 时间: "" }, 当前日程: "日期未记录", 当前特殊日期: "", 课表: [], 课程表: [], 次日第一节: scheduleFirstClassForDate(null) };
    const safeDateText = storyDateTextFromParts(parsed.year, parsed.month, parsed.day);
    const weekdayText = weekdayForStoryDate(safeDateText) || "";
    const minutes = minutesFromTimeText(storyTimeOnly(timeText, "00:00"));
    const slot = routineSlot(minutes, weekdayText, parsed);
    const calendar = storyCalendarDay(parsed.month, parsed.day, parsed.year);
    const tomorrow = parseStoryDate(nextStoryDateLabel(safeDateText));
    const originalTable = normalizeWeeklyTimetable(ST_WEEKLY_TIMETABLE);
    const modifiedTable = readWeeklyTimetable();
    const rows = scheduleCourseRowsForDate(parsed, weekdayText, modifiedTable, originalTable);
    return { 日期: safeDateText, 星期: weekdayText, 当前课段: { 名称: slot.title || "无", 时间: slot.detail || "" }, 当前日程: slot.title || "无", 当前特殊日期: calendar?.specialText || "", 课表: rows, 课程表: rows, 次日第一节: scheduleFirstClassForDate(tomorrow) };
  }

  function applyReadonlySchedule(system, dateText, timeText, options = {}) {
    const dailySchedule = dailyScheduleForDateTime(dateText, timeText);
    system["_当前周几"] = String(dailySchedule.星期 || "");
    system["_当前日程"] = String(dailySchedule.当前课段?.名称 || dailySchedule.当前日程 || "无");
    system["_当前特殊日期"] = String(dailySchedule.当前特殊日期 || "");
    if (options.syncTimetable !== false) {
      for (const key of ["当天课程表", "当天原课程表", "当天魔改课程表", "课程表"]) if (Object.prototype.hasOwnProperty.call(system, key)) delete system[key];
      system["_课程表"] = normalizeReadonlyTimetableRows(dailySchedule.课程表);
    }
    return dailySchedule;
  }

  function tempHypnosisEffectEndText(value) {
    if (!isPlainObject(value)) return "";
    for (const key of ["结束时间", "到期时间", "持续至", "结束", "endTime", "expiresAt", "until"]) {
      const text = effectScalar(value[key]).trim();
      if (text) return text;
    }
    return "";
  }

  function monitorCurrentStamp() {
    const system = getSystemState();
    const parsed = parseStoryDate(systemStoryDateText(system));
    const minutes = minutesFromTimeText(storyTimeOnly(system["当前时间"], "00:00"));
    if (!parsed) return minutes;
    return storyDateSerialDay(parsed) * 1440 + minutes;
  }

  function tempHypnosisEffectEndStamp(value) {
    const text = tempHypnosisEffectEndText(value);
    const match = String(text || "").match(/(\\d{4})\\s*年\\s*(\\d{1,2})\\s*月\\s*(\\d{1,2})\\s*日\\s+(\\d{1,2})\\s*[:：]\\s*(\\d{2})(?!\\d)/);
    if (!match) return 0;
    const hour = Number(match[4]);
    const minute = Number(match[5]);
    if (!Number.isInteger(hour) || hour < 0 || hour > 23 || !Number.isInteger(minute) || minute < 0 || minute > 59) return 0;
    const parsed = parseStoryDate(match[0]);
    if (!parsed) return 0;
    return storyDateSerialDay(parsed) * 1440 + hour * 60 + minute;
  }

  function tempHypnosisEffectSummary(key, value) {
    if (!isPlainObject(value)) return effectScalar(value) || String(key || "临时催眠").trim() || "临时催眠";
    return effectScalar(value["效果"] ?? value["名称"] ?? value["内容"] ?? value["描述"] ?? key) || String(key || "临时催眠").trim() || "临时催眠";
  }

  function collectExpiredTemporaryHypnosisEffects(limit = 1) {
    const currentStamp = monitorCurrentStamp();
    if (!Number.isFinite(currentStamp) || currentStamp <= 0) return [];
    const roles = getStatsRoles();
    const results = [];
    for (const [roleName, roleData] of Object.entries(roles || {})) {
      if (!isPlainObject(roleData)) continue;
      const effects = roleEffectValue(roleData, "临时催眠效果");
      if (!effects) continue;
      const entries = isPlainObject(effects) ? Object.entries(effects) : Array.isArray(effects) ? effects.map((item, index) => [String(index), item]) : [["临时催眠", effects]];
      for (const [key, value] of entries) {
        const endText = tempHypnosisEffectEndText(value);
        const endStamp = tempHypnosisEffectEndStamp(value);
        if (!endText || !endStamp || currentStamp < endStamp) continue;
        results.push({ roleName, key: String(key || "临时催眠").trim() || "临时催眠", title: tempHypnosisEffectSummary(key, value), endText });
        if (results.length >= limit) return results;
      }
    }
    return results;
  }

  async function expireTemporaryHypnosisEffectDirect(item, currentText) {
    if (!item?.roleName || !item?.key) return { ok: false, message: "没有找到到期的临时催眠效果。" };
    const result = await rewardApplySystemMutation((system, stat) => {
      const roles = stat["角色"] && typeof stat["角色"] === "object" && !Array.isArray(stat["角色"]) ? stat["角色"] : {};
      const deleted = deleteHypnosisEffectWithAttachedGhost(item.roleName, roles, system, "临时催眠效果", item.key, item.title);
      if (!deleted?.ok) return deleted;
      return { ok: true, message: "临时催眠效果已到期并由前端删除。", payload: { 来源: "催眠命令", 操作: "临时催眠到期提醒", 暂存摘要: item.roleName + "｜" + item.title + "｜已到期", 角色名: item.roleName, 效果名: item.key, 临时催眠: item.title, 效果结束时间: item.endText, 当前变量时间: currentText || "未记录", 前端处理: "前端按完整绝对故事时间删除到期临时效果。", 变量写入路径: deleted.peerName ? [rolePageVariablePath(item.roleName, "效果", "临时催眠效果"), rolePageVariablePath(deleted.peerName, "效果", "临时催眠效果")] : rolePageVariablePath(item.roleName, "效果", "临时催眠效果"), AI执行规范: "该临时催眠效果已经到期并由前端删除；不得延期、补回或转成永久效果。", 不可删除: true, locked: true, forceLocked: true } };
    });
    if (result?.ok) window.__ST_SET_EXPIRED_TEMP_HYPNOSIS_REMINDER__?.(result.payload);
    return result || { ok: false, message: "临时催眠到期处理失败。" };
  }

  function syncExpiredTemporaryHypnosisReminder() {
    try {
      if (typeof window.__ST_HYPNOOS_IS_LATEST_MESSAGE_FRONTEND__ === "function" && !window.__ST_HYPNOOS_IS_LATEST_MESSAGE_FRONTEND__()) return false;
      const item = collectExpiredTemporaryHypnosisEffects(1)[0];
      if (!item) return false;
      const system = getSystemState();
      const currentText = [systemStoryDateText(system), storyTimeOnly(system["当前时间"], "")].filter(Boolean).join(" ");
      const flightKey = item.roleName + "\\n" + item.key + "\\n" + item.endText;
      if (window.__ST_EXPIRED_TEMP_HYPNOSIS_WRITE_IN_FLIGHT__ === flightKey) return false;
      window.__ST_EXPIRED_TEMP_HYPNOSIS_WRITE_IN_FLIGHT__ = flightKey;
      void expireTemporaryHypnosisEffectDirect(item, currentText).finally(() => { if (window.__ST_EXPIRED_TEMP_HYPNOSIS_WRITE_IN_FLIGHT__ === flightKey) window.__ST_EXPIRED_TEMP_HYPNOSIS_WRITE_IN_FLIGHT__ = ""; });
      return false;
    } catch (error) {
      console.warn("[HypnoOS] 临时催眠到期扫描失败", error);
      return false;
    }
  }

