  function canonicalizeDynamicWorldbookVariablePaths(content) {
    let next = String(content || "");
    const escapeRegExp = (value) => String(value).replace(/[\\^$.*+?()[\]{}|]/g, "\\$&");
    const bs = String.fromCharCode(92);
    const dollar = String.fromCharCode(36);
    const roleRootFields = {
      "好感度": "状态/好感度",
      "警戒度": "状态/警戒度",
      "服从度": "状态/服从度",
      "性欲": "状态/性欲",
      "快感值": "状态/快感值",
      "绰号": "信息/绰号",
      "绰号已认可": "信息/绰号已认可",
      "_事件记录": "事件/_事件记录",
      "至关重要记忆": "事件/至关重要记忆",
      "心理": "效果/心理",
      "临时催眠效果": "效果/临时催眠效果",
      "永久催眠效果": "效果/永久催眠效果"
    };
    const profileFields = {
      "头发": "衣着/头发",
      "面部": "衣着/面部",
      "上衣": "衣着/上衣",
      "下衣": "衣着/下衣",
      "姓名": "信息/姓名",
      "年龄": "信息/_年龄",
      "_年龄": "信息/_年龄",
      "社团/职业": "信息/社团或职业",
      "社团或职业": "信息/社团或职业",
      "身高": "信息/身高",
      "体重": "信息/体重",
      "三围": "信息/三围",
      "阴茎长度": "信息/阴茎长度"
    };
    const replaceMap = { ...roleRootFields };
    for (const [key, value] of Object.entries(profileFields)) replaceMap["档案/" + key] = value;
    const keys = Object.keys(replaceMap).sort((a, b) => b.length - a.length).map(escapeRegExp).join("|");
    if (keys) {
      const whitespace = bs + "s";
      const dot = bs + ".";
      const slash = bs + "/";
      const profilePattern = Object.keys(profileFields).map((key) => escapeRegExp(key).split("/").join(slash)).join("|");
      const rootPattern = Object.keys(roleRootFields).map(escapeRegExp).join("|");
      next = next.replace(
        new RegExp("(/角色/[^" + whitespace + "/'，。；：<>]+)/(?:状态/心理|" + keys + ")(?=/|[" + whitespace + "'，。；：<>]|$)", "g"),
        (match, base) => {
          const suffix = match.slice(base.length + 1);
          return base + "/" + (suffix === "状态/心理" ? "效果/心理" : replaceMap[suffix]);
        }
      );
      next = next.replace(
        new RegExp("(stat_data" + dot + "角色" + dot + "[^." + whitespace + "']+)" + dot + "(?:状态" + dot + "心理|档案" + dot + "(" + profilePattern + ")|(" + rootPattern + "))(?=" + dot + "|[" + whitespace + "']|$)", "g"),
        (match, base, profileKey, rootKey) => {
          if (match.includes(".状态.心理")) return base + ".效果.心理";
          const mapped = profileKey ? profileFields[profileKey] : roleRootFields[rootKey];
          return base + "." + mapped.split("/").join(".");
        }
      );
    }
    return next
      .replaceAll("/系统/" + dollar + "警视厅线", "/系统/_警视厅线")
      .replaceAll("/系统/" + dollar + "医院线", "/系统/_医院线")
      .replaceAll("/系统/" + dollar + "灵异线", "/系统/_灵异线")
      .replaceAll(dollar + "警视厅线", "_警视厅线")
      .replaceAll(dollar + "医院线", "_医院线")
      .replaceAll(dollar + "灵异线", "_灵异线")
      .replaceAll("变量结构需包含「档案」(姓名、年龄、社团/职业、身高、体重、三围、头发、面部、上衣、下衣)、「心理」(此刻想法)", "变量结构需包含十页对象：「衣着」(头发、面部、上衣、下衣)、「信息」(姓名、_年龄、社团或职业、身高、体重、三围或阴茎长度)、「效果/心理」(此刻想法)、「劣迹」、「改造」、「物品」(仅持有)、「子嗣」")
      .replaceAll("档案使用「阴茎长度」替代「三围」", "「信息/阴茎长度」替代「信息/三围」")
      .replaceAll("档案改为女性格式，使用「三围」，不再使用「阴茎长度」", "「信息」改为女性格式，使用「三围」，不再使用「阴茎长度」");
  }

