  let encounterLibraryDataRevision = 0;
  const encounterPackagesReadCache = new Map();
  const encounterRoleLibraryReadCache = new Map();

  function encounterInvalidateLibraryReadCaches() {
    encounterLibraryDataRevision += 1;
    encounterPackagesReadCache.clear();
    encounterRoleLibraryReadCache.clear();
  }

