    if (!requireWritablePhoneFloor()) {
      encounterSetStatus(page, "历史楼层只读；切回当前楼后才能购买。");
      return;
    }
    const count = Number(quantity);
    if (!Number.isSafeInteger(count) || count < 1) {
      encounterSetStatus(page, "购买数量必须是大于0的整数。");
      return;
    }
    const data = encounterCurrentMvuData();
    if (!data) {
      encounterSetStatus(page, "MVU变量接口未就绪，无法购买。");
      return;
    }
    data.stat["系统"] = data.stat["系统"] && typeof data.stat["系统"] === "object" && !Array.isArray(data.stat["系统"]) ? data.stat["系统"] : {};
    if (!encounterVip6FromSystem(data.stat["系统"])) {
      encounterSetStatus(page, "常识修改雷达只有VIP6用户才能购买和使用。");
      return;
    }
    const cost = count * ENCOUNTER_SHOP_RULE_COUPON_PRICE;
