    if (current < cost) {
      encounterSetStatus(page, "星光点不足，常识修改雷达每个100星光点。");
      return;
    }
    data.stat["系统"]["星光点"] = current - cost;
    encounterAddInventoryItem(data.stat, LOCATION_RULE_RADAR_ITEM, count, "催眠APP出售给VIP6用户的一次性高级广范围雷达；在地图的地点规则抽屉中写入一条永久规则时消耗1个。");
