  function encounterBranchPersonaContent(comment, fallback) {
    try {
      const pkg = encounterReadPackages().find((item) => String(item?.id || "") === ENCOUNTER_ORJENRN_PACKAGE_ID);
      const entries = Array.isArray(pkg?.branchPersonaEntries) ? pkg.branchPersonaEntries : [];
      const match = entries.find((entry) => String(entry?.comment || "") === String(comment || ""));
      const content = String(match?.content || "").trim();
      if (content) return content;
    } catch {}
    return String(fallback || "");
  }

