  const ST_TEACHING_MAP_POINTS = [
    { id: "teacher-office", label: "教师办公室", short: "教师办公室", category: "行政", symbol: "🧑‍🏫", x: 20, y: 22, w: 88, h: 34, c1: "#fed7aa", c2: "#fb923c", info: "教师办公室。班主任、任课老师和校内管理信息常在这里交汇。" },
    { id: "principal", graphId: "principal", label: "校长室", short: "校长室", category: "行政", symbol: "🗂", x: 80, y: 22, w: 78, h: 34, c1: "#fdba74", c2: "#ea580c" },
    { id: "classroom-1", label: "一年级教室", short: "一年级", category: "学习", symbol: "1", x: 20, y: 48, w: 82, h: 34, c1: "#bfdbfe", c2: "#60a5fa", info: "一年级教室。低年级学生聚集，传闻扩散快，适合轻量校园日常。" },
    { id: "classroom", graphId: "classroom", label: "二年级教室", short: "二年级", category: "学习", symbol: "2", x: 50, y: 48, w: 90, h: 38, c1: "#fde68a", c2: "#f59e0b" },
    { id: "classroom-3", label: "三年级教室", short: "三年级", category: "学习", symbol: "3", x: 80, y: 48, w: 82, h: 34, c1: "#ddd6fe", c2: "#8b5cf6", info: "三年级教室。升学压力更重，角色互动会更容易被学业和前后辈关系影响。" },
    { id: "boys-restroom", label: "男厕所", short: "男厕所", category: "生活", symbol: "♂", x: 20, y: 64, w: 78, h: 34, c1: "#bfdbfe", c2: "#3b82f6", info: "教学楼男厕所。课间会有人进出，容易被脚步声、说话声和同学视线影响。" },
    { id: "girls-restroom", label: "女厕所", short: "女厕所", category: "生活", symbol: "♀", x: 80, y: 64, w: 78, h: 34, c1: "#fecdd3", c2: "#f472b6", info: "教学楼女厕所。出入更敏感，普通情况下不适合无关人员靠近。" },
    { id: "nurse-room", label: "保健室", short: "保健室", category: "生活", symbol: "＋", x: 20, y: 82, w: 78, h: 34, c1: "#fecdd3", c2: "#fb7185", info: "保健室。身体不适、临时休息、健康检查和被教师发现后的安置地点。" },
    { id: "corridor", graphId: "corridor", label: "主走廊", short: "主走廊", category: "公共", symbol: "↔", x: 50, y: 74, w: 96, h: 30, c1: "#e5e7eb", c2: "#9ca3af" },
    { id: "rooftop", label: "天台", short: "天台", category: "公共", symbol: "⇧", x: 80, y: 82, w: 82, h: 34, c1: "#d1fae5", c2: "#34d399", info: "教学楼天台。通常较安静，适合短暂谈话、躲避视线或独处。" }
  ];

  const ST_TEACHING_MAP_PATHS = [
    { x: 18, y: 47, w: 64, h: 6 },
    { x: 18, y: 73, w: 64, h: 6 },
    { x: 49, y: 22, w: 6, h: 54 },
    { x: 19, y: 22, w: 6, h: 54 },
    { x: 79, y: 22, w: 6, h: 54 }
  ];

  function campusPointData(graph = loadStaticGraph("school")) {
    const graphById = new Map((graph.locations || []).map((location) => [String(location.id), location]));
    return ST_CAMPUS_MAP_POINTS.map((point) => {
      const specialLocation = point.specialId ? SPECIAL_LOCATION_STATIC_ITEMS.find((item) => item.id === point.specialId) : null;
      const graphLocation = graphById.get(String(point.graphId || point.id));
      const location = graphLocation || specialLocation || {
        id: point.graphId || point.id,
        label: point.label,
        category: point.category,
        info: "暂无地点信息。"
      };
      const unlocked = specialLocation ? specialLocationUnlocked(specialLocation) : true;
      return {
        ...point,
        location,
        specialLocation,
        unlocked,
        label: location.label || point.label,
        short: point.short || location.label || point.label,
        category: location.category || point.category || "地点",
        info: location.info || "暂无地点信息。"
      };
    });
  }

  function campusExtraLocations(graph, points) {
    const pointIds = new Set(points.map((point) => String(point.location?.id || point.graphId || point.id)));
    return (graph.locations || []).filter((location) => String(location?.id || "") && !pointIds.has(String(location.id)));
  }

  function teachingPointData(graph = loadStaticGraph("school")) {
    const graphById = new Map((graph.locations || []).map((location) => [String(location.id), location]));
    return ST_TEACHING_MAP_POINTS.map((point) => {
      const graphLocation = point.graphId ? graphById.get(String(point.graphId)) : null;
      const location = graphLocation || {
        id: point.graphId || point.id,
        label: point.label,
        category: point.category,
        info: point.info || "暂无地点信息。"
      };
      return {
        ...point,
        location,
        label: location.label || point.label,
        short: point.short || location.label || point.label,
        category: location.category || point.category || "地点",
        info: location.info || point.info || "暂无地点信息。"
      };
    });
  }

  function campusSelectedLocation(page, points, extras) {
    const selected = String(page?.dataset?.campusSelected || "").trim();
    if (!selected) return null;
    const point = points.find((item) => String(item.id) === selected || String(item.location?.id) === selected);
    if (point) return { type: "point", id: point.id, location: point.location, point };
    const extra = extras.find((location) => String(location.id) === selected);
    if (extra) return { type: "extra", id: extra.id, location: extra, point: null };
    return null;
  }

  function renderCampusInfoPanel(page, selected, extras) {
    const currentLocation = getCurrentStoryLocation() || "未记录";
    const pendingStoryLocation = hasPendingStoryLocationOperation();
    const specialLocation = selected?.point?.specialLocation || null;
    const lockedSpecial = Boolean(specialLocation && !specialLocationUnlocked(specialLocation));
    const location = selected?.location || {
      id: "school",
      label: "私立斋明学园",
      category: "学校",
      info: "从校门、教学楼、旧校舍、图书馆、操场到泳池，斋明学园的主要活动区域被压缩成一张轻量校园图。"
    };
    const suggest = selected?.location && !lockedSpecial
      ? (specialLocation
        ? '<button type="button" class="st-location-suggest" data-campus-special-suggest="' + escapeAttr(specialLocation.id) + '"' + (pendingStoryLocation ? " disabled" : "") + '>' + (pendingStoryLocation ? "已暂存" : "建议设为地点") + '</button>'
        : '<button type="button" class="st-location-suggest" data-graph-suggest-location="' + escapeAttr(location.id) + '" data-graph-scope="school"' + (pendingStoryLocation ? " disabled" : "") + '>' + (pendingStoryLocation ? "已暂存" : "建议设为地点") + '</button>')
      : "";
    const enter = selected?.point?.enter === "teaching" && !lockedSpecial
      ? '<button type="button" class="st-campus-enter" data-campus-enter-layer="teaching">进入教学楼</button>'
      : "";
    const gate = lockedSpecial
      ? '<button type="button" class="st-campus-enter is-gate" data-campus-gate-open="' + escapeAttr(specialLocation.id) + '">查看准入证</button>'
      : "";
    const extraHtml = extras.length
      ? '<div class="st-campus-extra"><span class="st-campus-extra-title">更多校内地点</span><div class="st-campus-extra-list">' + extras.map((item) => (
          '<button type="button" class="' + (String(selected?.id || "") === String(item.id) ? "active" : "") + '" data-campus-extra="' + escapeAttr(item.id) + '">' + escapeHtml(item.label || item.id) + '</button>'
        )).join("") + '</div></div>'
      : '<p>后续用户自己添加的校内地点会收在这里，不会挤进主校园图。</p>';
    return '<section class="st-campus-info">' +
      '<div class="st-campus-info-head"><strong>' + escapeHtml(location.label || "校园总览") + '</strong><small>' + escapeHtml(location.category || "校园") + '</small></div>' +
      '<p>' + escapeHtml(lockedSpecial ? ((specialLocation.gateText || "你被门卫赶了出来") + "。" + (specialLocation.unlockNote || "")) : (location.info || "暂无地点信息。")) + '</p>' +
      '<div class="st-campus-actions">' + suggest + enter + gate + '</div>' +
      '<div class="st-location-current"><span>当前地点变量</span><strong>' + escapeHtml(operationPanelLocationText(currentLocation)) + '</strong></div>' +
      extraHtml +
    '</section>';
  }

  function renderTeachingInfoPanel(page, selected) {
    const currentLocation = getCurrentStoryLocation() || "未记录";
    const pendingStoryLocation = hasPendingStoryLocationOperation();
    const location = selected?.location || {
      id: "teaching-building",
      label: "主教学楼",
      category: "教学楼",
      info: "主教学楼按楼内案内図简化为办公室、年级教室、保健室、厕所、主走廊和天台。"
    };
    const suggest = selected?.location
      ? '<button type="button" class="st-location-suggest" data-building-suggest-location="' + escapeAttr(selected.id) + '"' + (pendingStoryLocation ? " disabled" : "") + '>' + (pendingStoryLocation ? "已暂存" : "建议设为地点") + '</button>'
      : "";
    return '<section class="st-campus-info">' +
      '<div class="st-campus-info-head"><strong>' + escapeHtml(location.label || "主教学楼") + '</strong><small>' + escapeHtml(location.category || "教学楼") + '</small></div>' +
      '<p>' + escapeHtml(location.info || "暂无地点信息。") + '</p>' +
      '<div class="st-campus-actions">' +
        '<button type="button" class="st-campus-up" data-campus-back-layer="campus">返回校园图</button>' +
        suggest +
      '</div>' +
      '<div class="st-location-current"><span>当前地点变量</span><strong>' + escapeHtml(operationPanelLocationText(currentLocation)) + '</strong></div>' +
    '</section>';
  }

  function renderCampusGateDialog(page) {
    const specialId = String(page?.dataset?.campusGateSpecial || "").trim();
    if (!specialId) return "";
    const location = SPECIAL_LOCATION_STATIC_ITEMS.find((item) => item.id === specialId);
    if (!location || specialLocationUnlocked(location)) return "";
    const status = String(page?.dataset?.specialLocationStatus || "").trim();
    const passItem = specialLocationPassItemName(location) || String(location.passItem || "对应准入证").trim();
    return '<div class="st-campus-gate-layer" data-campus-gate-layer role="presentation">' +
      '<section class="st-campus-gate-card" role="dialog" aria-modal="true" aria-label="特殊地点门卫">' +
        '<h3>' + escapeHtml(location.gateText || "你被门卫赶了出来") + '</h3>' +
        '<p>' + escapeHtml(location.unlockNote || ("需要持有「" + passItem + "」。可在邂逅商店购买对应准入证。")) + '</p>' +
        (status ? '<p class="st-campus-gate-status">' + escapeHtml(status) + '</p>' : '') +
        '<div class="st-campus-gate-actions">' +
          '<button type="button" data-campus-gate-close>取消</button>' +
          '<button type="button" class="primary" data-campus-gate-shop="' + escapeAttr(location.id) + '">去邂逅商店</button>' +
        '</div>' +
      '</section>' +
    '</div>';
  }

  function renderCampusMapCard(page) {
    const graph = loadStaticGraph("school");
    const currentLocation = getCurrentStoryLocation();
    const points = campusPointData(graph);
    const extras = campusExtraLocations(graph, points);
    const selected = campusSelectedLocation(page, points, extras);
    const fields = ST_CAMPUS_FIELDS.map((field) => '<i class="st-campus-field" style="--x:' + field.x + '%;--y:' + field.y + '%;--w:' + field.w + '%;--h:' + field.h + '%;--radius:' + escapeAttr(field.radius || "14px") + '"></i>').join("");
    const paths = ST_CAMPUS_MAP_PATHS.map((path) => '<i class="st-campus-path" style="--x:' + path.x + '%;--y:' + path.y + '%;--w:' + path.w + '%;--h:' + path.h + '%"></i>').join("");
    const pointHtml = points.map((point) => {
      const location = point.location || {};
      const isSelected = selected?.type === "point" && selected.id === point.id;
      const isCurrent = isGraphLocationCurrent(location, currentLocation);
      const locked = Boolean(point.specialLocation && !point.unlocked);
      const hasEnter = Boolean(point.enter);
      return '<button type="button" class="st-campus-point ' + (isSelected ? "active " : "") + (isCurrent ? "is-current " : "") + (locked ? "is-locked " : "") + (hasEnter ? "has-enter" : "") + '" data-campus-point="' + escapeAttr(point.id) + '"' + (point.specialLocation ? ' data-campus-special="' + escapeAttr(point.specialLocation.id) + '" data-campus-locked="' + (locked ? "true" : "false") + '"' : "") + ' style="--x:' + point.x + '%;--y:' + point.y + '%;--w:' + point.w + 'px;--h:' + point.h + 'px;--c1:' + escapeAttr(point.c1 || "#fde68a") + ';--c2:' + escapeAttr(point.c2 || "#f59e0b") + '" aria-label="' + escapeAttr(location.label || point.label) + '">' +
        '<span class="st-campus-block" aria-hidden="true"><span class="st-campus-symbol">' + escapeHtml(point.symbol || "📍") + '</span>' + (hasEnter ? '<span class="st-map-layer-mark">›</span>' : '') + '</span>' +
        '<span class="st-campus-label">' + escapeHtml(point.short || location.label || point.label) + '</span>' +
      '</button>';
    }).join("");
    return '<section class="st-lite-card st-graph-card st-graph-paper st-campus-card">' +
      '<div class="st-graph-head"><strong>斋明学园校园图</strong><span>' + graph.locations.length + ' 校内地点</span></div>' +
      '<section class="st-campus-stage" data-campus-stage aria-label="斋明学园校园地图">' +
        fields +
        paths +
        pointHtml +
      '</section>' +
      renderCampusInfoPanel(page, selected, extras) +
      renderCampusGateDialog(page) +
    '</section>' +
    renderGraphAddLocationCard("school", graph, page);
  }

  function renderTeachingMapCard(page) {
    const graph = loadStaticGraph("school");
    const currentLocation = getCurrentStoryLocation();
    const points = teachingPointData(graph);
    const selected = campusSelectedLocation(page, points, []);
    const paths = ST_TEACHING_MAP_PATHS.map((path) => '<i class="st-campus-path" style="--x:' + path.x + '%;--y:' + path.y + '%;--w:' + path.w + '%;--h:' + path.h + '%"></i>').join("");
    const pointHtml = points.map((point) => {
      const location = point.location || {};
      const isSelected = selected?.type === "point" && selected.id === point.id;
      const isCurrent = isGraphLocationCurrent(location, currentLocation);
      return '<button type="button" class="st-campus-point ' + (isSelected ? "active " : "") + (isCurrent ? "is-current " : "") + '" data-teaching-point="' + escapeAttr(point.id) + '" style="--x:' + point.x + '%;--y:' + point.y + '%;--w:' + point.w + 'px;--h:' + point.h + 'px;--c1:' + escapeAttr(point.c1 || "#fde68a") + ';--c2:' + escapeAttr(point.c2 || "#f59e0b") + '" aria-label="' + escapeAttr(location.label || point.label) + '">' +
        '<span class="st-campus-block" aria-hidden="true"><span class="st-campus-symbol">' + escapeHtml(point.symbol || "📍") + '</span></span>' +
        '<span class="st-campus-label">' + escapeHtml(point.short || location.label || point.label) + '</span>' +
      '</button>';
    }).join("");
    return '<section class="st-lite-card st-graph-card st-graph-paper st-campus-card">' +
      '<div class="st-graph-head"><strong>主教学楼案内図</strong><span>楼内地点</span></div>' +
      '<section class="st-campus-stage is-building" data-teaching-stage aria-label="主教学楼楼内地图">' +
        paths +
        pointHtml +
      '</section>' +
      renderTeachingInfoPanel(page, selected) +
    '</section>';
  }

  function renderCampusPage(page) {
    if (!page) return;
    if (!ST_BOARD_MAP_LAYERS[String(page.dataset.mapBoardLayer || "")]) {
      const legacyLayer = String(page.dataset.campusLayer || "campus");
      page.dataset.mapBoardLayer = legacyLayer === "teaching" ? "teaching" : "campus";
    }
    renderCityMapPage(page);
  }

  function bindCampusMapActions(page) {
    page.querySelector("[data-campus-stage]")?.addEventListener("click", (event) => {
      if (event.target?.closest?.("[data-campus-point]")) return;
      if (!page.dataset.campusSelected) return;
      delete page.dataset.campusSelected;
      renderCampusPage(page);
    });
    page.querySelectorAll("[data-campus-point]").forEach((button) => {
      button.addEventListener("click", async (event) => {
        event.preventDefault();
        event.stopPropagation();
        const id = button.getAttribute("data-campus-point") || "";
        const specialId = button.getAttribute("data-campus-special") || "";
        if (specialId && button.getAttribute("data-campus-locked") === "true") {
          page.dataset.campusSelected = id;
          page.dataset.campusGateSpecial = specialId;
          renderCampusPage(page);
          return;
        }
        delete page.dataset.campusGateSpecial;
        if (page.dataset.campusSelected === id) delete page.dataset.campusSelected;
        else page.dataset.campusSelected = id;
        renderCampusPage(page);
      });
    });
    page.querySelectorAll("[data-campus-enter-layer]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        page.dataset.campusLayer = button.getAttribute("data-campus-enter-layer") || "campus";
        delete page.dataset.campusSelected;
        delete page.dataset.campusGateSpecial;
        renderCampusPage(page);
      });
    });
    page.querySelectorAll("[data-campus-gate-open]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        page.dataset.campusGateSpecial = button.getAttribute("data-campus-gate-open") || "";
        renderCampusPage(page);
      });
    });
    page.querySelectorAll("[data-campus-gate-close]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        delete page.dataset.campusGateSpecial;
        renderCampusPage(page);
      });
    });
    page.querySelector("[data-campus-gate-layer]")?.addEventListener("click", (event) => {
      if (event.target?.closest?.(".st-campus-gate-card")) return;
      delete page.dataset.campusGateSpecial;
      renderCampusPage(page);
    });
    page.querySelectorAll("[data-campus-gate-shop]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const id = button.getAttribute("data-campus-gate-shop") || "";
        const location = SPECIAL_LOCATION_STATIC_ITEMS.find((item) => item.id === id);
        openSpecialLocationShop(page, location);
      });
    });
    page.querySelectorAll("[data-campus-special-suggest]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const id = button.getAttribute("data-campus-special-suggest") || "";
        const location = SPECIAL_LOCATION_STATIC_ITEMS.find((item) => item.id === id);
        if (!location) return;
        if (!specialLocationUnlocked(location)) {
          page.dataset.campusGateSpecial = id;
          renderCampusPage(page);
          return;
        }
        if (hasPendingStoryLocationOperation()) {
          renderCampusPage(page);
          return;
        }
        Promise.resolve(appendAppOperation({
          来源: "地图",
          操作: "建议剧情地点",
          地图类型: "校园特殊地点",
          地点ID: location.id,
          建议地点: {
            名称: location.label,
            分类: "特殊地点",
            描述: location.info || "待续"
          },
          当前地点变量: getCurrentStoryLocation() || "未知",
          AI执行规范: "这只是用户希望剧情进入该校内特殊地点的建议；前端不能直接改当前地点。AI应按剧情、时间、权限和世界观判断是否成立，成立时更新/系统/当前地点并展开对应特殊地点剧情；不合理时可拒绝、延后或给出进入条件。"
        })).then(() => renderCampusPage(page));
      });
    });
    page.querySelectorAll("[data-campus-extra]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const id = button.getAttribute("data-campus-extra") || "";
        if (page.dataset.campusSelected === id) delete page.dataset.campusSelected;
        else page.dataset.campusSelected = id;
        renderCampusPage(page);
      });
    });
  }

  function bindTeachingMapActions(page) {
    page.querySelector("[data-teaching-stage]")?.addEventListener("click", (event) => {
      if (event.target?.closest?.("[data-teaching-point]")) return;
      if (!page.dataset.campusSelected) return;
      delete page.dataset.campusSelected;
      renderCampusPage(page);
    });
    page.querySelectorAll("[data-teaching-point]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const id = button.getAttribute("data-teaching-point") || "";
        if (page.dataset.campusSelected === id) delete page.dataset.campusSelected;
        else page.dataset.campusSelected = id;
        renderCampusPage(page);
      });
    });
    page.querySelectorAll("[data-campus-back-layer]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        page.dataset.campusLayer = button.getAttribute("data-campus-back-layer") || "campus";
        delete page.dataset.campusSelected;
        renderCampusPage(page);
      });
    });
    page.querySelectorAll("[data-building-suggest-location]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const id = button.getAttribute("data-building-suggest-location") || "";
        const point = teachingPointData().find((item) => item.id === id);
        const location = point?.location;
        if (!location || hasPendingStoryLocationOperation()) {
          renderCampusPage(page);
          return;
        }
        Promise.resolve(appendAppOperation({
          来源: "学校地图",
          操作: "建议剧情地点",
          当前地点变量: getCurrentStoryLocation() || "未知",
          建议地点: {
            名称: location.label || point.label,
            分类: location.category || point.category || "教学楼",
            描述: location.info || point.info || "暂无地点信息。",
            地图类型: "主教学楼案内図"
          },
          AI执行规范: "这只是用户希望剧情地点设在这里的建议；前端不能直接改当前地点。AI应按剧情、时间和移动条件判断是否成立，成立时更新/系统/当前地点和/系统/当前事件；/系统/_当前周几、/系统/_当前日程、/系统/_当前特殊日期和/系统/_课程表为前端只读同步字段，AI不要手写这些字段。不合理时可拒绝或延后。"
        })).then(() => renderCampusPage(page));
      });
    });
  }

  function getLocationRules() {
    const variables = getLatestStatDataSync();
    const rules = variables?.["规则"];
    return rules && typeof rules === "object" && !Array.isArray(rules) ? rules : {};
  }

  function locationRuleRequirementState() {
    const system = getSystemState();
    return {
      vip6: encounterVip6FromSystem(system),
      vip5: encounterVip5FromSystem(system),
      radarCount: encounterInventoryItemCount(LOCATION_RULE_RADAR_ITEM)
    };
  }

  function mapLayerIsDescendantOf(layerId, ancestorId) {
    let cursor = String(layerId || "");
    const target = String(ancestorId || "");
    while (cursor && ST_BOARD_MAP_LAYERS[cursor]) {
      if (cursor === target) return true;
      cursor = String(ST_BOARD_MAP_LAYERS[cursor]?.parent || "");
    }
    return false;
  }

  function locationRuleVisibleInLayer(rule, layerId) {
    const ruleLayer = String(rule?.["地图层级"] || "city");
    return mapLayerIsDescendantOf(ruleLayer, layerId) || mapLayerIsDescendantOf(layerId, ruleLayer);
  }

  function mapLayerPathLabels(layerId) {
    const chain = [];
    let cursor = String(layerId || "city");
    while (cursor && ST_BOARD_MAP_LAYERS[cursor]) {
      const layer = ST_BOARD_MAP_LAYERS[cursor];
      if (cursor !== "city") {
        const parent = ST_BOARD_MAP_LAYERS[layer.parent];
        const entryNode = parent?.nodes?.find((node) => String(node.enter || "") === cursor);
        if (entryNode?.label) chain.unshift(entryNode.label);
      }
      cursor = String(layer.parent || "");
    }
    return chain;
  }

  function selectedMapRuleTarget(layerId, selected) {
    if (!selected?.location) return null;
    const location = selected.location;
    const name = String(location.label || selected.node?.label || selected.id || "").trim();
    if (!name) return null;
    const id = String(selected.id || location.id || "").trim();
    const path = [...mapLayerPathLabels(layerId), name].filter(Boolean);
    return {
      地点ID: layerId + ":" + id,
      地点名: name,
      地图层级: layerId,
      地点路径: path.join(" / "),
      生效范围: name
    };
  }

  function specialLocationRuleTarget(locationId) {
    const location = specialLocationCatalog().find((item) => String(item?.id || "") === String(locationId || ""));
    if (!location) return null;
    const layerId = specialLocationLayerId(location);
    const name = String(location.label || location.id || "").trim();
    const path = [...mapLayerPathLabels(layerId), name].filter(Boolean);
    return {
      地点ID: layerId + ":" + String(location.id),
      地点名: name,
      地图层级: layerId,
      地点路径: path.join(" / "),
      生效范围: name
    };
  }

  function activeLocationRuleTarget(page, layerId, selected) {
    const specialId = String(page?.dataset?.locationRuleSpecialId || "").trim();
    return (specialId ? specialLocationRuleTarget(specialId) : null) || selectedMapRuleTarget(layerId, selected);
  }

  async function locationRuleDeleteDirect(page, ruleId) {
    const id = String(ruleId || "").trim();
    if (!id) return { ok: false, message: "没有找到地点规则。" };
    if (!requireWritablePhoneFloor()) return { ok: false, message: "历史楼层只读。" };
    const result = await rewardApplySystemMutation((system, stat) => {
      const rules = stat["规则"] && typeof stat["规则"] === "object" && !Array.isArray(stat["规则"]) ? stat["规则"] : null;
      if (!rules || !Object.prototype.hasOwnProperty.call(rules, id)) return { ok: false, message: "变量中没有找到这条地点规则。" };
      const deleted = rules[id];
      const nextRules = Object.fromEntries(Object.entries(rules).filter(([key]) => key !== id));
      stat["规则"] = nextRules;
      return {
        ok: true,
        message: "地点规则已删除。",
        payload: {
          来源: "地图",
          操作: "删除地点规则",
          暂存摘要: String(deleted?.["地点名"] || id) + " · " + String(deleted?.["内容"] || ""),
          规则ID: id,
          地点ID: deleted?.["地点ID"] || "",
          前端处理: "已由前端直接写入变量",
          变量写入路径: ["/规则/" + id],
          AI执行规范: "地点规则已由前端删除；不得再次remove、退款或把它恢复为角色催眠效果。",
          不可删除: true,
          forceLocked: true
        }
      };
    });
    if (result?.ok) {
      const added = await appendAppOperation(result.payload);
      return { ok: true, message: added ? result.message : "地点规则已删除，暂存区已有提醒。" };
    }
    return result || { ok: false, message: "删除地点规则失败。" };
  }

  async function locationRuleCreateDirect(page, target, content) {
    const ruleText = String(content || "").trim();
    if (!target || !ruleText) return { ok: false, message: "请先选择一个具体地点并填写规则。" };
    if (!requireWritablePhoneFloor()) return { ok: false, message: "历史楼层只读。" };
    const requirement = locationRuleRequirementState();
    if (!requirement.vip6) return { ok: false, message: "高级广范围雷达需要VIP6。" };
    if (requirement.radarCount < 1) return { ok: false, message: "需要1个常识修改雷达。" };
    const pendingRuleCount = (() => {
      try {
        const pending = window.__ST_GET_PENDING_OPERATION_INPUT_LOG__?.() || [];
        return pending.filter((entry) => {
          const payload = entry?.payload || entry;
          return String(payload?.["来源"] || "").trim() === "地图"
            && String(payload?.["操作"] || "").trim() === "发布地点规则";
        }).length;
      } catch {
        return 0;
      }
    })();
    if (pendingRuleCount >= requirement.radarCount) {
      return { ok: false, message: "现有雷达已被本轮待发送的规则请求占用；请先发送或删除暂存请求。" };
    }
    const id = "radar-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 7);
    const rulePath = "/规则/" + id;
    const radarQuantityPath = "/系统/持有物品/" + LOCATION_RULE_RADAR_ITEM + "/数量";
    const added = await appendAppOperation({
      来源: "地图",
      操作: "发布地点规则",
      暂存摘要: target.地点名 + " · 待AI命名与润色",
      规则ID: id,
      地点: target,
      用户规则草案: ruleText,
      目标变量路径: rulePath,
      AI可写路径: [radarQuantityPath, rulePath],
      AI写入方式: "常识修改雷达数量用replace写当前值-1；地点规则根用add写入完整对象。",
      AI写入对象结构: {
        名称: "由变量模型结合草案、地点和本轮剧情生成的简洁规则名",
        内容: "由变量模型在不改变用户核心意图的前提下润色后的明确常识规则",
        目标范围: "范围内所有人",
        生效范围: target.生效范围,
        来源: "高级广范围雷达",
        地点ID: target.地点ID,
        地点名: target.地点名,
        地图层级: target.地图层级,
        地点路径: target.地点路径,
        持续类型: "永久"
      },
      前端处理: "只暂存用户意图；尚未扣除常识修改雷达，也未写入/规则。",
      AI执行规范: "剧情模型必须自然描写user使用高级广范围雷达、装置作用于指定地点以及现场常识开始改变；不要把草案原样当系统日志。变量模型必须在目标变量路径add完整规则对象，自行生成名称并润色内容，同时将常识修改雷达数量扣1。不得写入角色临时或永久催眠效果，不得改动其他规则。",
      不可删除: false
    });
    return added
      ? { ok: true, message: "规则请求已加入暂存；发送后由剧情模型演出、变量模型命名润色并写入。" }
      : { ok: false, message: "规则请求加入暂存失败。" };
  }

  function renderLocationRulesDrawer(page, layerId, selected) {
    const rules = getLocationRules();
    const entries = Object.entries(rules).filter(([, rule]) => locationRuleVisibleInLayer(rule, layerId));
    const requirement = locationRuleRequirementState();
    const target = activeLocationRuleTarget(page, layerId, selected);
    const pageSize = 4;
    const pageCount = Math.max(1, Math.ceil(entries.length / pageSize));
    const requestedPage = Math.max(0, Math.trunc(Number(page?.dataset?.locationRulePage || 0) || 0));
    const currentPage = Math.min(requestedPage, pageCount - 1);
    if (page) page.dataset.locationRulePage = String(currentPage);
    const visibleEntries = entries.slice(currentPage * pageSize, currentPage * pageSize + pageSize);
    const list = visibleEntries.length
      ? visibleEntries.map(([id, value]) => {
          const text = typeof value === "object" && value !== null ? (value["内容"] || JSON.stringify(value)) : value;
          const scope = String(value?.["地点路径"] || value?.["地点名"] || value?.["生效范围"] || "未标记地点");
          const name = String(value?.["名称"] || value?.["规则名"] || scope);
          const duration = String(value?.["持续类型"] || "永久");
          return '<article class="st-rule-item"><strong><span>' + escapeHtml(name) + '</span><small>' + escapeHtml(duration) + '</small></strong><em>' + escapeHtml(scope) + '</em><p>' + escapeHtml(text) + '</p><button class="st-rule-delete" type="button" data-location-rule-delete="' + escapeAttr(id) + '" aria-label="删除地点规则">删除</button></article>';
        }).join("")
      : '<p class="st-rule-empty">当前关联层级暂无APP地点规则；世界观仍采用正常规则。</p>';
    const pagination = entries.length > pageSize
      ? '<div class="st-rule-pagination"><button type="button" data-location-rule-page="-1"' + (currentPage <= 0 ? " disabled" : "") + ' aria-label="上一页">‹</button><span>' + (currentPage + 1) + " / " + pageCount + ' · 每页4项</span><button type="button" data-location-rule-page="1"' + (currentPage >= pageCount - 1 ? " disabled" : "") + ' aria-label="下一页">›</button></div>'
      : "";
    const form = requirement.vip6
      ? '<section class="st-rule-form">' +
          '<strong>目标：' + escapeHtml(target?.地点路径 || "请先在棋盘选择一个地点") + '</strong>' +
          '<textarea class="st-rule-input" data-location-rule-input placeholder="输入要永久写入该地点所有人常识的规则"' + (target ? "" : " disabled") + '></textarea>' +
          '<div class="st-rule-cost"><span>常识修改雷达 1</span><span>VIP6</span><span>单一地点及其子地点</span></div>' +
          '<button class="st-rule-button" type="button" data-location-rule-submit' + (target && requirement.radarCount > 0 ? "" : " disabled") + '>' + (target ? (requirement.radarCount > 0 ? "提交规则请求" : "缺少常识修改雷达") : "先选择地点") + '</button>' +
        '</section>'
      : '<p class="st-rule-state">VIP6可用一次性常识修改雷达写入永久规则。VIP5的开放空间常识修改成功后会以临时规则显示在这里。</p>';
    return '<section class="st-location-rule-drawer" data-location-rule-drawer>' +
      '<section class="st-rule-paper">' +
      '<div class="st-rule-paper-head">' +
        '<div class="st-rule-paper-title"><strong>' + escapeHtml(ST_BOARD_MAP_LAYERS[layerId]?.title || "地图") + ' / 常识裁决</strong><span>LOCATION VERDICT · 关联层级 ' + entries.length + ' 条 · 雷达 ' + requirement.radarCount + '</span></div>' +
        '<button type="button" class="st-rule-drawer-close" data-location-rule-close aria-label="收回规则抽屉">撤回</button>' +
      '</div>' +
      '<div class="st-rule-list">' + list + '</div>' +
      pagination +
      form +
      '<div class="st-location-rule-sync"><button type="button" data-location-directory-refresh="builtin">刷新地点世界书</button><button type="button" data-location-directory-refresh="custom">刷新新增地点世界书</button></div>' +
      '<p class="st-rule-state" data-location-rule-status>' + escapeHtml(String(page?.dataset?.locationRuleStatus || "特殊地点目录为角色卡固定条目，不参与刷新。")) + '</p>' +
      '</section>' +
    '</section>';
  }

  function locationRuleRadarBridgeMarkup() {
    return '<div class="st-location-rule-radar-bridge" aria-hidden="true"><img alt="" src="' + escapeAttr(stAssetUrl("maps/location-rule-radar-v2.png")) + '"></div>';
  }

  function positionLocationRuleRadarBridge(page, bridge) {
    const root = page?.parentElement;
    if (!root || !bridge?.isConnected) return;
    const rect = root.getBoundingClientRect();
    const width = Math.max(196, Math.min(318, rect.width * .54));
    const height = width * (916 / 1717);
    bridge.style.width = width + "px";
    bridge.style.left = (rect.left + rect.width / 2) + "px";
    bridge.style.top = (rect.top - height * .77) + "px";
  }

  function startLocationRuleRadarTracking(page, bridge) {
    if (!bridge) return;
    const tick = () => {
      if (!bridge.isConnected || !page?.isConnected) return;
      positionLocationRuleRadarBridge(page, bridge);
      bridge.__stRuleRadarFrame = window.requestAnimationFrame(tick);
    };
    if (bridge.__stRuleRadarFrame) window.cancelAnimationFrame(bridge.__stRuleRadarFrame);
    tick();
  }

  function removeLocationRuleRadarBridge(bridge) {
    if (!bridge) return;
    if (bridge.__stRuleRadarFrame) window.cancelAnimationFrame(bridge.__stRuleRadarFrame);
    bridge.__stRuleRadarFrame = 0;
    bridge.remove();
  }

  function syncLocationRuleRadarBridge(page, open, immediate = false) {
    const root = page?.parentElement;
    if (!root) return;
    const hostBridge = globalThis.__ST_HYPNOOS_UPDATE_LOCATION_RULE_RADAR__;
    if (typeof hostBridge === "function") {
      root.classList.toggle("st-rule-radar-open", Boolean(open));
      root.parentElement?.classList.remove("st-rule-radar-stage");
      document.querySelectorAll("body > .st-location-rule-radar-bridge").forEach(removeLocationRuleRadarBridge);
      try {
        hostBridge({ visible: Boolean(open), immediate: Boolean(immediate) });
      } catch (_) {}
      return;
    }
    let bridge = document.querySelector("body > .st-location-rule-radar-bridge");
    if (open) {
      root.classList.add("st-rule-radar-open");
      if (!bridge) {
        document.body.insertAdjacentHTML("beforeend", locationRuleRadarBridgeMarkup());
        bridge = document.querySelector("body > .st-location-rule-radar-bridge");
      }
      startLocationRuleRadarTracking(page, bridge);
      window.requestAnimationFrame(() => bridge?.classList.add("is-raised"));
      return;
    }
    root.classList.remove("st-rule-radar-open");
    if (!bridge) return;
    if (immediate) {
      removeLocationRuleRadarBridge(bridge);
      return;
    }
    bridge.classList.remove("is-raised");
    bridge.classList.add("is-lowering");
    window.setTimeout(() => removeLocationRuleRadarBridge(bridge), 520);
  }

  function closeLocationRuleDrawer(page) {
    const drawer = page?.querySelector?.("[data-location-rule-drawer]");
    drawer?.classList?.add("is-retracting");
    delete page.dataset.mapBoardRulesOpen;
    if (page.dataset.locationRuleReturnSpecial === "true") page.dataset.mapBoardSpecialOpen = "true";
    delete page.dataset.locationRuleReturnSpecial;
    delete page.dataset.locationRuleSpecialId;
    syncLocationRuleRadarBridge(page, false);
    window.setTimeout(() => page?.isConnected && renderCityMapPage(page), 500);
  }

  function graphAddFormValues(card, scope) {
    const nameInput = card?.querySelector("[data-graph-add-name]");
    const categoryInput = card?.querySelector("[data-graph-add-category]");
    const customCategoryInput = card?.querySelector("[data-graph-add-custom-category]");
    const selectedCategory = String(categoryInput?.value || "").trim();
    return {
      scope: graphSupplementScope(scope),
      name: String(nameInput?.value || "").trim(),
      category: (selectedCategory === GRAPH_CUSTOM_CATEGORY_VALUE ? String(customCategoryInput?.value || "").trim() : selectedCategory),
      info: String(card?.querySelector("[data-graph-add-info]")?.value || "").trim(),
      note: String(card?.querySelector("[data-graph-add-note]")?.value || "").trim()
    };
  }

  function graphFillAddForm(card, item) {
    const source = item && typeof item === "object" ? item : {};
    const values = {
      name: String(source["名称"] || source.name || source.label || "").trim().slice(0, 80),
      category: String(source["分类"] || source.category || "").trim().slice(0, 40),
      info: String(source["信息"] || source.info || source.description || "").trim().slice(0, 1200)
    };
    const nameInput = card?.querySelector("[data-graph-add-name]");
    const categoryInput = card?.querySelector("[data-graph-add-category]");
    const customCategoryInput = card?.querySelector("[data-graph-add-custom-category]");
    const infoInput = card?.querySelector("[data-graph-add-info]");
    if (nameInput && values.name) nameInput.value = values.name;
    if (categoryInput && values.category) {
      const option = Array.from(categoryInput.options || []).find((entry) => entry.value === values.category);
      if (option) categoryInput.value = values.category;
      else if (customCategoryInput) {
        categoryInput.value = GRAPH_CUSTOM_CATEGORY_VALUE;
        customCategoryInput.hidden = false;
        customCategoryInput.value = values.category;
      } else {
        categoryInput.value = values.category;
      }
    }
    if (infoInput && values.info) infoInput.value = values.info;
    return values;
  }

  function saveGraphAddForm(page, button) {
    const scope = graphSupplementScope(button.getAttribute("data-graph-scope") || "world");
    const statusKey = graphAddStatusDatasetKey(scope);
    const card = button.closest("[data-graph-add-scope]");
    const values = graphAddFormValues(card, scope);
    if (!values.name) {
      page.dataset[statusKey] = "请填写地点名。";
      return null;
    }
    const location = addStaticGraphLocation(scope, {
      name: values.name,
      category: values.category,
      info: values.info || graphFallbackLocationInfo(scope, values.name, values.category),
      layer: mapBoardLayerId(page)
    });
    if (!location) {
      page.dataset[statusKey] = "地点保存失败。";
      return null;
    }
    page.dataset.mapBoardSelected = location.id;
    page.dataset[statusKey] = "已保存到前端地图：" + location.label + "。";
    delete page.dataset.mapBoardAddOpen;
    return location;
  }

  function bindGraphPageActions(page) {
    page.querySelectorAll("[data-graph-add-category]").forEach((select) => {
      toggleGraphCustomCategoryInput(select);
      select.addEventListener("change", () => toggleGraphCustomCategoryInput(select));
    });
    page.querySelectorAll("[data-graph-add-generate]").forEach((button) => {
      button.addEventListener("click", async (event) => {
        event.preventDefault();
        event.stopPropagation();
        if (!isLatestPhoneVariableView()) return;
        const scope = graphSupplementScope(button.getAttribute("data-graph-scope") || "world");
        const statusKey = graphAddStatusDatasetKey(scope);
        const card = button.closest("[data-graph-add-scope]");
        const values = graphAddFormValues(card, scope);
        button.disabled = true;
        button.textContent = "生成中…";
        try {
          const text = await invokeIndependentTextModel({
            system: "你负责为一个剧情地图生成单个地点资料。只返回一个JSON对象，且只允许三个字符串字段：名称、分类、信息。不要输出变量路径、JSON Patch、世界书标签、Markdown或多个地点。",
            user: "地图范围：" + (scope === "school" ? "学校" : "城市/区域") + "\\n已有地点名：" + (values.name || "未填写") + "\\n已有分类：" + (values.category || "未填写") + "\\n已有说明：" + (values.info || "未填写") + "\\n请结合当前剧情与相关世界书补全一个不重复、可用于后续剧情的地点。",
            note: values.note
          });
          const generated = parseConnectorJsonObject(text);
          const filled = graphFillAddForm(card, generated);
          page.dataset[statusKey] = filled.name ? "插头已补全，请确认后保存。" : "插头返回缺少地点名，请手动补充。";
          const hint = card?.querySelector(".st-graph-add-hint:last-of-type");
          if (hint) hint.textContent = page.dataset[statusKey];
        } catch (error) {
          page.dataset[statusKey] = "插头补全失败：" + String(error?.message || error || "未知错误");
          const hint = card?.querySelector(".st-graph-add-hint:last-of-type");
          if (hint) hint.textContent = page.dataset[statusKey];
        } finally {
          button.disabled = false;
          button.textContent = "插头补全";
        }
      });
    });
    page.querySelectorAll("[data-graph-add-submit]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        if (!isLatestPhoneVariableView()) return;
        const location = saveGraphAddForm(page, button);
        if (location) rerenderGraphHost(page);
        else {
          const card = button.closest("[data-graph-add-scope]");
          const scope = graphSupplementScope(button.getAttribute("data-graph-scope") || "world");
          const hint = card?.querySelector(".st-graph-add-hint:last-of-type");
          if (hint) hint.textContent = page.dataset[graphAddStatusDatasetKey(scope)] || "地点保存失败。";
        }
      });
    });
    page.querySelectorAll("[data-graph-category-scroll]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        const scope = button.getAttribute("data-graph-scope") || "world";
        const direction = Number(button.getAttribute("data-graph-category-scroll") || 1) < 0 ? -1 : 1;
        const tabs = page.querySelector('[data-graph-category-tabs="' + scope + '"]');
        if (!tabs) return;
        const amount = Math.max(120, Math.floor(tabs.clientWidth * 0.72)) * direction;
        try { tabs.scrollBy({ left: amount, behavior: "smooth" }); }
        catch { tabs.scrollLeft += amount; }
      });
    });
    page.querySelectorAll("[data-graph-category-filter]").forEach((button) => {
      button.addEventListener("click", () => {
        const scope = button.getAttribute("data-graph-scope") || "world";
        rememberGraphUiState(page, scope);
        page.dataset[graphCategoryDatasetKey(scope)] = button.getAttribute("data-graph-category-filter") || "";
        rerenderGraphHost(page);
      });
    });
    page.querySelectorAll("[data-graph-favorite-filter]").forEach((button) => {
      button.addEventListener("click", () => {
        const scope = button.getAttribute("data-graph-scope") || "world";
        rememberGraphUiState(page, scope);
        const key = graphFavoriteDatasetKey(scope);
        page.dataset[key] = page.dataset[key] === "true" ? "" : "true";
        rerenderGraphHost(page);
      });
    });
    page.querySelectorAll("[data-graph-suggest-location]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const scope = button.getAttribute("data-graph-scope") || "world";
	        const graph = loadStaticGraph(scope);
	        const id = button.getAttribute("data-graph-suggest-location") || "";
	        const location = graph.locations.find((item) => item.id === id);
	        if (!location) return;
	        if (hasPendingStoryLocationOperation()) {
	          rerenderGraphHost(page);
	          return;
	        }
	        const needsAiSupplement = isGraphPlaceholderLocationInfo(location.info);
	        const supplementFormat = graphLocationSupplementFormat(scope, location);
	        Promise.resolve(appendAppOperation({
	          来源: scope === "school" ? "学校地图" : "地图",
	          操作: "建议剧情地点",
          当前地点变量: getCurrentStoryLocation() || "未知",
          建议地点: {
            地点ID: location.id,
            名称: location.label,
            分类: location.category || "未分类",
            描述: location.info || "暂无地点信息。",
            地图类型: graph.title
          },
          需要AI补充地点描述: needsAiSupplement,
          补充写回格式: needsAiSupplement ? supplementFormat : "",
          地点信息更新格式: "<地点信息更新>" + JSON.stringify({
            地图: scope === "school" ? "school" : "world",
            id: location.id,
            名称: location.label,
            分类: location.category || "未分类",
            信息: "仅当本轮用户行动造成地点环境或用途重大改变时填写新描述"
          }) + "</地点信息更新>",
	          AI执行规范: needsAiSupplement
	            ? "这只是用户希望剧情地点设在这里的建议；前端不能直接改当前地点。AI应按剧情、时间和移动条件判断是否成立，成立时更新/系统/当前地点和/系统/当前事件；/系统/_当前周几、/系统/_当前日程、/系统/_当前特殊日期和/系统/_课程表为前端只读同步字段，AI不要手写这些字段。该地点描述仍是前端占位，本轮必须在回复末尾额外输出一个<新增地点补充>{...}</新增地点补充>单地点JSON，按建议ID补充地点信息/分类；不得输出完整地图JSON，不得删除或重排其他地点。"
	            : "这只是用户希望剧情地点设在这里的建议；前端不能直接改当前地点。AI应按剧情、时间和移动条件判断是否成立，成立时更新/系统/当前地点和/系统/当前事件；/系统/_当前周几、/系统/_当前日程、/系统/_当前特殊日期和/系统/_课程表为前端只读同步字段，AI不要手写这些字段。不合理时可拒绝或延后。通常不要改地点描述；只有用户在该地点的行动造成环境、用途、可进入性或剧情功能出现重大且持续的改变时，才在回复末尾额外输出一个<地点信息更新>{...}</地点信息更新>单地点JSON，供前端低频更新本地地图。不得输出完整地图JSON，不得删除或重排其他地点。"
	        })).then(() => {
	          rerenderGraphHost(page);
	        });
	      });
	    });
    page.querySelectorAll("[data-graph-action]").forEach((button) => {
      button.addEventListener("click", async (event) => {
        event.preventDefault();
        event.stopPropagation();
        const scope = button.getAttribute("data-graph-scope") || "world";
        const action = button.getAttribute("data-graph-action");
        rememberGraphUiState(page, scope);
        if (action === "toggle-favorite") {
          toggleGraphFavorite(scope, button.getAttribute("data-graph-node-id") || "");
        }
        if (action === "delete-node") {
          const nodeId = button.getAttribute("data-graph-node-id") || "";
          const graph = loadStaticGraph(scope);
          const location = graph.locations.find((item) => item.id === nodeId);
          const label = location?.label || nodeId || "这个地点";
          const ok = await encounterConfirm(page, { title: "删除自定义地点", message: "永久删除地点「" + label + "」？\\n\\n此操作会直接删除本浏览器里的自定义地点，删除后无法恢复。", confirmText: "确认删除" });
          if (!ok) return;
          deleteStaticGraphNode(scope, nodeId);
        }
        rerenderGraphHost(page);
      });
    });
    page.querySelector("[data-location-rule-submit]")?.addEventListener("click", async (event) => {
      event.preventDefault();
      event.stopPropagation();
      const layerId = mapBoardLayerId(page);
      const nodes = mapBoardNodeData(layerId);
      const extras = mapBoardExtraLocations(layerId, nodes);
      const target = activeLocationRuleTarget(page, layerId, mapBoardSelectedEntry(page, nodes, extras));
      const input = page.querySelector("[data-location-rule-input]");
      const result = await locationRuleCreateDirect(page, target, input?.value || "");
      page.dataset.locationRuleStatus = result?.message || "";
      if (result?.ok) page.dataset.locationRulePage = "0";
      renderCityMapPage(page);
    });
    page.querySelectorAll("[data-location-rule-page]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const delta = Math.sign(Number(button.getAttribute("data-location-rule-page") || 0));
        const current = Math.max(0, Math.trunc(Number(page.dataset.locationRulePage || 0) || 0));
        page.dataset.locationRulePage = String(Math.max(0, current + delta));
        renderCityMapPage(page);
      });
    });
    page.querySelectorAll("[data-location-rule-delete]").forEach((button) => {
      button.addEventListener("click", async (event) => {
        event.preventDefault();
        event.stopPropagation();
        const id = button.getAttribute("data-location-rule-delete") || "";
        const result = await locationRuleDeleteDirect(page, id);
        page.dataset.locationRuleStatus = result?.message || "";
        renderCityMapPage(page);
      });
    });
    page.querySelectorAll("[data-location-directory-refresh]").forEach((button) => {
      button.addEventListener("click", async (event) => {
        event.preventDefault();
        event.stopPropagation();
        const mode = button.getAttribute("data-location-directory-refresh") || "builtin";
        button.disabled = true;
        page.dataset.locationRuleStatus = "正在覆盖角色卡地点世界书…";
        const result = await refreshMapLocationDirectoryWorldbook(mode);
        page.dataset.locationRuleStatus = result?.ok
          ? ((mode === "custom" ? "新增地点" : "地点") + "世界书已覆盖，共 " + result.count + " 个地点。")
          : ("世界书刷新失败：" + String(result?.reason || "无法写入角色卡世界书"));
        renderCityMapPage(page);
      });
    });
  }

