  function policeBadRecordTraitById(id) {
    return ST_POLICE_BAD_RECORD_TRAITS.find((trait) => trait.id === String(id || "")) || null;
  }

  function policeBadRecordPersonaReference(roleName, role) {
    const profile = roleProfileData(roleName, role || {});
    const details = [profile["社团/职业"], profile["职业"], profile["面部"], profile["头发"], roleEffectValue(role, "心理")]
      .map((item) => String(item || "").replace(/\s+/g, " ").trim())
      .filter(Boolean);
    return (details.join("；") || (String(roleName || "角色") + "既有人设")).slice(0, 240);
  }

  function policeBadRecordValue(trait, mode, direction, roleName, role) {
    const descriptor = mode === "positive" ? trait.positive : mode === "negative" ? trait.negative : "无";
    return {
      "状态": mode === "positive" ? "正 · " + descriptor : mode === "negative" ? "负 · " + descriptor : "无",
      "特调": ""
    };
  }

  function policeBadRecordTuningMaterial(trait, mode, direction, roleName, role) {
    const prompt = mode === "positive" ? trait.positivePrompt : mode === "negative" ? trait.negativePrompt : "不施加该项人格微调，保留角色原有人设中的自然表现。";
    const normalizedDirection = String(direction || "").trim();
    const state = mode === "positive" ? "正 · " + trait.positive : mode === "negative" ? "负 · " + trait.negative : "无";
    const persona = policeBadRecordPersonaReference(roleName, role);
    return trait.id + "：" + state + "；方向=" + (normalizedDirection || "自然收束") + "；提示=" + prompt + "；参考=" + persona;
  }

  function policeBadRecordRosterRoles(roles = getStatsRoles()) {
    return Object.entries(roles && typeof roles === "object" ? roles : {})
      .filter(([name, role]) => name && role && typeof role === "object" && !Array.isArray(role))
      .map(([name, role]) => {
        const obedience = Math.max(0, Number(roleStateValue(role, "服从度", 0)) || 0);
        const possessed = isGhostPossessedHostRole(name);
        const maleRole = isMaleRole(name, role);
        const restricted = ST_NON_OPERABLE_ROLE_NAMES.has(name) || maleRole || possessed;
        const personality = role["劣迹"]?.["性格"];
        const traitStates = ST_POLICE_BAD_RECORD_TRAITS.map((trait) => {
          const unlocked = Boolean(personality && typeof personality === "object" && !Array.isArray(personality) && Object.prototype.hasOwnProperty.call(personality, trait.id));
          return profileBadRecordTraitState(unlocked ? personality[trait.id] : undefined, unlocked);
        });
        return { name, role, obedience, possessed, maleRole, restricted, eligible: obedience >= 100 && !restricted, traitStates };
      })
      .sort((left, right) => left.name.localeCompare(right.name, "zh-Hans-CN"));
  }

  function policeBadRecordEligibleRoles() {
    return policeBadRecordRosterRoles().filter((item) => item.eligible);
  }

  function policeTraitOperationAlreadyQueued(payload) {
    const expected = payload && typeof payload === "object" ? payload : {};
    try {
      const pending = window.__ST_GET_PENDING_OPERATION_INPUT_LOG__?.() || [];
      return pending.some((entry) => {
        const item = entry?.payload || entry;
        if (!item || typeof item !== "object" || String(item["来源"] || "") !== "警视厅" || String(item["操作"] || "") !== "性格特调" || String(item["角色名"] || "") !== String(expected["角色名"] || "")) return false;
        const traits = item["特调请求"] && typeof item["特调请求"] === "object" ? item["特调请求"] : {};
        const traitId = String(expected["性格项"] || "");
        return Boolean(traits[traitId]) || (String(item["性格项"] || "") === traitId);
      });
    } catch {
      return false;
    }
  }

  function policeHqEventControl(page, event, selector) {
    const path = typeof event?.composedPath === "function" ? event.composedPath() : [];
    for (const node of path) {
      if (node === page || !node?.matches?.(selector) || !page.contains(node)) continue;
      return node;
    }
    const fallback = event?.target?.closest?.(selector);
    return fallback && fallback !== page && page.contains(fallback) ? fallback : null;
  }

  async function confirmPoliceTraitOperation(page, roleName, traitId, mode) {
    const configText = mode === "positive" ? "正" : mode === "negative" ? "负" : "无";
    const br = String.fromCharCode(10);
    return encounterConfirm(page, {
      title: "确认性格特调",
      message:
      "确认对“" + roleName + "”进行“" + traitId + "”性格特调？" + br + br +
      "配置：" + configText + br +
      "首次解锁会消耗10星光点；确认后本轮会锁定该角色的性格特调暂存，已特调过的性格只能查看不能再改。",
      cancelText: "取消",
      confirmText: "确认特调"
    });
  }

  async function policeApplyBadRecordTrait(page, roleName, traitId, mode, direction) {
    const trait = policeBadRecordTraitById(traitId);
    if (!page || !trait || !roleName || !["positive", "negative", "none"].includes(mode)) return;
    if (ST_NON_OPERABLE_ROLE_NAMES.has(roleName)) {
      page.dataset.policeTraitNotice = roleName + "不能进行性格特调。";
      rerenderPoliceHeadquartersPreservingScroll(page);
      return;
    }
    if (isMaleRole(roleName, getStatsRoles()?.[roleName])) {
      page.dataset.policeTraitNotice = "男性角色不能进行性格特调。";
      rerenderPoliceHeadquartersPreservingScroll(page);
      return;
    }
    if (isGhostPossessedHostRole(roleName)) {
      page.dataset.policeTraitNotice = ghostPossessedHostBlockedMessage(roleName, "进行性格特调");
      rerenderPoliceHeadquartersPreservingScroll(page);
      return;
    }
    const pendingRole = stagedRetunePendingRole();
    if (pendingRole && pendingRole !== roleName) {
      page.dataset.policeTraitNotice = "本轮暂存已锁定“" + pendingRole + "”，不能混入" + roleName + "的性格特调。";
      rerenderPoliceHeadquartersPreservingScroll(page);
      return;
    }
    if (page.dataset.policeTraitBusy === "1") return;
    if (!await confirmPoliceTraitOperation(page, roleName, trait.id, mode)) {
      page.dataset.policeTraitNotice = "已取消性格特调。";
      rerenderPoliceHeadquartersPreservingScroll(page);
      return;
    }
    page.dataset.policeTraitBusy = "1";
    page.dataset.policeTraitNotice = "正在写入性格特调...";
    rerenderPoliceHeadquartersPreservingScroll(page);
    try {
      const result = await rewardApplySystemMutation((system, stat) => {
        if (Number(system[ST_POLICE_LINE_KEY] ?? 0) !== 2) return { ok: false, message: "警视厅线尚未结束，不能进行性格特调。" };
        const roles = stat?.["角色"] && typeof stat["角色"] === "object" && !Array.isArray(stat["角色"]) ? stat["角色"] : {};
        const role = stat?.["角色"]?.[roleName];
        if (!role || typeof role !== "object" || Array.isArray(role)) return { ok: false, message: "没有找到目标角色变量。" };
        if (ST_NON_OPERABLE_ROLE_NAMES.has(roleName)) return { ok: false, message: roleName + "不能进行性格特调。" };
        if (isMaleRole(roleName, role)) return { ok: false, message: "男性角色不能进行性格特调。" };
        if (String(system?.[ST_GHOST_POSSESSION_SYSTEM_KEY] || "").trim() === roleName && roleName !== ST_GHOST_ROLE_NAME) return { ok: false, message: ghostPossessedHostBlockedMessage(roleName, "进行性格特调") };
        if (Number(roleStateValue(role, "服从度", 0)) < 100) return { ok: false, message: "目标角色服从度未达到100。" };
        const records = role["劣迹"];
        if (records !== undefined && (!records || typeof records !== "object" || Array.isArray(records))) return { ok: false, message: "目标角色的劣迹记录格式异常。" };
        const personality = records?.["性格"];
        if (personality !== undefined && (!personality || typeof personality !== "object" || Array.isArray(personality))) return { ok: false, message: "目标角色的性格记录格式异常。" };
        const unlocked = Boolean(personality && Object.prototype.hasOwnProperty.call(personality, trait.id));
        if (unlocked) return { ok: false, message: trait.id + "已经完成特调，只能查看，不能再次修改。" };
        const starlight = Number(system["星光点"] ?? 0) || 0;
        if (!unlocked && starlight < 10) return { ok: false, message: "星光点不足，首次解锁需要持有10点星光点。" };
        const targetRecords = records || (role["劣迹"] = {});
        const targetPersonality = personality || (targetRecords["性格"] = {});
        targetPersonality[trait.id] = policeBadRecordValue(trait, mode, direction, roleName, role);
        const tuningMaterial = policeBadRecordTuningMaterial(trait, mode, direction, roleName, role);
        if (!unlocked) system["星光点"] = starlight - 10;
        return {
          ok: true,
          message: unlocked ? "已更新" + roleName + "的" + trait.id + "配置。" : "已消耗10星光点解锁并配置" + roleName + "的" + trait.id + "。",
          payload: {
            来源: "警视厅",
            操作: "性格特调",
            变量处理: "协同",
            角色名: roleName,
            性格项: trait.id,
            配置: mode === "positive" ? "正" : mode === "negative" ? "负" : "无",
            特调请求文本: tuningMaterial,
            特调请求: { [trait.id]: tuningMaterial },
            解锁费用星光点: unlocked ? 0 : 10,
            前端处理: "前端已直接写入/角色/" + roleName + "/劣迹/性格/" + trait.id + "/状态，并建立空的/特调占位" + (unlocked ? "；本次不扣费" : "；已扣除10星光点"),
            前端写入路径: ["/角色/" + roleName + "/劣迹/性格/" + trait.id + "/状态", "/角色/" + roleName + "/劣迹/性格/" + trait.id + "/特调"].concat(unlocked ? [] : ["/系统/星光点"]),
            AI写入路径: ["/角色/" + roleName + "/劣迹/性格/" + trait.id + "/特调"],
            变量写入路径: ["/角色/" + roleName + "/劣迹/性格/" + trait.id + "/状态", "/角色/" + roleName + "/劣迹/性格/" + trait.id + "/特调"].concat(unlocked ? [] : ["/系统/星光点"]),
            AI执行规范: "前端已写入/状态并建立空的/特调占位；本次特调必须在当前一次回复内结束。只replace /角色/" + roleName + "/劣迹/性格/" + trait.id + "/特调 为最终角色表现文本，不得原样写入请求或标签，不得重复扣星光点、改写/状态或/系统/_警视厅线。"
          }
        };
      });
      if (!result?.ok) throw new Error(result?.message || "性格特调失败。");
      const payload = {
        ...result.payload,
        不可删除: true,
        locked: true,
        forceLocked: true
      };
      const added = await appendAppOperation(payload);
      const alreadyQueued = !added && policeTraitOperationAlreadyQueued(payload);
      if (!added && !alreadyQueued) {
        throw new Error("性格特调已写入变量，但暂存区写入失败；请重新载入后核对，不会将本次操作标记为已提交。");
      }
      page.dataset.policeTraitNotice = result.message + (added ? " 已锁定到暂存区。" : " 对应锁定记录已在暂存区。");
      delete page.dataset.policeTraitMode;
      delete page.dataset.policeTraitDirection;
    } catch (error) {
      page.dataset.policeTraitNotice = String(error?.message || error || "性格特调失败。");
    } finally {
      delete page.dataset.policeTraitBusy;
      rerenderPoliceHeadquartersPreservingScroll(page);
    }
  }

  function bindPoliceHeadquartersV5Controls(page, root) {
    if (!page || !root || !root.isConnected) return;
    const redraw = () => rerenderPoliceHeadquartersPreservingScroll(page);
    // 特调提交是会改变量的动作，必须在当前页面的捕获阶段单独接管。
    // 该页面会复用地图节点；旧版地图/档案热更新可能残留气泡监听，
    // 不能让它们先吞掉“确认/解锁”。
    try { page.__stPoliceHqActionAbort?.abort(); } catch {}
    const actionCapture = new AbortController();
    page.__stPoliceHqActionAbort = actionCapture;
    page.addEventListener("click", (event) => {
      const cancel = policeHqEventControl(page, event, "[data-police-hq-v5-cancel]");
      if (cancel) {
        event.preventDefault();
        event.stopImmediatePropagation();
        page.dataset.policeTraitEdit = ST_POLICE_BAD_RECORD_TRAITS[0]?.id || "";
        delete page.dataset.policeTraitMode;
        delete page.dataset.policeTraitDirection;
        redraw();
        return;
      }
      const apply = policeHqEventControl(page, event, "[data-police-hq-v5-apply]");
      if (!apply || apply.disabled) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      void policeApplyBadRecordTrait(
        page,
        page.dataset.policeTraitRole || "",
        page.dataset.policeTraitEdit || ST_POLICE_BAD_RECORD_TRAITS[0]?.id || "",
        page.dataset.policeTraitMode || "none",
        String(root.querySelector("[data-police-hq-v5-direction]")?.value || "").slice(0, 240)
      );
    }, { capture: true, signal: actionCapture.signal });
    root.querySelectorAll("[data-police-hq-v5-role]").forEach((button) => {
      button.onclick = (event) => {
        event?.preventDefault?.();
        event?.stopPropagation?.();
        if (!root.isConnected || button.disabled) return;
        page.dataset.policeTraitRole = button.getAttribute("data-police-hq-v5-role") || "";
        // 切换人物不重置正在查看的性格项；只重置尚未写入的编辑草稿。
        delete page.dataset.policeTraitMode;
        delete page.dataset.policeTraitDirection;
        redraw();
      };
    });
    root.querySelectorAll("[data-police-hq-v5-trait]").forEach((button) => {
      button.onclick = (event) => {
        event?.preventDefault?.();
        event?.stopPropagation?.();
        if (!root.isConnected) return;
        const traitId = policeBadRecordTraitById(button.getAttribute("data-police-hq-v5-trait"))?.id;
        if (!traitId) return;
        page.dataset.policeTraitEdit = traitId;
        delete page.dataset.policeTraitMode;
        delete page.dataset.policeTraitDirection;
        redraw();
      };
    });
    root.querySelectorAll("[data-police-hq-v5-mode]").forEach((button) => {
      button.onclick = (event) => {
        event?.preventDefault?.();
        event?.stopPropagation?.();
        if (!root.isConnected) return;
        if (button.disabled) return;
        const mode = button.getAttribute("data-police-hq-v5-mode");
        if (!['positive', 'negative', 'none'].includes(mode)) return;
        page.dataset.policeTraitMode = mode;
        page.dataset.policeTraitDirection = String(root.querySelector("[data-police-hq-v5-direction]")?.value || "").slice(0, 240);
        redraw();
      };
    });
    const direction = root.querySelector("[data-police-hq-v5-direction]");
    if (direction) direction.oninput = () => { page.dataset.policeTraitDirection = String(direction.value || "").slice(0, 240); };
    // 同时监听 pointerup 与 click：一些宿主页面会在点击阶段接管地图按钮，
    // 但指针抬起仍会可靠地到达真实的操作按钮。
    const runAction = (event, action) => {
      if (event?.type === "pointerup" && Number.isFinite(event.button) && event.button !== 0) return;
      event?.preventDefault?.();
      event?.stopImmediatePropagation?.();
      if (action === "cancel") {
        page.dataset.policeTraitEdit = ST_POLICE_BAD_RECORD_TRAITS[0]?.id || "";
        delete page.dataset.policeTraitMode;
        delete page.dataset.policeTraitDirection;
        redraw();
        return;
      }
      if (event?.currentTarget?.disabled || page.dataset.policeTraitBusy === "1") return;
      void policeApplyBadRecordTrait(
        page,
        page.dataset.policeTraitRole || "",
        page.dataset.policeTraitEdit || ST_POLICE_BAD_RECORD_TRAITS[0]?.id || "",
        page.dataset.policeTraitMode || "none",
        String(root.querySelector("[data-police-hq-v5-direction]")?.value || "").slice(0, 240)
      );
    };
    const cancelButton = root.querySelector("[data-police-hq-v5-cancel]");
    const applyButton = root.querySelector("[data-police-hq-v5-apply]");
    if (cancelButton) {
      cancelButton.onclick = (event) => runAction(event, "cancel");
      cancelButton.onpointerup = (event) => runAction(event, "cancel");
    }
    if (applyButton) {
      applyButton.onclick = (event) => runAction(event, "apply");
      applyButton.onpointerup = (event) => runAction(event, "apply");
    }
  }

  function renderPoliceHeadquartersPage(page) {
    if (policeLineValue() !== 2) {
      mapBoardSetLayer(page, "city");
      renderCityMapPage(page);
      return;
    }
    const statData = getLatestStatDataSync();
    const rolesSnapshot = statData?.["角色"] && typeof statData["角色"] === "object" && !Array.isArray(statData["角色"]) ? statData["角色"] : {};
    const roster = policeBadRecordRosterRoles(rolesSnapshot);
    const pendingRetuneRole = stagedRetunePendingRole();
    const candidates = roster.filter((item) => item.eligible && (!pendingRetuneRole || item.name === pendingRetuneRole));
    const selectedName = candidates.some((item) => item.name === page.dataset.policeTraitRole) ? page.dataset.policeTraitRole : (candidates[0]?.name || "");
    if (selectedName) page.dataset.policeTraitRole = selectedName;
    const selected = candidates.find((item) => item.name === selectedName) || null;
    const selectedPersonality = profileBadRecordPersonality(selected?.role || {});
    const editId = policeBadRecordTraitById(page.dataset.policeTraitEdit)?.id || ST_POLICE_BAD_RECORD_TRAITS[0]?.id || "";
    if (editId) page.dataset.policeTraitEdit = editId;
    const editTrait = policeBadRecordTraitById(editId);
    const editValue = editTrait && Object.prototype.hasOwnProperty.call(selectedPersonality, editTrait.id) ? selectedPersonality[editTrait.id] : undefined;
    const editUnlocked = Boolean(editTrait && Object.prototype.hasOwnProperty.call(selectedPersonality, editTrait.id));
    const availableStarlight = Math.max(0, Math.floor(Number(statData?.["系统"]?.["星光点"] ?? 0) || 0));
    const needsUnlock = Boolean(editTrait && !editUnlocked);
    const canUnlock = !needsUnlock || availableStarlight >= 10;
    const storedState = profileBadRecordTraitState(editValue, editValue !== undefined);
    const currentMode = page.dataset.policeTraitMode || (storedState.id === "positive" ? "positive" : storedState.id === "negative" ? "negative" : "none");
    const currentDirection = page.dataset.policeTraitDirection ?? "";
    const rosterHtml = roster.length
      ? roster.map((item) => {
          const accessMarks = item.traitStates.map((state) => '<i class="is-' + escapeAttr(state.id) + '"></i>').join("");
          const stateSummary = item.traitStates.map((state) => state.label).join("、");
          const unavailableReason = pendingRetuneRole && pendingRetuneRole !== item.name ? "本轮暂存已锁定" + pendingRetuneRole : (item.possessed ? ghostPossessedHostBlockedMessage(item.name, "进行性格特调") : (item.eligible ? "" : "服从度未达到100"));
          return '<button type="button" class="st-police-hq-v5-role ' + (item.name === selectedName ? "is-selected" : "") + (unavailableReason ? " is-denied" : "") + '" data-police-hq-v5-role="' + escapeAttr(item.name) + '" aria-label="' + escapeAttr(item.name + "，九项性格状态：" + stateSummary + (unavailableReason ? "，" + unavailableReason : "")) + '"' + (unavailableReason ? ' disabled title="' + escapeAttr(unavailableReason) + '"' : "") + '><strong>' + escapeHtml(item.name) + '</strong><span class="st-police-hq-v5-meter" aria-hidden="true">' + accessMarks + '</span></button>';
        }).join("")
      : '<p class="st-police-hq-v5-empty">当前没有可供读取的角色档案。</p>';
    const traitsHtml = selected
      ? ST_POLICE_BAD_RECORD_TRAITS.map((trait) => {
          const unlocked = Object.prototype.hasOwnProperty.call(selectedPersonality, trait.id);
          const value = unlocked ? selectedPersonality[trait.id] : undefined;
          const state = profileBadRecordTraitState(value, unlocked);
          return '<button type="button" class="st-police-hq-v5-trait is-' + escapeAttr(state.id) + (editTrait?.id === trait.id ? " is-selected" : "") + '" data-police-hq-v5-trait="' + escapeAttr(trait.id) + '" aria-label="' + escapeAttr(trait.id + "：" + state.label) + '"' + '><strong>' + escapeHtml(trait.id) + '</strong><span>' + escapeHtml(state.label) + '</span></button>';
        }).join("")
      : "";
    const currentTuningText = editValue && typeof editValue === "object" && !Array.isArray(editValue)
      ? String(editValue["特调"] || "").trim()
      : "";
    const currentContentHtml = '<section class="st-police-hq-v5-current" aria-label="当前性格特调内容"><strong>当前内容</strong><p>状态：' + escapeHtml(editUnlocked ? storedState.label : "未解锁") + '</p><p>特调：' + escapeHtml(currentTuningText || (editUnlocked ? "等待AI生成。" : "未解锁。")) + '</p></section>';
    const editHtml = selected && editTrait
      ? '<section class="st-police-hq-v5-editor" aria-label="性格特调配置"><header><strong>' + escapeHtml(selected.name + " · " + editTrait.id) + '</strong><span>特调室</span></header>' +
        '<div class="st-police-hq-v5-modes"><button type="button" class="' + (currentMode === "positive" ? "active" : "") + '" data-police-hq-v5-mode="positive"' + (editUnlocked ? " disabled" : "") + '>正·' + escapeHtml(editTrait.positive) + '</button><button type="button" class="' + (currentMode === "negative" ? "active" : "") + '" data-police-hq-v5-mode="negative"' + (editUnlocked ? " disabled" : "") + '>负·' + escapeHtml(editTrait.negative) + '</button><button type="button" class="' + (currentMode === "none" ? "active" : "") + '" data-police-hq-v5-mode="none"' + (editUnlocked ? " disabled" : "") + '>无</button></div>' +
        currentContentHtml +
        '<label for="st-police-hq-v5-direction"><strong>特调方向</strong><textarea id="st-police-hq-v5-direction" name="policeTraitDirection" data-police-hq-v5-direction maxlength="240" placeholder="可选：描述希望在该状态下强化的角色表现。"' + (editUnlocked ? " disabled" : "") + '>' + escapeHtml(String(currentDirection || "")) + '</textarea></label>' +
        '<div class="st-police-hq-v5-actions"><button type="button" data-police-hq-v5-cancel>取消</button><button type="button" class="primary" data-police-hq-v5-apply' + (page.dataset.policeTraitBusy === "1" || !canUnlock || editUnlocked ? " disabled" : "") + (editUnlocked ? ' title="该性格已完成特调，只能查看"' : (needsUnlock ? ' title="首次解锁消耗10星光点"' : "")) + '>' + (editUnlocked ? "已特调" : (needsUnlock ? "10星光点解锁" : "确认")) + '</button></div>' +
      '</section>'
      : '<section class="st-police-hq-v5-editor is-idle" aria-label="性格特调配置"></section>';
    const defaultSceneAsset = selected?.name === ST_POLICE_ATTENTION_ROLE_NAME
      ? ST_POLICE_TRAIT_SELF_SILHOUETTE
      : (ST_POLICE_TRAIT_ROLE_SILHOUETTES[selected?.name] || ST_POLICE_TRAIT_TARGET_SILHOUETTE);
    sceneHydrateSilhouetteForRole(page, "police-trait", selected?.name, () => renderPoliceHeadquartersPage(page));
    const sceneAsset = sceneSilhouetteForRole(selected?.name, "police-trait", defaultSceneAsset);
    const sceneAlt = selected?.name === ST_POLICE_ATTENTION_ROLE_NAME
      ? "九鬼真白主动引导操作的剪影"
      : "九鬼真白与用户共同执行性格特调的剪影";
    page.className = "st-lite-app st-hypnosis-lite-app st-police-hq-v5-app";
    setPhoneActiveApp(page.parentElement, "police-headquarters");
    page.innerHTML = renderLiteHeader(page, { title: "警视厅", html: '<strong>性格特调室</strong>' }) +
      '<main class="st-lite-body st-police-hq-v5-body" data-police-hq-v5-root>' +
      '<section class="st-police-hq-v5-overview" aria-label="警视厅性格特调">' +
        '<aside class="st-police-hq-v5-roster"><header><strong>可调对象</strong><span>服从 ≥ 100</span></header><div class="st-police-hq-v5-roster-list" aria-label="角色列表">' + rosterHtml + '</div></aside>' +
        '<figure class="st-police-hq-v5-scene" data-scene-silhouette-open title="点击管理当前角色剪影"><img src="' + escapeAttr(sceneAsset) + '" alt="' + escapeAttr(sceneAlt) + '"><figcaption>' + escapeHtml(selected?.name || "请选择角色") + '</figcaption></figure>' +
      '</section>' +
      '<section class="st-police-hq-v5-workspace" aria-label="性格参数与内容">' +
        '<section class="st-police-hq-v5-traits"><header><strong>九项性格</strong><span>点击选择</span></header>' + (selected ? '<div class="st-police-hq-v5-trait-grid" aria-label="九项人格参数">' + traitsHtml + '</div>' : '<p class="st-police-hq-v5-empty">达到条件后即可进入特调。</p>') + '</section>' +
        editHtml +
      '</section>' +
      (page.dataset.policeTraitNotice ? '<p class="st-police-hq-v5-notice" role="status" aria-live="polite">' + escapeHtml(page.dataset.policeTraitNotice) + '</p>' : "") +
      (page.dataset.sceneSilhouetteActiveDialog === "police-trait" && selected?.name ? renderSceneSilhouetteDialog("police-trait", selected.name, defaultSceneAsset) : "") +
      '</main>';
    const root = page.querySelector("[data-police-hq-v5-root]");
    bindPoliceHeadquartersV5Controls(page, root);
    bindLiteHeader(page, () => renderPoliceHeadquartersPage(page));
    page.querySelector('[data-lite-action="back"]')?.addEventListener("click", () => { mapBoardSetLayer(page, "city"); renderCityMapPage(page); });
    bindSceneSilhouetteControls(page, "police-trait", selected?.name, defaultSceneAsset, () => renderPoliceHeadquartersPage(page));
  }

  function cityMapPointData() {
    const graph = loadStaticGraph("world");
    const graphById = new Map((graph.locations || []).map((location) => [String(location.id), location]));
    const university = SPECIAL_LOCATION_STATIC_ITEMS.find((item) => item.id === "university");
    return ST_CITY_MAP_POINTS.map((point) => {
      const graphLocation = point.graphId ? graphById.get(String(point.graphId)) : null;
      const specialLocation = point.specialId === "university" ? university : null;
      const unlocked = specialLocation ? specialLocationUnlocked(specialLocation) : true;
      return {
        ...point,
        label: graphLocation?.label || specialLocation?.label || point.label,
        short: point.short || graphLocation?.label || specialLocation?.label || point.label,
        category: point.category || graphLocation?.category || "地点",
        info: graphLocation?.info || specialLocation?.info || point.intro || "暂无地点信息。",
        unlocked
      };
    });
  }

  function cityMapAdditionalLocations() {
    const graph = loadStaticGraph("world");
    const pointIds = new Set(ST_CITY_MAP_POINTS.map((point) => String(point.graphId || point.id)));
    const pointLabels = new Set(ST_CITY_MAP_POINTS.map((point) => String(point.label || point.short || "")));
    const defaultIds = defaultGraphNodeIds("world");
    return (graph.locations || [])
      .filter((location) => {
        const id = String(location.id || "");
        const label = String(location.label || "");
        return id && !defaultIds.has(id) && !pointIds.has(id) && !pointLabels.has(label);
      })
      .slice(0, 16);
  }

  function cityMapSelectedPoint(page, points, extras = []) {
    const selected = String(page?.dataset?.cityMapSelected || "").trim();
    const point = points.find((item) => item.id === selected);
    if (point) return point;
    const extra = extras.find((item) => item.id === selected);
    return extra ? { ...extra, isExtra: true } : null;
  }

  function mapBoardLayerId(page) {
    const id = String(page?.dataset?.mapBoardLayer || "").trim();
    return ST_BOARD_MAP_LAYERS[id] ? id : "city";
  }

  function mapBoardLayer(page) {
    return ST_BOARD_MAP_LAYERS[mapBoardLayerId(page)] || ST_BOARD_MAP_LAYERS.city;
  }

  // 地图、警视厅与医院下层复用同一节点。下层曾复用了催眠页的紫色主题类，
  // 即使切回地图也可能被 !important 背景覆盖；所有地图返回路径都经此处清理。
  function restoreMapSurfaceTheme(page) {
    if (!page) return;
    page.classList.remove(
      "st-police-hq-app",
      "st-police-hq-v5-app",
      "st-hypnosis-lite-app",
      "st-hospital-remodel-app"
    );
    page.classList.add("st-lite-app", "st-city-map-app");
    ["background", "backgroundColor", "backgroundImage", "color", "isolation", "filter"].forEach((property) => {
      page.style.removeProperty(property);
    });
    ["mapSurfaceTheme", "hospitalRemodelTheme", "policeHeadquartersTheme", "pageTheme"].forEach((key) => {
      delete page.dataset[key];
    });
  }

  function applyHospitalRemodelSurfaceTheme(page) {
    if (!page) return;
    // 医院是城市地图下层，不得携带 st-hypnosis-lite-app；后者拥有紫色 !important 背景。
    page.classList.remove("st-police-hq-app", "st-police-hq-v5-app", "st-hypnosis-lite-app");
    page.classList.add("st-lite-app", "st-city-map-app", "st-hospital-remodel-app");
    ["background", "backgroundColor", "backgroundImage", "color", "isolation", "filter"].forEach((property) => {
      page.style.removeProperty(property);
    });
    ["mapSurfaceTheme", "policeHeadquartersTheme", "pageTheme"].forEach((key) => {
      delete page.dataset[key];
    });
    page.dataset.mapSurfaceTheme = "hospital-remodel";
  }

  function mapBoardSetLayer(page, layerId) {
    if (!page || !ST_BOARD_MAP_LAYERS[layerId]) return;
    page.dataset.mapBoardLayer = layerId;
    page.dataset.campusLayer = layerId === "teaching" ? "teaching" : "campus";
    delete page.dataset.mapBoardSelected;
    delete page.dataset.mapBoardLastClick;
    delete page.dataset.mapBoardLastClickAt;
    delete page.dataset.cityMapSelected;
    delete page.dataset.campusSelected;
    delete page.dataset.campusGateSpecial;
    delete page.dataset.mapBoardDrawerOpen;
    delete page.dataset.mapBoardRulesOpen;
    delete page.dataset.mapBoardExtraPage;
    delete page.dataset.mapBoardAddOpen;
    delete page.dataset.policeHeadquartersUnavailable;
  }

  function mapBoardNodeData(layerId, graphSnapshot = null, statSnapshot = null, systemSnapshot = null) {
    const layer = ST_BOARD_MAP_LAYERS[layerId] || ST_BOARD_MAP_LAYERS.city;
    const graph = graphSnapshot || loadStaticGraph(layer.currentScope || "world");
    const stat = statSnapshot && typeof statSnapshot === "object" && !Array.isArray(statSnapshot)
      ? statSnapshot
      : getLatestStatDataSync();
    const system = systemSnapshot && typeof systemSnapshot === "object" && !Array.isArray(systemSnapshot)
      ? systemSnapshot
      : (stat?.["系统"] || null);
    const graphById = new Map((graph.locations || []).map((location) => [String(location.id), location]));
    return (layer.nodes || []).map((node) => {
      const graphLocation = node.graphId ? graphById.get(String(node.graphId)) : null;
      const specialLocation = node.specialId ? specialLocationCatalog().find((item) => item.id === node.specialId) : null;
      const fallback = {
        id: node.graphId || node.specialId || node.id,
        label: node.label || node.short || node.id,
        category: node.category || "地点",
        info: node.info || "暂无地点信息。"
      };
      const location = graphLocation || specialLocation || fallback;
      const unlocked = specialLocation ? specialLocationUnlocked(specialLocation, stat) : true;
      const resolved = {
        ...node,
        location,
        specialLocation,
        unlocked,
        label: location.label || node.label || fallback.label,
        short: node.short || location.label || node.label || fallback.label,
        category: location.category || node.category || fallback.category,
        info: location.info || node.info || fallback.info
      };
      if (layerId === "city" && node.id === "police-headquarters") {
        if (policeLineValue(system) === 2) {
          return {
            ...resolved,
            enter: "police",
            comingSoon: false,
            comingSoonMessage: "",
            info: "警视厅特别对策室的受限终端现已开放。可在此查看服从度达到100的角色，并进行永久性格特调。"
          };
        }
        return {
          ...resolved,
          // 入口始终可点：在线路0/1给出站内提示，而不是错误地显示“待续”。
          enter: "police",
          comingSoon: false,
          comingSoonMessage: ""
        };
      }
      return resolved;
    });
  }

