	  async function settingsImportPayload(payload) {
	    const version = Math.max(1, Math.trunc(Number(payload?.version) || 1));
	    if (version >= 2 && Array.isArray(payload?.chat?.messages)) {
	      const targetScope = settingsCurrentChatScope();
	      if (!targetScope) throw new Error("当前聊天没有稳定存储标识，不能执行覆盖导入。");
	      const sourceScope = String(payload?.frontendStorage?.sourceScope || "").trim();
	      const frontendStorage = settingsObject(payload?.frontendStorage);
	      const rollbackStorage = {
	        localStorage: settingsManagedLocalStorageSnapshot(),
	        sessionStorage: settingsManagedSessionStorageSnapshot(),
	        encounterIndexedDbJson: await settingsEncounterRawStorageSnapshot(),
	        profilePhotoIndexedDb: await settingsProfilePhotoStorageSnapshot()
	      };
	      const chatResult = await settingsReplaceFullChat(payload.chat);
	      try {
	        settingsOverwriteManagedLocalStorage(settingsRemapStorageEntries(frontendStorage.localStorage, sourceScope, targetScope));
	        settingsOverwriteManagedSessionStorage(settingsRemapStorageEntries(frontendStorage.sessionStorage, sourceScope, targetScope));
	        await settingsWriteEncounterRawStorage(settingsRemapStorageEntries(frontendStorage.encounterIndexedDbJson, sourceScope, targetScope));
	        await settingsWriteProfilePhotoStorage(settingsRemapStorageEntries(frontendStorage.profilePhotoIndexedDb, sourceScope, targetScope));
	      } catch (error) {
	        try {
	          settingsOverwriteManagedLocalStorage(rollbackStorage.localStorage);
	          settingsOverwriteManagedSessionStorage(rollbackStorage.sessionStorage);
	          await settingsWriteEncounterRawStorage(rollbackStorage.encounterIndexedDbJson);
	          await settingsWriteProfilePhotoStorage(rollbackStorage.profilePhotoIndexedDb);
	        } catch {}
	        try { await chatResult.rollback?.(); } catch {}
	        throw error;
	      }
	      try { globalThis.__ST_HYPNOOS_DAILY_SCHEDULE_SYNC_SIGNATURE__ = ""; } catch {}
	      try { window.dispatchEvent(new CustomEvent("HYPNOOS_FRONTEND_STORAGE_IMPORTED")); } catch {}
	      try { window.dispatchEvent(new CustomEvent("HYPNOOS_OPERATION_QUEUE_CHANGED")); } catch {}
	      if (typeof chatResult.reload === "function") window.setTimeout(() => Promise.resolve(chatResult.reload()).catch(() => {}), 120);
	      return {
	        ok: true,
	        fullChatImport: {
	          messageCount: chatResult.messageCount,
	          variableLayers: chatResult.variableLayers,
	          storageCount:
	            Object.keys(settingsObject(frontendStorage.localStorage)).length +
	            Object.keys(settingsObject(frontendStorage.sessionStorage)).length +
	            Object.keys(settingsObject(frontendStorage.encounterIndexedDbJson)).length +
	            Object.keys(settingsObject(frontendStorage.profilePhotoIndexedDb)).length
	        },
	        variableImport: { total: chatResult.variableLayers, written: chatResult.variableLayers, skipped: [], mismatched: [] }
	      };
	    }
	    const sections = settingsObject(payload?.sections || payload);
	    const rawStorage = settingsObject(payload?.rawStorage);
	    if (Object.prototype.hasOwnProperty.call(rawStorage, "localStorage")) {
	      settingsOverwriteManagedLocalStorage(rawStorage.localStorage);
	    }
	    if (Object.prototype.hasOwnProperty.call(rawStorage, "encounterIndexedDbJson")) {
	      await settingsWriteEncounterRawStorage(rawStorage.encounterIndexedDbJson);
	    }
	    const rewards = settingsObject(sections.rewards);
	    if (Object.prototype.hasOwnProperty.call(rewards, "state")) {
	      settingsWriteFrontendRewardStateSafe(rewards.state);
	    }
	    if (Object.prototype.hasOwnProperty.call(rewards, "counts")) settingsWriteFrontendRewardCountsSafe(rewards.counts);

    const encounter = settingsObject(sections.encounter);
    if (Object.prototype.hasOwnProperty.call(encounter, "purchases")) await settingsWriteEncounterPurchases(encounter.purchases);
    if (Object.prototype.hasOwnProperty.call(encounter, "packageUnlocks")) await settingsWriteEncounterPackageUnlocks(encounter.packageUnlocks);
    if (Object.prototype.hasOwnProperty.call(encounter, "roleUnlocks")) await settingsWriteEncounterRoleUnlocks(encounter.roleUnlocks);

    const locations = settingsObject(sections.locations);
    if (Object.prototype.hasOwnProperty.call(locations, "world")) saveStaticGraph("world", locations.world);
    if (Object.prototype.hasOwnProperty.call(locations, "school")) saveStaticGraph("school", locations.school);
    const favorites = settingsObject(locations.favorites);
    if (Object.prototype.hasOwnProperty.call(favorites, "world")) writeGraphFavoriteIds("world", new Set(settingsArray(favorites.world)));
    if (Object.prototype.hasOwnProperty.call(favorites, "school")) writeGraphFavoriteIds("school", new Set(settingsArray(favorites.school)));
    if (Object.prototype.hasOwnProperty.call(locations, "updateSeen")) writeSeenGraphUpdateKeys(new Set(settingsArray(locations.updateSeen)));
    if (Object.prototype.hasOwnProperty.call(locations, "specialUnlocks")) {
      try { localStorage.setItem(specialLocationUnlockStorageKey(), JSON.stringify(settingsObject(locations.specialUnlocks))); } catch {}
    }

    const timetable = settingsObject(sections.timetable);
    if (Object.prototype.hasOwnProperty.call(timetable, "overrides")) writeWeeklyTimetable(timetable.overrides);
    if (Object.prototype.hasOwnProperty.call(timetable, "descriptions")) writeWeeklyTimetableDescriptions(timetable.descriptions);

	    const profile = settingsObject(sections.profile);
	    if (Object.prototype.hasOwnProperty.call(profile, "favoriteRoles")) writeFavoriteRoleNames(settingsArray(profile.favoriteRoles));
	    if (Object.prototype.hasOwnProperty.call(profile, "eventMemories")) writeProfileEventMemoryStore(profile.eventMemories);
	    const variables = settingsObject(sections.variables || {});
	    const legacySnapshots = Array.isArray(sections.mvuSnapshots) ? sections.mvuSnapshots : null;
	    const recentMessages = Array.isArray(variables.recentMessages) ? variables.recentMessages : legacySnapshots;
	    const variableImport = Array.isArray(recentMessages) ? await settingsImportRecentMvuSnapshots(recentMessages) : { total: 0, written: 0, skipped: [], mismatched: [] };
	    try { globalThis.__ST_HYPNOOS_DAILY_SCHEDULE_SYNC_SIGNATURE__ = ""; } catch {}
	    try { window.dispatchEvent(new CustomEvent("HYPNOOS_FRONTEND_STORAGE_IMPORTED")); } catch {}
	    try { window.dispatchEvent(new CustomEvent("HYPNOOS_OPERATION_QUEUE_CHANGED")); } catch {}
	    return { ok: true, variableImport };
	  }

