      if (!candidate?.stat || !candidate?.replace) return { ok: false, changed: false, reason: "未读到可写入的MVU变量。" };
      const roles = isPlainObject(candidate.stat["角色"]) ? candidate.stat["角色"] : {};
      if (Object.values(roles).every((role) => roleSevenPagesComplete(role))) return { ok: true, changed: false, reason: "" };
