  function looksLikePhoneHome(root) {
    const rootText = root?.innerText || "";
    return ["催眠APP", "日历", "成就和任务", "库存", "MC匿名版"].every((label) => rootText.includes(label)) &&
      !root.querySelector(".st-mchan-internal-app, .st-calendar-lite-app, .st-timetable-app, .st-clock-app, .st-profile-app, .st-map-app, .st-city-map-app, .st-school-app, .st-special-location-app, .st-camera-app, .st-wallpaper-app, .st-encounter-app, .st-inventory-app, .st-reward-app, .st-hypnosis-lite-app, .st-help-app, .st-settings-app, .st-user-registration-app, .st-gambling-app, .st-placeholder-app");
  }

  function getHomeHeader(root) {
    return root?.querySelector?.('[class*="px-6"][class*="mb-8"]') || root?.firstElementChild?.firstElementChild || null;
  }

  const ST_HOME_AUTHOR_STATUS = "Ramiel";

  function patchHomeAuthorStatus(root) {
    if (!root || !looksLikePhoneHome(root)) return;
    const existing = root.querySelector(".st-home-author-status");
    if (existing?.textContent === ST_HOME_AUTHOR_STATUS) return;
    const rootRect = root.getBoundingClientRect();
    const candidates = Array.from(root.querySelectorAll("span,div,time")).filter((element) => {
      if (element.closest(".st-mchan-internal-app,.st-calendar-lite-app,.st-timetable-app,.st-clock-app,.st-profile-app,.st-map-app,.st-city-map-app,.st-school-app,.st-special-location-app,.st-camera-app,.st-wallpaper-app,.st-encounter-app,.st-inventory-app,.st-reward-app,.st-hypnosis-lite-app,.st-help-app,.st-settings-app,.st-user-registration-app,.st-gambling-app,.st-placeholder-app")) return false;
      const text = element.textContent?.trim() || "";
      if (!element.classList?.contains("st-home-author-status") && !/^\\d{1,2}:\\d{2}$/.test(text)) return false;
      if (element.children.length > 0) return false;
      const rect = element.getBoundingClientRect();
      if (rect.width <= 0 || rect.height <= 0) return false;
      const top = rect.top - rootRect.top;
      const left = rect.left - rootRect.left;
      const fontSize = Number.parseFloat(getComputedStyle(element).fontSize) || 0;
      return top >= 0 && top < 72 && left >= 0 && left < 130 && fontSize <= 28;
    });
    const target = candidates.sort((a, b) => {
      const ar = a.getBoundingClientRect();
      const br = b.getBoundingClientRect();
      return (ar.top - br.top) || (ar.left - br.left);
    })[0];
    if (!target) return;
    target.textContent = ST_HOME_AUTHOR_STATUS;
    target.classList.add("st-home-author-status");
  }

  function pendingOperationCount() {
    try {
      const pending = window.__ST_GET_PENDING_OPERATION_INPUT_LOG__?.();
      const note = String(window.__ST_GET_PENDING_OPERATION_NOTE__?.() || "").trim();
      return (Array.isArray(pending) ? pending.length : 0) + (note ? 1 : 0);
    } catch {
      return 0;
    }
  }

